--Settings of the ini file (GBA-PK_Multiplayer.ini next to this script, the file that also holds the address), read here so that
--nothing is printed before they apply. The file is made when the script is first used (both lines are off):
--  log=on|off            what the script writes to the console of mGBA (default off)
--  debug=on|off          all debug messages of the table above (on) / none of them (default off)
--  debug_<group>=on|off  one group, after "debug": unable_to_connect, network_count, network, card, trade, animation, battle,
--                        scripts, render, position, gametype, nickname, getmenus
MPLogOn = false                          --off unless the ini file says log=on
for name in pairs(DebugMessages) do DebugMessages[name] = false end   --all off unless the ini file turns them on
function MPIniDebugKey(t, k, v)           --a line of the ini file: true when it was one of the log / debug settings
	local s = string.lower(v)
	local on = not (s == "0" or s == "off" or s == "no" or s == "false")
	if k == "log" then t.log = on
	elseif k == "debug" then t.debug = on
	elseif string.sub(k, 1, 6) == "debug_" then
		t.dbg = t.dbg or {}
		t.dbg[string.sub(k, 7)] = on
	else
		return false
	end
	return true
end
function MPApplyDebugIni(t)
	if t.log ~= nil then MPLogOn = t.log end
	if t.debug ~= nil then
		for name in pairs(DebugMessages) do DebugMessages[name] = t.debug end
	end
	for want, on in pairs(t.dbg or {}) do
		for name in pairs(DebugMessages) do
			if string.lower(name) == want then DebugMessages[name] = on end
		end
	end
end
do
	local ok, src = pcall(function() return debug.getinfo(1, "S").source end)
	local path = "GBA-PK_Multiplayer.ini"
	if ok and type(src) == "string" and string.sub(src, 1, 1) == "@" then
		local dir = string.match(string.sub(src, 2), "^(.*[/\\])")
		if dir then path = dir .. path end
	end
	local okf, f = pcall(io.open, path, "r")
	if okf and f then
		local t = {}
		for line in f:lines() do
			local k, v = string.match(line, "^%s*([%w_]+)%s*=%s*(.-)%s*$")
			if k and v ~= "" then MPIniDebugKey(t, string.lower(k), v) end
		end
		f:close()
		MPApplyDebugIni(t)
	end
end
if not MPConsoleWrapped then              --console:log of the whole script goes through MPLogOn
	MPConsoleWrapped = true
	local realConsole = console
	console = setmetatable({}, {__index = function(_, k)
		local f = realConsole[k]
		if type(f) ~= "function" then return f end
		if k == "log" then
			return function(_, ...) if MPLogOn then return f(realConsole, ...) end end
		end
		return function(_, ...) return f(realConsole, ...) end
	end})
end

