--New networking stuff
NetFrameSize = 64
NetWriteMax = 8192           --bytes handed to the socket in one write
NetReadChunk = 2048          --bytes asked from the socket in one read
NetReceiveHz = 120           --sockets are read at most this many times per second (the emulator can run at 900 fps)
NetAcceptHz = 20             --the host looks for new connections at most this many times per second
NetQueueSoft = 32768         --waiting bytes per socket from which position snapshots replace older ones
NetQueueHard = 1048576       --waiting bytes per socket from which the connection is treated as dead and the queue is dropped
NetForwardRaw = true         --the host passes position packets of a client on unchanged (true) or builds them again from its own data (false)
NetOut = setmetatable({}, {__mode = "k"}) --socket -> queue of frames that did not leave yet
NetIn = setmetatable({}, {__mode = "k"})  --socket -> bytes that were read but are not handled yet
NetDefer = false             --true while a frame is running: the queues are written when the frame is over (NetEndFrame)
NetOwnPacket, NetOwnFrame = nil, -1
NetStats = {writes = 0, bytesOut = 0, refused = 0, partial = 0, collapsed = 0, reads = 0, bytesIn = 0, framesIn = 0, skipped = 0, since = os.time()}


