-- A ROM hack is recognised by the CRC32 of the ROM (emu:checksum). A profile gives the addresses that hack needs (found with
-- tas/auto_profile.py by lining up the code of the base game in the hack) and the game it is built on; when the ROM is not in the
-- list the script runs with the tables of the base game as before (FireRed 1.0, LeafGreen 1.0, Ruby / Sapphire 1.0, Emerald).
MPCompat.Force = false          --true: run the script on a ROM with an unknown layout anyway
MPCompat.Verbose = true

local function mpCompatSay(text)
	if MPCompat.Verbose then console:log("Hack: " .. text) end
end

function MPCompat.Crc()
	local ok, s = pcall(function() return emu:checksum(C.CHECKSUM.CRC32) end)
	if not ok or type(s) ~= "string" or #s < 4 then return nil end
	return string.format("%02X%02X%02X%02X", s:byte(1), s:byte(2), s:byte(3), s:byte(4))
end

--the footprint of the script in free ROM space, relative to its base (keypad list ... script data, native code, evolution stub, region name)
local MPCompatFoot = {keypadList = 0, keypadText = 0x100, label = 0x380, multiChoice = 0x3A0, text = 0x3C0, script = 0x400, native = 0x1000,
	evoStub = 0x1200, regionName = 0x1300}
local MPCompatFootSize = 0x1400

local function mpCompatBlank(cart, from, size)
	for a = from, from + size - 4, 4 do
		local w = cart:read32(a)
		if w ~= 0xFFFFFFFF and w ~= 0 then return false end
	end
	return true
end

--true when the places the script writes to are free in this ROM
function MPCompat.DefaultSpaceFree(gid)
	local cart = emu.memory.cart0
	local size = cart:size()
	local ga = gAddress[gid]
	local spots = {{0x8A7FC00, 0x400}, {ga.gScriptData, 0x400}, {ga.gNativeData, 0x200}, {MPFreeRom.evoStub, 0x40}, {MPFreeRom.regionName, 0x40}}
	for _, s in ipairs(spots) do
		local off = s[1] - 0x8000000
		if off + s[2] > size then
			if gid ~= "AXVJ" and gid ~= "AXPJ" then return false end
		elseif not mpCompatBlank(cart, off, s[2]) then
			return false
		end
	end
	return true
end

--finds MPCompatFootSize bytes of 0xFF in the last 4 MB of the ROM, returns the ROM address or nil
function MPCompat.FindFree()
	local cart = emu.memory.cart0
	local size = cart:size()
	local a = (size - MPCompatFootSize) & ~0xFF
	local floor = size - 0x400000
	while a > floor do
		local bad = nil
		for off = a + MPCompatFootSize - 4, a, -4 do
			if cart:read32(off) ~= 0xFFFFFFFF then bad = off break end
		end
		if not bad then return 0x8000000 + a end
		a = (bad - MPCompatFootSize) & ~0xFF
	end
	return nil
end

function MPCompat.Relocate(gid, base)
	MPFreeSpaceShift = MPFreeSpaceShift or {}
	MPFreeSpaceShift[gid] = base - 0x8A7FC00
	local ga = gAddress[gid]
	ga.gMultiChoiceData = base + MPCompatFoot.multiChoice
	ga.gTextData = base + MPCompatFoot.text
	ga.gScriptData = base + MPCompatFoot.script
	ga.gNativeData = base + MPCompatFoot.native
	MPFreeRom.evoStub = base + MPCompatFoot.evoStub
	MPFreeRom.regionName = base + MPCompatFoot.regionName
	MPEvoStubAt = MPFreeRom.evoStub
	MPRegionNameAt = MPFreeRom.regionName
end

--the share of the places of the game the script uses that still hold the game's code / data (0..1, nil when there are no anchors)
function MPCompat.LayoutScore(gid)
	local list = MPCompat.Anchors[gid]
	if not list or #list == 0 then return nil end
	local cart = emu.memory.cart0
	local size = cart:size()
	local hit = 0
	for _, a in ipairs(list) do
		local o = a[1] - 0x8000000
		if o + 8 <= size then
			if string.format("%08X%08X", cart:read32(o), cart:read32(o + 4)) == a[2] then hit = hit + 1 end
		end
	end
	return hit / #list
end

--does the START menu of this ROM look like the one of the game the script has tables for?
function MPCompat.MenuLooksRight(gid)
	local a = MPAddress and MPAddress[gid]
	if not a then return true end
	local cart = emu.memory.cart0
	local o = a.entry - 0x8000000
	if o < 0 or o + 8 > cart:size() then return false end
	if cart:read32(o) == a.text and cart:read32(o + 4) == a.func then return true end
	return cart:read32(o + 4) == a.func     --patched already by an earlier start of the script
end

--applies the profile of this ROM; returns the profile (or nil), and the missing essentials of an incomplete one
function MPCompat.ApplyProfile(gid)
	local crc = MPCompat.Crc()
	local p = crc and MPCompat.Profiles[crc]
	if MPMonSet then MPMonSet(100) end                 --the layout of a Pokemon: the decomp's, unless the profile says otherwise
	MPSpecialMap = {}
	MPNoBattle = false
	MPPatchMap = nil
	MPBufPtr = nil
	MPCtrlEnd = 0x37
	MPScriptExtra = {}
	MPEngine = "00000000"
	if MPBufMetaSaved then setmetatable(MPBufMetaSaved.tbl, MPBufMetaSaved.meta) MPBufMetaSaved = nil end   --the game table's own metatable back
	if not p then return nil, nil, gid end
	if p.base ~= gid then
		if gAddress[p.base] then
			mpCompatSay(string.format("%s is built on %s (the header said %s)", p.name, p.base, gid))
			gid = p.base
		else
			mpCompatSay("profile " .. p.name .. " is for " .. tostring(p.base) .. ", the game is " .. gid)
			return nil, nil, gid
		end
	end
	if p.incomplete and not MPCompat.Force then
		mpCompatSay("profile " .. p.name .. " is incomplete, missing: " .. tostring(p.missing))
		return nil, p.missing, gid
	end
	local n = 0
	for tbl, kv in pairs(p.set or {}) do
		local t = _G[tbl]
		local g = t and t[gid]
		if type(g) == "table" then
			for k, v in pairs(kv) do
				g[k] = v
				n = n + 1
			end
		end
	end
	--the first 7 words of the trainer battle function as they are in this ROM (the Versus stub replaces them and puts them back)
	local b = MPBattleAddress and MPBattleAddress[gid]
	if n > 0 and b and MPBattleOrig and b.start and b.start >= 0x8000000 then
		local cart = emu.memory.cart0
		local o = b.start - 0x8000000
		MPBattleOrig[gid] = {}
		for i = 0, 6 do MPBattleOrig[gid][i + 1] = cart:read32(o + i * 4) end
	end
	if p.specials then MPSpecialMap = p.specials end
	MPNoBattle = p.nobattle and true or false
	MPPatchMap = p.patches
	--a hack with addresses / a layout / patches of its own has a battle engine of its own: the CRC of the ROM names it
	if next(p.set or {}) ~= nil or p.mon or p.patches or p.bufptr or p.cmdextra then MPEngine = crc end
	MPScriptExtra = p.cmdextra or {}
	if p.bufptr and gAddress[p.base] then
		--the battle buffers are inside gBattleResources: the address is read from the pointer each time it is asked for
		MPBufPtr = p.bufptr
		MPCtrlEnd = p.bufptr.finish or 0x37                   --the controller command that ends a link battle (0x37; one more in Exceeded)
		local tbl = gAddress[p.base]
		tbl.gBattleBufferA = nil
		tbl.gBattleBufferB = nil
		local orig = getmetatable(tbl)                       --the table has a metatable (dynamic reads): keep it behind ours
		MPBufMetaSaved = {tbl = tbl, meta = orig}
		setmetatable(tbl, {__index = function(t, k)
			local b = MPBufPtr
			if b and (k == "gBattleBufferA" or k == "gBattleBufferB") then
				local ptr = emu:read32(b.addr)
				if ptr < 0x02000000 or ptr >= 0x02040000 then return 0x02000100 end      --no battle: nothing real there
				return ptr + (k == "gBattleBufferA" and b.a or b.b)
			end
			local oi = orig and orig.__index
			if type(oi) == "function" then return oi(t, k) end
			return rawget(t, k)
		end})
	end
	if p.mon and MPMonSet then
		MPMonSet(p.mon.size, p.mon.hp)
		mpCompatSay(string.format("a Pokemon of this game has %d bytes (the decomp's: 100)", p.mon.size))
	end
	mpCompatSay(string.format("recognised: %s (%d addresses set, CRC %s)", p.name, n, crc))
	return p, nil, gid
end

--called from StartScript after the game was detected: returns "ok" or "disable", a message, the game id to use
function MPCompat.Start(gid)
	local p, missing, newgid = MPCompat.ApplyProfile(gid)
	gid = newgid or gid
	if missing and not MPCompat.Force then
		return "disable", "This ROM is a hack the script only knows in part (missing: " .. missing .. "): the script stays off. " ..
			"MPCompat.Force = true in the file tries anyway.", gid
	end
	--the menus go to free ROM space: the place of the game when it is free, else a block of 0xFF at the end of the ROM
	local base = rawget(_G, "MPCompatBase")          --chosen at an earlier start of the script in this session: keep it
	if base or not MPCompat.DefaultSpaceFree(gid) then
		base = base or MPCompat.FindFree()
		_G.MPCompatBase = base
		if base then
			MPCompat.Relocate(gid, base)
			mpCompatSay(string.format("the ROM uses the space the script wants: everything is written at 0x%X instead", base))
		else
			mpCompatSay("no free space found in the last 4 MB of the ROM: menus will overwrite data of the game")
		end
	end
	if not p and not MPCompat.Force then
		local score = MPCompat.LayoutScore(gid)
		if score and score < 0.5 then
			return "disable", string.format("This ROM is a hack built on a different layout (%d%% of the places the script uses are the game's) and " ..
				"there is no profile for it: the script stays off. (MPCompat.Force = true tries anyway.)", math.floor(score * 100)), gid
		end
		if not score and not MPCompat.MenuLooksRight(gid) then
			return "disable", "This ROM is a hack whose START menu the script does not know (no profile for it): the script stays off. " ..
				"(MPCompat.Force = true tries anyway.)", gid
		end
	end
	return "ok", p and p.name or nil, gid
end

--called by StartScript (after GetGameVersion): the profile of the hack, free space, layout gate
function MPCompatStart()
	if not EnableScript then return end
	local ok, status, msg, gid = pcall(MPCompat.Start, GameID)
	if not ok then
		console:log("Hack profile: " .. tostring(status))
		return
	end
	if gid and gid ~= GameID then GameID = gid end
	if status == "disable" then
		EnableScript = false
		console:log(msg)
		if ConsoleForText then ConsoleForText:print(msg) end
	end
end
