function Player:ReadBattleVar()
	if self.BattleVars.Buffer_ID > 0 then
		--if not sending, copy data
		self.BattleVars.Attacker = emu:read8(gAddress[GameID].gBattlerAttacker)
		self.BattleVars.Target = emu:read8(gAddress[GameID].gBattlerTarget)
		self.BattleVars.Absent_Battler = emu:read8(gAddress[GameID].gAbsentBattlerFlags)
		self.BattleVars.Effect_Battler = emu:read8(gAddress[GameID].gEffectBattler)
		self.BattleVars.Buffer_A = {}
		self.BattleVars.Buffer_B = {}
		self.BattleVars.Battleflags = {}

		local buffer_place = 0x200*(self.BattleVars.Buffer_ID-1)
		for i=1, 256 do
			self.BattleVars.Buffer_A[i] = emu:read8(gAddress[GameID].gBattleBufferA+(i-1)+buffer_place)
		end
		for i=1, 256 do
			self.BattleVars.Buffer_B[i] = emu:read8(gAddress[GameID].gBattleBufferB+(i-1)+buffer_place)
		end
	end
	for i=1, 4 do
		self.BattleVars.Battleflags[i] = emu:read8(gAddress[GameID].gBattleControllerExecFlags+i-1)
	end
end

function Player:SetBattleVar(battle)
	self.BattleVars = battle or self.BattleVars
end

function Player:SetBattleVar2(battle)
	self.BattleVars2 = battle or self.BattleVars2
end

function Player:SetBattleVarBuffer(transfer_stage, buffer_a, buffer_b)
	local transfer_stage = transfer_stage or 1
	transfer_stage = transfer_stage + self.BattleVars.Transfer_Stage
	local bufferaplace = 30 + 20*(transfer_stage-1)
	local bufferbplace = 0 + 20*(transfer_stage-1)
	if buffer_a then
		for i=1, 20 do
			self.BattleVars.Buffer_A[i+bufferaplace] = buffer_a[i]
		end
	end
	if buffer_b then
		for i=1, 20 do
			self.BattleVars.Buffer_B[i+bufferbplace] = buffer_b[i]
		end
	end
	self.BattleVars.Transfer_Stage = transfer_stage
end

function Player:ReduceTimeout(mili)
	self.Timeout = self.Timeout - mili
end

function Player:RefreshTimeout()
	self.Timeout = ClientTimeout
end

function Player:GetTalking()
	return self.IsTalkingTarget
end

function Player:SetTalking(Target, nick)
	self.IsTalkingTarget = Target or self.IsTalkingTarget
	local nickname = nick or false
	if nickname then self.TalkingTargetNick = nick end
end

function Player:GetTalkingNickname()
	return self.TalkingTargetNick
end




































































































































































































































































































































































































































































































































































-- ===========================================================================================================================
-- 8. SPRITE PALETTES
-- ===========================================================================================================================

function ApplyPalette(palette, slot)
	local Palette_unfaded = gAddress[GameID].gPaletteUnfaded + 0x200 --0x200 is objects
	local Palette_faded = gAddress[GameID].gPaletteFaded + 0x200 --0x200 is objects
	local isLoaded = true
	if palette and slot then
		--check if applied
		for i=1, #palette do
			local adr = Palette_unfaded+(slot*32)+((i-1)*2)
			if emu:read16(adr) ~= palette[i] then
				isLoaded = false
			end
		end
		--if not in menu and not applied
		if IsInMenu() == 0 and isLoaded == false then
			for i=1,#palette do
				local adr = Palette_unfaded+(slot*32)+((i-1)*2)
				emu:write16(adr, palette[i])
			end
			for i=1,#palette do
				local adr = Palette_faded+(slot*32)+((i-1)*2)
				emu:write16(adr, palette[i])
			end
		end
	end
end

-- OwnGameSprites palettes. Remote players are drawn through OBJ palette 0 (the local player's). When their
-- Slots 0-11 belong to object events. Free slots are 0xFFFF in sSpritePaletteTag
OGSPalettes = {
	FR   = {0x51F0, 0x21F5, 0x4B1F, 0x3A5B, 0x210F, 0x6908, 0x3CE7, 0x628E, 0x14AD, 0x7FBD, 0x6AD6, 0x25BF, 0x1CF8, 0x2F7F, 0x1E77, 0x0000},
	E_B  = {0x530E, 0x5B5F, 0x4B1F, 0x3A5B, 0x210F, 0x3D27, 0x30E5, 0x28A3, 0x1C82, 0x779B, 0x3B2E, 0x2A49, 0x2D9F, 0x2118, 0x7FFF, 0x0000},
	E_M  = {0x530E, 0x677F, 0x4A9B, 0x3A19, 0x296F, 0x398C, 0x20E5, 0x29B4, 0x1CC9, 0x6F39, 0x234D, 0x12A8, 0x2D9F, 0x2118, 0x7FFF, 0x0000},
	RS_B = {0x530E, 0x5B5F, 0x4B1F, 0x3A5B, 0x210F, 0x3D27, 0x30E5, 0x28A3, 0x1C82, 0x779B, 0x2F1F, 0x2E77, 0x2D9F, 0x2118, 0x7FFF, 0x0000},
	RS_M = {0x530E, 0x677F, 0x4A9B, 0x3A19, 0x296F, 0x398C, 0x20E5, 0x29B4, 0x1CC9, 0x6F39, 0x2F1F, 0x2E77, 0x2D9F, 0x2118, 0x7FFF, 0x0000},
}
OGSTags = {FR = 0xFB00, E_B = 0xFB01, E_M = 0xFB02, RS_B = 0xFB03, RS_M = 0xFB04, HOT = 0xFB10, GRASS = 0xFB11, DIVE = 0xFB12}

--palettes of the overlay sprites (hot springs water, tall grass, dive), looked up when needed
function OGSExtraPalette(key)
	if key == "HOT" then return ActualPalette["RSE"].Hot_Springs
	elseif key == "GRASS" then return ActualPalette["RSE"].Tall_Grass
	elseif key == "DIVE" then return ActualPalette["RSE"].Underwater end
	return nil
end

--sprite table (spriteData id) -> palette key. 1/2 FRLG male/female (same palette), 3/4 Emerald, 5/6 Ruby/Sapphire
OGSTableKey = {[1] = "FR", [2] = "FR", [3] = "E_B", [4] = "E_M", [5] = "RS_B", [6] = "RS_M"}

OGSClaimed = {}
OGSUsed = {}
OGSBottom = {} --screen y of the feet of each drawn remote player (by draw index), for ReorderPlayerOAM

--returns the slot (12-15) holding the palette for key, or nil
function OGSClaim(key)
	local addr = OGSAddress[GameID]
	if not addr or not (OGSPalettes[key] or OGSExtraPalette(key)) then return nil end
	--only in the overworld: battles/contests reuse the table with another layout
	if emu:read8(addr.reserved) < 8 then return nil end
	local tag = OGSTags[key]
	local free = nil
	for slot = 12, 15 do
		local t = emu:read16(addr.tags + slot * 2)
		if t == tag then
			OGSClaimed[key] = slot
			return slot
		elseif t == 0xFFFF and not free then
			free = slot
		end
	end
	if not free then return nil end
	emu:write16(addr.tags + free * 2, tag)
	OGSClaimed[key] = free
	return free
end

--give back claimed slots that are no longer used (call after drawing)
function OGSReleaseUnused()
	local addr = OGSAddress[GameID]
	if not addr then return end
	for key, slot in pairs(OGSClaimed) do
		if not OGSUsed[key] then
			if emu:read16(addr.tags + slot * 2) == OGSTags[key] then
				emu:write16(addr.tags + slot * 2, 0xFFFF)
			end
			OGSClaimed[key] = nil
		end
	end
end

--claims a slot for an overlay palette and loads it. fallback (the old fixed slot 14) when no slot can be claimed
function OGSUseSlot(key, fallback)
	local slot = OGSClaim(key)
	if slot then OGSUsed[key] = true else slot = fallback end
	ApplyPalette(OGSPalettes[key] or OGSExtraPalette(key), slot)
	return slot
end
--slot (0-15) in which the game itself has loaded the object event palette with this tag (overworld only), or nil
function OGSFindLoadedPalette(colors)
	local addr = OGSAddress[GameID]
	if not addr or not colors then return nil end
	if emu:read8(addr.reserved) < 8 then return nil end
	local base = gAddress[GameID].gPaletteUnfaded + 0x200
	for slot = 0, 15 do
		local tag = emu:read16(addr.tags + slot * 2)
		--slots 0-11 are patched by the game WITHOUT a tag (it stays 0xFFFF), so they are always looked at. 12-15 only when in use by
		--the game (not free, not one of ours)
		local usable = (slot < 12) or (tag ~= 0xFFFF and not (tag >= 0xFB00 and tag <= 0xFCFF))
		if usable then
			local same = true
			for i = 2, 16 do --color 0 is transparent
				if emu:read16(base + slot * 32 + (i - 1) * 2) ~= colors[i] then same = false break end
			end
			if same then return slot end
		end
	end
	return nil
end

--is the object palette slot completely black? (never loaded by the game: free to use)
function OGSSlotEmpty(slot)
	local base = gAddress[GameID].gPaletteUnfaded + 0x200 + slot * 32
	for i = 0, 15 do
		if emu:read16(base + i * 2) ~= 0 then return false end
	end
	return true
end

--does the slot hold exactly these colors?
function OGSSlotHolds(slot, colors)
	local base = gAddress[GameID].gPaletteUnfaded + 0x200 + slot * 32
	for i = 2, 16 do
		if emu:read16(base + (i - 1) * 2) ~= colors[i] then return false end
	end
	return true
end

--the already loaded NPC palette (slots 2-5) that is closest in color to "colors", or nil when none is loaded. Empty (black) slots are no palette
function OGSNearestLoaded(colors)
	local addr = OGSAddress[GameID]
	if not addr or not colors then return nil end
	if emu:read8(addr.reserved) < 8 then return nil end
	local base = gAddress[GameID].gPaletteUnfaded + 0x200
	local best, bestDiff = nil, nil
	for slot = 2, 5 do
		if not OGSSlotEmpty(slot) then --NPC palettes are patched into 2-5 without a tag
			local diff = 0
			for i = 2, 16 do --color 0 is transparent
				local a = emu:read16(base + slot * 32 + (i - 1) * 2)
				local b = colors[i] or 0
				diff = diff + math.abs((a & 31) - (b & 31)) + math.abs(((a >> 5) & 31) - ((b >> 5) & 31)) + math.abs(((a >> 10) & 31) - ((b >> 10) & 31))
			end
			if not bestDiff or diff < bestDiff then best, bestDiff = slot, diff end
		end
	end
	return best
end

OGSEmptyClaimed = {} --palette key -> NPC slot (2-5) that was empty and now holds the palette of a server NPC
OGSNPCWarned = {}

--object palette slot for the palette of a server NPC. In this order:
-- 1 the slot this script claimed for it (tag 0xFB00+/0xFC00+ in 12-15)    2 an empty slot it used before, while it is still ours
-- 3 a slot where the game itself has exactly these colors (the map's NPCs, any slot 0-15, nothing is written)
-- 4 an EMPTY (all black) NPC slot 2-5 (written)                           5 a free dynamic slot (12-15, tag 0xFFFF) (written)
-- 6 the closest loaded NPC palette, else palette 0.  Slots 0-1 and 6-11 (player, reflections, special) are never written
function OGSNPCPalette(key)
	local colors = OGSPalettes[key]
	local addr = OGSAddress[GameID]
	local mine = OGSClaimed[key]
	if mine and addr and emu:read16(addr.tags + mine * 2) == OGSTags[key] then
		OGSUsed[key] = true
		ApplyPalette(colors, mine)
		return mine
	end
	local e = OGSEmptyClaimed[key]
	if e then
		if OGSSlotHolds(e, colors) or OGSSlotEmpty(e) then
			ApplyPalette(colors, e)
			return e
		end
		OGSEmptyClaimed[key] = nil --the game loaded something else into it
	end
	local loaded = OGSFindLoadedPalette(colors)
	if loaded then return loaded end
	if addr and emu:read8(addr.reserved) >= 8 then
		local taken = {}
		for _, s in pairs(OGSEmptyClaimed) do taken[s] = true end
		for slot = 2, 5 do --the NPC palette slots of the game, first when one of them is empty
			if not taken[slot] and OGSSlotEmpty(slot) then
				OGSEmptyClaimed[key] = slot
				ApplyPalette(colors, slot)
				return slot
			end
		end
	end
	local claimed = OGSClaim(key)
	if claimed then
		OGSUsed[key] = true
		ApplyPalette(colors, claimed)
		return claimed
	end
	if not OGSNPCWarned[key] then
		OGSNPCWarned[key] = true
		console:log("[NPC palette] no free object palette for " .. tostring(key) .. ", using the closest one that is loaded. palslots() shows them")
	end
	return OGSNearestLoaded(colors) or 0
end

--console: palslots() lists the 16 object palette slots (tag, empty or not, who uses it)
function palslots()
	local addr = OGSAddress[GameID]
	if not addr then console:log("palslots: no addresses for " .. tostring(GameID)) return end
	for slot = 0, 15 do
		local tag = emu:read16(addr.tags + slot * 2)
		local who = ""
		for key, s in pairs(OGSClaimed) do if s == slot then who = who .. " " .. key end end
		for key, s in pairs(OGSEmptyClaimed) do if s == slot then who = who .. " " .. key .. "(empty slot)" end end
		console:log(string.format("slot %2d  tag %04X  %s%s", slot, tag, OGSSlotEmpty(slot) and "EMPTY" or "loaded", who))
	end
end

--palette slot to draw remote player RealID with, or nil to keep palette 0. Decided by the sprite table actually used.
function OGSGetSlot(RealID)
	if not OwnGameSprites then return nil end
	local theirs = OGSTableKey[GetAnimationTableSlot(RealID, 1)]

	local mine = OGSTableKey[gAddress[GameID].sAnimationTable + (PositionData.Gender == 1 and 1 or 0)]

	if not theirs or not mine or mine == theirs then return nil end
	local slot = OGSClaim(theirs)
	if not slot then return nil end
	OGSUsed[theirs] = true
	ApplyPalette(OGSPalettes[theirs], slot)
	return slot
end


-- ===========================================================================================================================
-- 9. PLAYER LIST AND GAME DETECTION
-- ===========================================================================================================================

function FindPlayerByID(id)
	for _, player in pairs(players) do
		if player:GetID() == id then
			return player
		end
	end
	return nil -- return nil if no player is found with the given ID
end

function FindPlayerByNickname(nickname)
	for _, player in pairs(players) do
		if player.Nickname == nickname then
			return player
		end
	end
	return nil -- return nil if no player is found with the given ID
end

function FindFirstFreeID()
	-- Create a table to track which IDs are taken
	if #players == 0 then
		return 1
	end
	local takenIDs = {}
	for _, player in ipairs(players) do
		takenIDs[player:GetID()] = true
	end

	-- Find the first ID that is not taken
	local id = 1
	while takenIDs[id] do
		id = id + 1
	end
	return id
end

function AddTempPlayer(socket)
	local player = Temp_Player:new(socket)
	table.insert(temp_players, player)
end

function RemoveTempPlayer(removeplayer)
	if temp_players then
		for i = #temp_players, 1, -1 do
			if temp_players[i] == removeplayer then
				table.remove(temp_players, i)
			end
		end
		--a connection that never became a player is closed
		NetRelease(removeplayer:GetSocket())
	end
end


function AddPlayer(id, socket, nickname, GameID, startX, startY, direction, mapID, animation, gender, spritetype, entrance, borderx, bordery, connections, animdata, tile)
	local player = Player:new(id, socket, nickname, GameID, startX, startY, direction, mapID, animation, gender, spritetype, entrance, borderx, bordery, animdata, tile)
	table.insert(players, player)
	--UpdatePlayerConsole()
	--if id ~= PlayerID then
	--	console:log("Player " .. nickname .. " has successfully connected")
	--end
	if DebugMessages.Network or DebugMessages.Nickname then console:log("Player " .. id .. " connected, getting nickname") end
end

-- Remove a player by ID
function RemovePlayer(id)
	MPOnPlayerRemoved(id)
	MPVsPlayerRemoved(id)
	BLogAdd("player " .. tostring(id) .. " removed from the player list")
	for i, player in ipairs(players) do
		if player:GetID() == id then
			if id ~= PlayerID then
				console:log("Player " .. player:GetNickname() .. " has been disconnected")
			end
			local playersocket = player:GetSocket()
			table.remove(players, i)
			NetRelease(playersocket) --host: the connection of this client is flushed and closed
			UpdatePlayerConsole()
		end
	end
end

-- Clear a player's variables
function ClearPlayer(id)
	for i, player in ipairs(players) do
		if player:GetID() == id then
			player:Clear()
		end
	end
end

function LoadPalette(source, dest)
	for i=0, 7 do
		emu:write32(dest, ROMCARD:read32(source))
	end
end

