-- ===========================================================================================================================
-- 10c. SCRIPTED EFFECTS OF THE GAME (Fly)
-- ===========================================================================================================================
-- The fly of the game is a field effect: the player does the field move pose, a bird comes, the player jumps on it and they fly off
-- (and the same backwards when the player arrives). Neither the bird nor its path belong to the object of the player, the other players
-- would see the player standing there and then vanish. The sender looks at the tasks of the game (Task_FlyOut / Task_FlyIn are the
-- tasks that run the effect, 3 bits of the step counter byte of the position packet say which one runs) and the receiver plays the
-- frames that were recorded from the real game (move_tools/56_fx.lua, build_fly.py): the pose and the place of the player and the
-- sprite of the bird, relative to the place of the player on its screen.
MPFxBank = 960            --first tile of the images of effects (64 tiles at the end of the tiles of the objects)
MPFxOwner = nil           --the player that uses them now (one effect at a time)

--kinds of the packet that play a spin (spin_data.lua) and the order of the spin: down, left, up, right
MPFxSpinKind = {[44] = "rope_out", [45] = "rope_in", [46] = "tele_out", [47] = "tele_in"}
MPFxSpinCycle = {1, 3, 2, 4}
MPFxSpinPos = {[1] = 0, [3] = 1, [2] = 2, [4] = 3}

--the picture (image number of the sheet) that the sprite of the player shows now: the frame of the animation command that is under way
--(sprite: anims at +8, animNum +0x2A, animCmdIndex +0x2B). nil when it cannot be read
function MPFxSpriteBase()
	local gi = gAddress[GameID]
	if not gi or not gi.gPlayerAvatar or not gi.gSpriteData then return nil end
	local sid = emu:read8(gi.gPlayerAvatar + 4)
	if sid >= 64 then return nil end
	return gi.gSpriteData + sid * 0x44
end

function MPFxSpriteImage()
	local base = MPFxSpriteBase()
	if not base then return nil end
	local anims = emu:read32(base + 8)
	if anims < 0x08000000 or anims >= 0x0A000000 then return nil end
	local num = emu:read8(base + 0x2A)
	if num > 31 then return nil end
	local arr = emu:read32(anims + 4 * num)
	if arr < 0x08000000 or arr >= 0x0A000000 then return nil end
	local idx = emu:read8(base + 0x2B)
	local v = emu:read16(arr + 4 * idx)
	if v >= 0x8000 and idx > 0 then v = emu:read16(arr + 4 * (idx - 1)) end      --the end of the animation: the last picture stays
	if v >= 0x8000 then return nil end
	return v
end

--0 nothing, 1 the player flies away, 2 the player arrives by air, 4 - 7 the picture of the fishing rod (the game shows picture 0 - 3 of
--its direction: take out 0 1 2 3, hooked 2 3 2 3 .., put away 3 2 1 0) while the player uses the fishing sprite
MPFxFishLast = 4
function MPFxFishKind()
	local v = MPFxSpriteImage()
	if v and v < 12 then MPFxFishLast = 4 + (v & 3) end
	return MPFxFishLast
end

--the player walks against something (the game: walking in place, 32 frames: 16 with a leg forward, 16 standing; the other leg the next
--time). Movement action 25 - 28 (Emerald, Ruby, Sapphire) / 33 - 36 (FireRed, LeafGreen). While the sprite shows a leg picture (sheet
--pictures 3, 5, 7 = first leg, 4, 6, 8 = second leg of down, up, side) the kind is 3 / 4, while it stands it is 0
function MPFxBumpAction(ab, st)
	if not ab then return false end
	local gi = gAddress[GameID]
	local bike = (st == 1 or st == 5)
	if gi and gi.sGameType == "RSE" then
		if bike then return ab >= 29 and ab <= 32 end
		return ab >= 25 and ab <= 28
	end
	if bike then return ab >= 37 and ab <= 40 end
	return ab >= 33 and ab <= 36
end

--the pose of an extra sprite sheet (watering the berries, the VS Seeker): the sprite points at its picture table; the kind is
--8 + 9 * group + picture number (groups of gfx_data.lua)
function MPFxGfxKind()
	local pt = MPGfxPtr and MPGfxPtr[GameID]
	if not pt then return nil end
	local base = MPFxSpriteBase()
	if not base then return nil end
	local g = pt[emu:read32(base + 0xC)]
	if not g then return nil end
	local v = MPFxSpriteImage()
	if v and v < 9 then return 8 + g * 9 + v end
	return nil
end

function MPFxSenderKind(st, ab, menu)
	if st == 4 then return MPFxFishKind() end
	MPFxFishLast = 4
	if (st == 0 or st == 1 or st == 5) and (menu or 0) == 0 and MPFxBumpAction(ab, st) then
		local v = MPFxSpriteImage()
		if v and v >= 3 and v <= 8 then return (v % 2 == 1) and 3 or 4 end
		return 0
	end
	local a = GameID and MPFxTaskAddr and MPFxTaskAddr[GameID]
	if a then
		for i = 0, 15 do
			local t = a.tasks + i * 0x28
			if emu:read8(t + 4) ~= 0 then
				local f = emu:read32(t)
				if f == a.out then return 1 end
				if f == a["in"] then return 2 end
				if f == a.ro then return 44 end             --Escape Rope / Dig: spin away, spin and blink on arrival
				if f == a.ri then return 45 end
				if f == a.to then return 46 end             --Teleport: spin and rise, spin and drop
				if f == a.ti then return 47 end
			end
		end
	end
	return MPFxGfxKind() or 0
end

--the pictures of the extra sheets are put into the sprite tables of the mod (ids 120 + 10 * group + picture) when they are first needed
MPFxGfxReady = {}
function MPFxInstallGfx(fam, g)
	local key = fam .. g
	if MPFxGfxReady[key] then return end
	MPFxGfxReady[key] = true
	local sheet = MPGfx[fam][g]
	local tabs = (fam == "RSE") and {3, 4} or {1, 2}        --male / female table of Emerald / FireRed
	for gender = 1, 2 do
		local t = spriteData[tabs[gender]]
		local gsh = sheet and sheet[gender]
		if t and gsh then
			for i, words in ipairs(gsh.pics) do
				t[120 + g * 10 + i] = {Animation = "Pose " .. g .. "." .. i, Size = gsh.size, Slot = 1, Palette = 0, RawData = words}
			end
		end
	end
end

--the effect of the player of this frame (called at the end of every animation call of the player)
function MPFxApply(self, mv)
	local kind = self.FxKind or 0
	if kind ~= (mv.fxKind or 0) then
		mv.fxKind = kind
		mv.fx = nil
		mv.spin = nil
		local sn = MPFxSpinKind[kind]
		if sn and MPFxSpin then
			local gi = gAddress[self.GameID]
			local fam = (gi and gi.sGameType == "FRLG") and "FRLG" or "RSE"
			local data = MPFxSpin[fam] and MPFxSpin[fam][sn]
			if data then mv.spin = {t = 0, data = data, pos = MPFxSpinPos[MPMv.IdxOf[self.RDir or 4] or 1] or 0} end
		end
		if (kind == 1 or kind == 2) and MPFxFly then
			local gi = gAddress[self.GameID]
			local fam = (gi and gi.sGameType == "FRLG") and "FRLG" or "RSE"
			mv.fx = {t = 0, ph = (kind == 1) and "out" or "in", fam = fam}
		end
	end
	mv.fxd = nil
	--Escape Rope / Dig / Teleport: spin (the direction steps through down, left, up, right), rise, blink: recorded / simulated frames
	local sp = mv.spin
	if sp then
		sp.t = sp.t + 1
		local i = math.min(sp.t, sp.data.n)
		local ended = sp.t > sp.data.n
		local vis = sp.data.v:sub(i, i) == "1"
		if ended and kind == 46 then vis = false end                 --the player is gone after the rise
		if not vis then
			mv.fxd = {hide = true}
		else
			local di = MPFxSpinCycle[(sp.pos + sp.data.d[i]) % 4 + 1]
			local pose = (di == 1) and 3 or ((di == 2) and 2 or 1)
			mv.fxd = {body = {112, 56 + (sp.data.y[i] or 0), pose, (di == 4) and 1 or 0}}
			local id = self.PlayerID
			drawplayertable[id] = nil
			AddDrawPlayer(id, pose, self.Gender)
		end
		return
	end
	--fishing: the picture of the rod is the one the game shows at this moment (sent as the kind 4 - 7)
	if self.RST == 4 and kind >= 4 and kind <= 7 and (self.RAnim or 0) >= 81 and self.RAnim <= 88 then
		local base = ({[81] = 46, [85] = 46, [82] = 50, [86] = 50})[self.RAnim] or 42
		local t = drawplayertable[self.PlayerID]
		if t then
			for i = #t, 1, -1 do
				if t[i].SpriteSlot == 1 then table.remove(t, i) end
			end
		end
		AddDrawPlayer(self.PlayerID, base + (kind - 4), self.Gender)
	end
	--an extra sheet of the player (watering, VS Seeker): the picture of the sender, from the sheet read from the ROM
	if kind >= 8 and kind < 8 + 27 and MPGfx then
		local g, k = (kind - 8) // 9, (kind - 8) % 9
		local gi = gAddress[self.GameID]
		local fam = (gi and gi.sGameType == "FRLG") and "FRLG" or "RSE"
		local sheet = MPGfx[fam] and MPGfx[fam][g]
		local gsh = sheet and sheet[(self.Gender == 1) and 2 or 1]
		if gsh and gsh.map[k + 1] then
			MPFxInstallGfx(fam, g)
			local tab = drawplayertable[self.PlayerID]
			if tab then
				for i = #tab, 1, -1 do
					if tab[i].SpriteSlot == 1 then table.remove(tab, i) end
				end
			end
			AddDrawPlayer(self.PlayerID, 120 + g * 10 + gsh.map[k + 1], self.Gender)
		end
	end
	--walking in place against something: the leg picture that the game shows (kind 3 = first leg, 4 = second leg); the standing half is
	--the ordinary standing pose
	if (kind == 3 or kind == 4) and (self.RST == 0 or self.RST == 1 or self.RST == 5) and not mv.step then
		local di = MPMv.IdxOf[self.RDir or 4] or 1
		local ids = (self.RST == 0) and MPMv.Pose.walk[di] or MPMv.Pose.bike[di]
		local tab = drawplayertable[self.PlayerID]
		if tab then
			for i = #tab, 1, -1 do
				if tab[i].SpriteSlot == 1 then table.remove(tab, i) end
			end
		end
		local leg = (kind == 3) and 2 or 3
		local gi2 = gAddress[self.GameID]
		if self.RST ~= 0 and gi2 and gi2.sGameType == "RSE" then leg = (kind == 3) and 3 or 2 end    --the two cycle pictures of the Hoenn bikes are named the other way round (measured)
		AddDrawPlayer(self.PlayerID, ids[leg], self.Gender)
	end
	local fx = mv.fx
	if not fx then return end
	local data = MPFxFly[fx.fam][fx.ph]
	fx.t = fx.t + 1
	local f = data.frames[fx.t]
	if not f then
		mv.fxd = {hide = true}                                   --the effect is over, the screen goes black / the map changes
		return
	end
	if f.b then
		mv.fxd = {body = f.b, bird = f.d}
		local id = self.PlayerID
		drawplayertable[id] = nil
		AddDrawPlayer(id, f.b[3] or 36, self.Gender)
	elseif fx.t < data.first and fx.ph == "out" then
		mv.fxd = {bird = f.d}                                    --still standing there
	else
		mv.fxd = {hide = true, bird = f.d}                       --not on the screen (or hidden by the game): only the bird
	end
	if f.d then
		local img = MPFxFly[fx.fam].images[f.d[3]]
		if img and (MPFxOwner == nil or MPFxOwner == self.PlayerID) then
			MPFxOwner = self.PlayerID
			spriteData[1006] = spriteData[1006] or {}
			spriteData[1006][f.d[3]] = spriteData[1006][f.d[3]] or {Size = img.size, Slot = 2, RawData = img.words}
			AddDrawSprite(self.PlayerID, 2, 1006, f.d[3], 0, 0)
		end
	end
end

--the end of the effect of a player gives the tiles back
function MPFxRelease(id)
	if MPFxOwner == id then MPFxOwner = nil end
end

--the sprite of the bird in the block of the player (called at the end of DrawPlayerRaw)
function MPFxDrawBird(id, addr, fx, fy, palette)
	local p = FindPlayerByID(id)
	local mv = p and p.Mv
	local fxd = mv and mv.fxd
	local d = fxd and fxd.bird
	if not d or not GetSlotUsed(id, 2) or GetAnimationTableSlot(id, 2) ~= 1006 then return end
	local refx, refy = 112, 56
	if fxd.body then refx, refy = fxd.body[1], fxd.body[2] end
	local x, y = fx + d[1] - refx, fy + d[2] - refy
	local size = GetAnimationSizeSlot(id, 2)
	local shape, sz = 0, 2                                      --32x32
	if size == "64x64" then sz = 3 elseif size == "16x32" then shape, sz = 2, 1 end
	local spriteSize = shape * 64                               --attribute 0, high byte: shape (+ rotation / scaling)
	local facing = sz * 64                                      --attribute 1, high byte: size (+ flips / matrix)
	local aff = d[7]
	if aff then
		spriteSize = spriteSize | 3                              --rotation / scaling with a double sized area
		facing = facing | (31 << 1)                              --matrix 31 (entries 124 .. 127 of the OAM, nothing else uses them)
		local base = OGSOamBase()
		for k = 1, 4 do emu:write16(base + (124 + k - 1) * 8 + 6, aff[k] & 0xFFFF) end
	else
		if d[5] == 1 then facing = facing | 16 end
		if d[6] == 1 then facing = facing | 32 end
	end
	local construct = (palette * 4096) + (d[4] * 1024) + MPFxBank
	WriteToSpriteList(addr + 16, x, y, facing, spriteSize, construct, 0, 0, 0)
end


