function HandleSprite(id, Animation, Gender, animate, menu, tile)
	local AnimateID = 0

	--stand still
	if Animation == 1 then AddDrawPlayer(id,3,Gender) AnimateID = 251
	elseif Animation == 2 then AddDrawPlayer(id,2,Gender) AnimateID = 252
	elseif Animation == 3 then AddDrawPlayer(id,1,Gender) AnimateID = 253
	elseif Animation == 4 then AddDrawPlayer(id,1,Gender) AnimateID = 254

		--walking
	elseif Animation == 5 then AnimateID = 1
	elseif Animation == 6 then AnimateID = 2
	elseif Animation == 7 then AnimateID = 3
	elseif Animation == 8 then AnimateID = 13

		--turning
	elseif Animation == 9 then AnimateID = 10
	elseif Animation == 10 then AnimateID = 11
	elseif Animation == 11 then AnimateID = 12
	elseif Animation == 12 then AnimateID = 12

		--running
	elseif Animation == 13 then AnimateID = 4
	elseif Animation == 14 then AnimateID = 5
	elseif Animation == 15 then AnimateID = 6
	elseif Animation == 16 then AnimateID = 14

		--bike still
	elseif Animation == 17 then AddDrawPlayer(id,12,Gender) AnimateID = 251
	elseif Animation == 18 then AddDrawPlayer(id,11,Gender) AnimateID = 252
	elseif Animation == 19 then AddDrawPlayer(id,10,Gender) AnimateID = 253
	elseif Animation == 20 then AddDrawPlayer(id,10,Gender) AnimateID = 254

		--bike slow moving
	elseif Animation == 21 then AnimateID = 7
	elseif Animation == 22 then AnimateID = 8
	elseif Animation == 23 then AnimateID = 9
	elseif Animation == 24 then AnimateID = 15

		--bike fast move
	elseif Animation == 25 then AnimateID = 7
	elseif Animation == 26 then AnimateID = 8
	elseif Animation == 27 then AnimateID = 9
	elseif Animation == 28 then AnimateID = 15

		--bike hit wall
	elseif Animation == 29 then AddDrawPlayer(id,12,Gender) AnimateID = 251
	elseif Animation == 30 then AddDrawPlayer(id,11,Gender) AnimateID = 252
	elseif Animation == 31 then AddDrawPlayer(id,10,Gender) AnimateID = 253
	elseif Animation == 32 then AddDrawPlayer(id,10,Gender) AnimateID = 254

		--surf still
	elseif Animation == 33 then AnimateID = 17
	elseif Animation == 34 then AnimateID = 18
	elseif Animation == 35 then AnimateID = 19
	elseif Animation == 36 then AnimateID = 20

		--surf moving
	elseif Animation == 37 then AnimateID = 21
	elseif Animation == 38 then AnimateID = 22
	elseif Animation == 39 then AnimateID = 23
	elseif Animation == 40 then AnimateID = 24

		--wheelie starting no movement
	elseif Animation == 41 then AnimateID = 25
	elseif Animation == 42 then AnimateID = 26
	elseif Animation == 43 then AnimateID = 27
	elseif Animation == 44 then AnimateID = 28

		--wheelie current no movement
	elseif Animation == 45 then AddDrawPlayer(id,59,Gender) AnimateID = 251
	elseif Animation == 46 then AddDrawPlayer(id,63,Gender) AnimateID = 252
	elseif Animation == 47 then AddDrawPlayer(id,55,Gender) AnimateID = 253
	elseif Animation == 48 then AddDrawPlayer(id,55,Gender) AnimateID = 254

		--wheelie down no movement
	elseif Animation == 49 then AnimateID = 29
	elseif Animation == 50 then AnimateID = 30
	elseif Animation == 51 then AnimateID = 31
	elseif Animation == 52 then AnimateID = 32

		--wheelie starting movement
	elseif Animation == 53 then AnimateID = 33
	elseif Animation == 54 then AnimateID = 34
	elseif Animation == 55 then AnimateID = 35
	elseif Animation == 56 then AnimateID = 36

		--wheelie current movement
	elseif Animation == 57 then AnimateID = 37
	elseif Animation == 58 then AnimateID = 38
	elseif Animation == 59 then AnimateID = 39
	elseif Animation == 60 then AnimateID = 40

		--wheelie down movement
	elseif Animation == 61 then AnimateID = 41
	elseif Animation == 62 then AnimateID = 42
	elseif Animation == 63 then AnimateID = 43
	elseif Animation == 64 then AnimateID = 44

		--wheelie jumping no movement
	elseif Animation == 65 then AnimateID = 45
	elseif Animation == 66 then AnimateID = 46
	elseif Animation == 67 then AnimateID = 47
	elseif Animation == 68 then AnimateID = 48

		--wheelie jumping movement
	elseif Animation == 69 then AnimateID = 49
	elseif Animation == 70 then AnimateID = 50
	elseif Animation == 71 then AnimateID = 51
	elseif Animation == 72 then AnimateID = 52

		--throwing pokemon out
	elseif Animation == 80 then AnimateID = 53

		--fishing
	elseif Animation == 81 then AnimateID = 54
	elseif Animation == 82 then AnimateID = 55
	elseif Animation == 83 then AnimateID = 56
	elseif Animation == 84 then AnimateID = 57

		--fishing surfing
	elseif Animation == 85 then AnimateID = 58
	elseif Animation == 86 then AnimateID = 59
	elseif Animation == 87 then AnimateID = 60
	elseif Animation == 88 then AnimateID = 61

		--mach bike
	elseif Animation == 89 then AnimateID = 62
	elseif Animation == 90 then AnimateID = 63
	elseif Animation == 91 then AnimateID = 64
	elseif Animation == 92 then AnimateID = 65

		--underwater (dive): standing
	elseif Animation == 93 then AddDrawPlayer(id,93,Gender) AnimateID = 251
	elseif Animation == 94 then AddDrawPlayer(id,94,Gender) AnimateID = 252
	elseif Animation == 95 then AddDrawPlayer(id,95,Gender) AnimateID = 253
	elseif Animation == 96 then AddDrawPlayer(id,95,Gender) AnimateID = 254
		--underwater (dive): moving down, up, left, right
	elseif Animation == 97 then AnimateID = 66
	elseif Animation == 98 then AnimateID = 67
	elseif Animation == 99 then AnimateID = 68
	elseif Animation == 100 then AnimateID = 69

	elseif Animation == 0 then AnimateID = animate
	else AnimateID = animate
	end

	if menu == 2 then --Battle
		AddDrawSprite(id, 3, 1000, 1) --Fighting Symbol
	elseif menu == 3 or menu == 4 then --Pokemon Menu / Summary
		AddDrawSprite(id, 3, 1001, 1) --Pokeball Symbol
	elseif menu == 5 then --Item Menu
		AddDrawSprite(id, 3, 1002, 1) --Bag Symbol
	end
	if tile == 0x28 then
		AddDrawSprite(id, 2, 1004, 1) --Hot springs
	elseif tile == 0x3 then
		AddDrawSprite(id, 2, 1005, 3) --Long grass (still image; the movement block plays the images)
	end
	return AnimateID
end

function CalculateRelative(OtherGameID, CurrentX, CurrentY, PreviousX, PreviousY, AnimationX, AnimationY, MapID, PreviousMapID, PreviousMapX, PreviousMapY, BorderX, BorderY, PlayerX, PlayerY, PlayerDirection, PlayerMapID, PlayerPrevMapID, PlayerMapDirection, MapDirection, CameraX, CameraY, Entrance, PlayerEntrance, PlayerMapPrevX, PlayerMapPrevY, PlayerBorderX, PlayerBorderY, Accountable, PlayerConnections, PlayerGameID, MatchBanks)
	local AnimationX = AnimationX
	local AnimationY = AnimationY
	--console:log("X: " .. CurrentX .. " Y: " .. CurrentY)
	if PositionData.AnimationData > 0 then
		return 0, 0, 0, 0, 0, 0
	end

	--if in script, calculate relative position of where actual player is
	local TooBusyByte = emu:read8(gAddress[GameID].gLockControls)
	if PositionData.UseMapPos and TooBusyByte then
		local relx = PositionData.CurrentX - PositionData.ActualX
		local rely = PositionData.CurrentY - PositionData.ActualY
		AnimationX = AnimationX + (relx*16)
		AnimationY = AnimationY + (rely*16)
	end

	local OtherPlayerGame = "None"
	local YourGame = gAddress[PlayerGameID].sGameType
	MatchBanks = false
	local FRLG_Games = {BPR1 = true, BPR2 = true, BPG1 = true, BPG2 = true, BPRJ = true, BPGJ = true, BPRF = true, BPGF = true, BPRS = true, BPGS = true, BPRD = true, BPGD = true, BPRI = true, BPGI = true}
	local RSE_Games = {BPEE = true, BPEJ = true, BPEF = true, BPES = true, BPED = true, BPEI = true, AXV1 = true, AXV2 = true, AXP1 = true, AXP2 = true, AXVJ = true, AXPJ = true, AXVF = true, AXPF = true, AXVS = true, AXPS = true, AXVD = true, AXPD = true, AXVI = true, AXPI = true}

	if FRLG_Games[OtherGameID] then OtherPlayerGame = "FRLG" end
	if RSE_Games[OtherGameID] then OtherPlayerGame = "RSE" end

	if PartialSeperateGames then
		local YourBanks, OtherBanks = GetMapBanks(PlayerGameID), GetMapBanks(OtherGameID)
		if YourBanks and OtherBanks then
			local PlayerMap, PlayerLocation = findMapName(YourBanks, PlayerMapID)
			local Map, Location = findMapName(OtherBanks, MapID)
			if PlayerMap and PlayerLocation and Map and Location then
				if PlayerMap == "Pokecenter_Entrance" and Map == "Pokecenter_Entrance" then
					MatchBanks = true
					if DebugMessages.Position then console:log("Pokecenter_Entrance") end
				elseif PlayerMap == "Pokecenter_First_Floor" and Map == "Pokecenter_First_Floor" then
					MatchBanks = true
					if DebugMessages.Position then console:log("Pokecenter_First_Floor") end
				elseif PlayerMap == "Shop" and Map == "Shop" then
					MatchBanks = true
					if DebugMessages.Position then console:log("Shop") end
				end
			end
		end
	end

	if SeperateGames and not MatchBanks then
		if YourGame ~= OtherPlayerGame then
			if DebugMessages.Render then
				console:log("Different game. Your game: " .. YourGame .. " their game: " .. OtherPlayerGame)
			end
			return 0, 0, 0, 0, 0, 0
		end
	end

	local RelativeX, RelativeY = 0, 0

	if DebugMessages.Render then console:log("CAMERAX: " .. PositionData.CurrentCameraX .. " CAMERAY: " .. PositionData.CurrentCameraY) end

	local CameraMax = 256

	local dx = PositionData.CameraXPos
	local dy = PositionData.CameraYPos
	local Visible = 0
	--Route jumping causes camera glitch
	if PositionData.AnimationByte == 12 and dy == 0 and PositionData.PreviousY ~= PositionData.CurrentY then
		dy = 17
	elseif PositionData.AnimationByte == 13 and dy == 0 and PositionData.PreviousY ~= PositionData.CurrentY then
		dy = -17
	elseif PositionData.AnimationByte == 14 and dx == 0 and PositionData.PreviousX ~= PositionData.CurrentX then
		dx = -17
	elseif PositionData.AnimationByte == 15 and dx == 0 and PositionData.PreviousX ~= PositionData.CurrentX then
		dx = 17
	end
	local dx_test = (CameraMax - PositionData.CurrentCameraX) % 16
	local dy_test = (CameraMax - PositionData.CurrentCameraY) % 16
	if PlayerDirection == 1 and dx_test ~= 0 then
		dx = -16 + dx
	elseif PlayerDirection == 3 and dy_test ~= 0 then
		dy = -16 + dy
	end

	if MapID == PlayerMapID or MatchBanks then
		RelativeX = (PreviousX - PlayerX) * 16 + AnimationX + dx
		RelativeY = (PreviousY - PlayerY) * 16 + AnimationY + dy
		Visible = 1
	else
		--NEED LATER
		if PlayerConnections.MapConnectAmount then
			if PlayerConnections.MapConnectAmount > 0 then
				for i=1,PlayerConnections.MapConnectAmount do
					if MapID == PlayerConnections[i].MapID then
						if PlayerConnections[i].Direction == 1 then --down from player
							PosX = PreviousX + PlayerConnections[i].Offset
							PosY = PreviousY + PlayerBorderY
							if DebugMessages.Position then console:log("CONNECTION SOUTH! Y: " .. PosY .. " PLAYER Y: " .. PlayerY) end
							Visible = 1
							RelativeX = (PosX - PlayerX) * 16 + AnimationX + dx
							RelativeY = (PosY - PlayerY) * 16 + AnimationY + dy
							if DebugMessages.Position then console:log("RELATIVE Y: " .. RelativeY) end
						elseif PlayerConnections[i].Direction == 2 then --up from player
							PosX = PreviousX + PlayerConnections[i].Offset
							PosY = PreviousY - BorderY
							if DebugMessages.Position then console:log("CONNECTION NORTH! Y: " .. PosY .. " PLAYER Y: " .. PlayerY) end
							Visible = 1
							RelativeX = (PosX - PlayerX) * 16 + AnimationX + dx
							RelativeY = (PosY - PlayerY) * 16 + AnimationY + dy
							if DebugMessages.Position then console:log("RELATIVE Y: " .. RelativeY) end
						elseif PlayerConnections[i].Direction == 3 then --left from player
							PosX = PreviousX - BorderX
							PosY = PreviousY + PlayerConnections[i].Offset
							Visible = 1
							RelativeX = (PosX - PlayerX) * 16 + AnimationX + dx
							RelativeY = (PosY - PlayerY) * 16 + AnimationY + dy
						elseif PlayerConnections[i].Direction == 4 then --right from player
							PosX = PreviousX + PlayerBorderX
							PosY = PreviousY + PlayerConnections[i].Offset
							Visible = 1
							RelativeX = (PosX - PlayerX) * 16 + AnimationX + dx
							RelativeY = (PosY - PlayerY) * 16 + AnimationY + dy
						end
					end
				end
			end
		end
	end
	--	console:log("RELATIVE X: " .. RelativeX .. " PREV X: " .. PreviousX .. " PLAYER X: " .. PlayerX .. " dx: " .. dx .. " RELATIVE Y: " .. RelativeY .. " PREV Y: " .. PreviousY .. " PLAYER X: " .. PlayerY .. " dy: " .. dy)
	return RelativeX, RelativeY, Visible, MatchBanks
end

function GetAnimationTableBase(id, AnimationID, GenderID)
	local mine = gAddress[GameID]
	if OwnGameSprites then
		local other = FindPlayerByID(id)
		local theirs = other and gAddress[other:GetGameID()]
		if theirs and theirs.sAnimationTable ~= mine.sAnimationTable then
			local add = (GenderID == 1) and 1 or 0
			local t = spriteData[theirs.sAnimationTable + add]
			local l = spriteData[mine.sAnimationTable + add]
			t = t and t[AnimationID]
			l = l and l[AnimationID]
			if t and l and t.Size == l.Size and t.Slot == l.Slot then
				return theirs.sAnimationTable
			end
		end
	end
	return mine.sAnimationTable
end

function AddDrawPlayer(id, AnimationID, GenderID)
	local AnimationTableID = GetAnimationTableBase(id, AnimationID, GenderID)
	local playerIDNum = playerIDNum or 0
	if GenderID == 1 then
		AnimationTableID = AnimationTableID + 1
	end
	local SpriteSizeID = "16x32"
	local SpriteSlotID = 1
	local Sprite = spriteData[AnimationTableID]
	if Sprite then
		if Sprite[AnimationID] then
			SpriteSizeID = Sprite[AnimationID].Size
			SpriteSlotID = Sprite[AnimationID].Slot
		end
	end
	local drawplayertableitem = {
		Animation = AnimationID,
		AnimationTable = AnimationTableID,
		Gender = GenderID,
		SpriteSize = SpriteSizeID,
		SpriteSlot = SpriteSlotID,
	}
	if not drawplayertable[id] then
		drawplayertable[id] = {}
	end
	table.insert(drawplayertable[id], drawplayertableitem)
end


function CreatePlayer(id, tileset)
	if drawplayertable[id] then
		for _, item in ipairs(drawplayertable[id]) do
			createChars(tileset, item.AnimationTable, item.Animation)
		end
	end
end

function AddDrawSprite(id, pos, AnimationTableID, AnimationID, xoffsetID, yoffsetID)
	local SpriteSizeID = "16x16"
	local SpriteSlotID = 3
	local Sprite = spriteData[AnimationTableID]
	if Sprite then
		if Sprite[AnimationID] then
			SpriteSizeID = Sprite[AnimationID].Size
			SpriteSlotID = Sprite[AnimationID].Slot
		end
	end
	local drawspritetableitem = {
		Animation = AnimationID,
		AnimationTable = AnimationTableID,
		SpriteSize = SpriteSizeID,
		SpriteSlot = SpriteSlotID,
		x = xoffsetID,
		y = yoffsetID
	}
	if not drawspritetable[id] then
		drawspritetable[id] = {}
	end
	if not drawspritetable[id][pos] then
		drawspritetable[id][pos] = {}
	end
	drawspritetable[id][pos] = drawspritetableitem
end

function GetDrawSpriteOffsets(pos)
	local x = 0
	local y = 0
	if drawspritetable[id] then
		if drawspritetable[id][pos] then
			if drawspritetable[id][pos].x then x = drawspritetable[id][pos].x end
			if drawspritetable[id][pos].y then y = drawspritetable[id][pos].y end
		end
	end
	return x, y
end

function RefreshDrawSprite(id, pos)
	if drawspritetable[id] then
		if drawspritetable[id][pos] then
			drawspritetable[id][pos] = nil
		end
	end
end

function CreateSprite(id, tileset)
	if drawspritetable[id] then
		for pos, sprite in pairs(drawspritetable[id]) do
			if sprite then
				--	console:log("ID: " .. id .. " POS: " .. pos .. " TAB: " .. sprite.AnimationTable .. " AN: " .. sprite.Animation)
				createChars(tileset, sprite.AnimationTable, sprite.Animation)
			end
		end
	end
end

function AddRenderPlayer(id, OtherGameID2, DrawX2, DrawY2, Animation2, Gender2, SpriteType2, Direction2, Visible2, AnimationFrame2, AnimationCycle2, SurfFrame2, AnimationData2)
	--console:log("ADD PLAYER " .. id .. " TO RENDER. DrawX: " .. DrawX2 .. " DRAWY: " .. DrawY2)
	local FinalX = DrawX2 + 112
	local FinalY = DrawY2 + 56
	local renderplayertableitem = {
		OtherGameID = OtherGameID2,
		FinalMapX = FinalX,
		FinalMapY = FinalY,
		SpriteType = SpriteType2,
		Direction = Direction2,
		Visible = Visible2,
		AnimationFrame = AnimationFrame2,
		AnimationCycle = AnimationCycle2,
		SurfFrame = SurfFrame2,
		AnimationData = AnimationData2,
	}
	renderplayertable[id] = renderplayertableitem
end

function HasAnimationInRange(animstart, animend)
	for id, items in pairs(drawplayertable) do
		for _, item in ipairs(items) do
			--	console:log("ANIM: " .. item.Animation)
			if item.Animation >= animstart and item.Animation <= animend then
				return true
			end
		end
	end
	return false
end

function GetAnimationSlot(id, pos)
	if drawspritetable[id] then
		if drawspritetable[id][pos] then
			return drawspritetable[id][pos].Animation
		end
	end
	if drawplayertable then
		for key, playerData in pairs(drawplayertable) do
			if playerData then
				if key == id then
					for _, item in ipairs(playerData) do
						if item.SpriteSlot == pos then
							return item.Animation
						end
					end
				end
			end
		end
	end
	return 0
end

function GetAnimationTableSlot(id, pos)
	if drawspritetable[id] then
		if drawspritetable[id][pos] then
			return drawspritetable[id][pos].AnimationTable
		end
	end
	if drawplayertable then
		for key, playerData in pairs(drawplayertable) do
			if playerData then
				if key == id then
					for _, item in ipairs(playerData) do
						if item.SpriteSlot == pos then
							return item.AnimationTable
						end
					end
				end
			end
		end
	end
	return 0
end

function GetAnimationSizeSlot(id, pos)
	if drawspritetable[id] then
		if drawspritetable[id][pos] then
			return drawspritetable[id][pos].SpriteSize
		end
	end
	if drawplayertable then
		for key, playerData in pairs(drawplayertable) do
			if playerData then
				if key == id then
					for _, item in ipairs(playerData) do
						if item.SpriteSlot == pos then
							return item.SpriteSize
						end
					end
				end
			end
		end
	end
	return "16x32"
end

function GetSlotUsed(id, pos)
	if drawspritetable[id] then
		if drawspritetable[id][pos] then
			return true
		end
	end
	if drawplayertable then
		for key, playerData in pairs(drawplayertable) do
			if playerData then
				if key == id then
					for _, item in ipairs(playerData) do
						if item.SpriteSlot == pos then
							return true
						end
					end
				end
			end
		end
	end
	return false
end

function RefreshRenderPlayer()
	previousdrawplayertable = drawplayertable
	drawplayertable = {}
	renderplayertable = {}
end

-- OAM layout of remote players.
OGSCap = nil --bytes of the player being drawn, by address
OGSCapBase = 0
OGSTouched = {}
OGSBlock = {} --draw index
OGSTop = 0 --first entry after the last block
OGSNext = 0 --start of the lowest block
OGSPrevLow = nil
OGSValid = false

function OGSOamBase()
	local info = gAddress[GameID]
	if info.gOamBuffer then return info.gOamBuffer end --a game whose gMain is not like the others (Japanese Ruby / Sapphire)
	return info.gMainCallback - 4 + ((info.sGameVersion == "RS") and 0x3C or 0x38) --gMain.oamBuffer
end

function OGSW8(addr, v)
	v = math.floor(v) & 0xFF
	if OGSCap then OGSCap[addr] = v else emu:write8(addr, v) end
end

function OGSW16(addr, v)
	v = math.floor(v) & 0xFFFF
	if OGSCap then
		OGSCap[addr] = v & 0xFF
		OGSCap[addr + 1] = v >> 8
	else
		emu:write16(addr, v)
	end
end

--first tile of the block of the player that is drawn as number `slot` (0, 1, 2 ...)
function MPBankTile(slot)
	if slot < 8 then return 480 - 48 * slot end
	return 528 + 48 * (slot - 8)
end

--how many players can be drawn this frame: the setting, what fits in the OAM entries the game does not use (64 .. tail + 2, 3 each) and
--in the tile banks (18)
function MPDrawLimit(tail)
	if DrawPlayerCount == 0 then return 0 end
	local room = math.max(0, (tail + 3 - 64) // 3)
	if room > 17 then room = 17 end --the tiles of the 18th are the ones of the effects
	if tail + 2 > 127 or tail < 1 then room = 8 end                      --a layout that was not understood: as it was
	if DrawPlayerCount < 0 then return room end
	return math.min(DrawPlayerCount, room)
end

--start of every DynamicRender
function OGSBegin()
	local info = gAddress[GameID]
	local tail = (info.gSprite - OGSOamBase()) // 8 --OAM index of the old player 0 block
	OGSLimit = MPDrawLimit(tail)
	OGSValid = tail >= 1 and tail + 2 <= 127 and OGSLimit * 3 <= tail
	OGSTop = tail + 3
	OGSNext = OGSTop
	OGSBlock = {}
	OGSCap = nil
	if OGSPrevLow == nil then OGSPrevLow = OGSTop - 3 * OGSLimit end
end

--DrawPlayerRaw drew into OGSCap: place the used entries
function OGSCommit(id, cap)
	local m = 0
	for j in pairs(OGSTouched) do
		if j + 1 > m then m = j + 1 end
	end
	if m < 1 then m = 1 end
	local maxLen = 3 --(not 'cap': that is the parameter of this function, the bytes of the block)
	if DynamicOAM and m > 3 and (OGSTop - OGSNext + 4) <= 3 * OGSLimit then maxLen = 4 end
	if m > maxLen or not DynamicOAM then m = maxLen end
	local start = OGSNext - m
	if start < 1 then return end --cannot happen with DrawPlayerCount players, but never write below the layout
	local oamBase = OGSOamBase()
	for j = 0, m - 1 do
		for b = 0, 5 do --attr0-attr2 only. Bytes 6-7 are the affine matrices, which belong to the game
			local v = cap[OGSCapBase + j * 8 + b]
			if v then emu:write8(oamBase + (start + j) * 8 + b, v) end
		end
	end
	OGSBlock[id] = {start = start, len = m}
	OGSNext = start
end

function DrawPlayer(id, ...)
	if not OGSValid then return DrawPlayerRaw(id, ...) end
	OGSCap = {}
	OGSCapBase = gAddress[GameID].gSprite - id * 24
	OGSTouched = {}
	local ok, err = pcall(DrawPlayerRaw, id, ...)
	local cap = OGSCap
	OGSCap = nil --never leave the capture on, other code writes to the OAM directly
	if ok then OGSCommit(id, cap) else error(err, 0) end
end

--end of DynamicRender: park entries that remote players used last frame and do not use now
function OGSParkVacated()
	if not OGSValid then return end
	local low, prev = OGSNext, OGSPrevLow
	if prev and low > prev then
		local oamBase = OGSOamBase()
		for i = math.max(prev, 1), math.min(low, OGSTop) - 1 do
			local base = oamBase + i * 8
			emu:write16(base, 48)
			emu:write16(base + 2, 416) --x = 416 is off screen
			emu:write16(base + 4, 12)
		end
	end
	OGSPrevLow = low
end

--OAM size (width, height) by shape and size bits
OGSOamSize = {
	[0] = {{8, 8}, {16, 16}, {32, 32}, {64, 64}},
	[1] = {{16, 8}, {32, 8}, {32, 16}, {64, 32}},
	[2] = {{8, 16}, {8, 32}, {16, 32}, {32, 64}},
}

--A reflection of the game (the sprite below an object that stands on a puddle / pond / ice: priority 3, rotation / scaling entry) would
--show through the transparent pixels of a remote player that stands on its tile (a player directly above or below another one on a
--puddle: "sky reflection where the other players stand", GitHub #80 / #94; with sunny weather the reflection palette is bright). Such
--an entry is hidden for the frame. Runs before ReorderPlayerOAM (the remote blocks are still where OGSCommit put them).
HideReflectionsUnderPlayers = true
function OGSHideReflections(n)
	if not HideReflectionsUnderPlayers or not n or n < 1 or not OGSValid then return end
	local low, top = OGSNext, OGSTop
	if low >= top then return end
	local oamBase = OGSOamBase()
	local rects = {}
	for k = 0, n - 1 do
		local blk = OGSBlock[k]
		if blk then
			local x0, y0, x1, y1
			for j = 0, blk.len - 1 do
				local base = oamBase + (blk.start + j) * 8
				local a0, a1 = emu:read16(base), emu:read16(base + 2)
				if ((a0 >> 8) & 3) ~= 2 then
					local x, y = a1 & 0x1FF, a0 & 0xFF
					if x >= 256 then x = x - 512 end
					local size = OGSOamSize[(a0 >> 14) & 3]
					size = size and size[((a1 >> 14) & 3) + 1]
					if size and y < 160 and x > -32 and x < 240 then
						x0, y0 = math.min(x0 or x, x), math.min(y0 or y, y)
						x1, y1 = math.max(x1 or (x + size[1]), x + size[1]), math.max(y1 or (y + size[2]), y + size[2])
					end
				end
			end
			if x0 then rects[#rects + 1] = {x0, y0, x1, y1} end
		end
	end
	if #rects == 0 then return end
	for i = 0, math.min(64, low) - 1 do
		local base = oamBase + i * 8
		local a0, a1, a2 = emu:read16(base), emu:read16(base + 2), emu:read16(base + 4)
		--rotation / scaling (not double size, not hidden), normal mode, the lowest priority: what the game makes a reflection of
		if (a0 & 0x300) == 0x100 and ((a0 >> 10) & 3) == 0 and ((a2 >> 10) & 3) == 3 then
			local x, y = a1 & 0x1FF, a0 & 0xFF
			if x >= 256 then x = x - 512 end
			local size = OGSOamSize[(a0 >> 14) & 3]
			size = size and size[((a1 >> 14) & 3) + 1]
			if size and y < 160 and size[1] >= 16 then
				for _, r in ipairs(rects) do
					local ow = math.min(x + size[1], r[3]) - math.max(x, r[1])
					local oh = math.min(y + size[2], r[4]) - math.max(y, r[2])
					if ow >= 8 and oh >= 8 then
						emu:write16(base, (a0 & ~0x300) | 0x200)             --hidden
						break
					end
				end
			end
		end
	end
end

--Remote players are at the end of the OAM buffer. Lower OAM index = in front among sprites of the same priority.
--This moves each remote player's entries to where the game would have put it:
--  * before the first semi-transparent sprite (fog), otherwise the blending of that sprite is stripped from our pixels
--  * (YSortPlayers) before the first sprite of the same priority that stands further north (its feet are higher on screen),
--    so players walk in front of/behind NPCs and each other like in the game. The game's OAM list is already sorted this way.
--Only the game's entries (0-63) and the remote player block are involved. Entries in between belong to nobody and stay.
--Only attr0-attr2 are moved. The 4th halfword of each entry belongs to the affine matrices, which must stay where they are.
function ReorderPlayerOAM(n)
	if not n or n < 1 or not OGSValid then return end
	local low, top = OGSNext, OGSTop
	if low >= top then return end
	local oamBase = OGSOamBase()
	local G = math.min(64, low)
	local pos = {} --slot -> OAM index
	for i = 0, G - 1 do pos[#pos + 1] = i end
	for i = low, top - 1 do pos[#pos + 1] = i end
	local orig, at = {}, {}
	for s = 1, #pos do
		local base = oamBase + pos[s] * 8
		local ab = emu:read32(base)
		orig[s] = {ab & 0xFFFF, ab >> 16, emu:read16(base + 4)}
		at[pos[s]] = s
	end
	--the game's entries as {attr0, attr1, attr2, bottom, on}
	local list = {}
	for s = 1, G do
		local e = {orig[s][1], orig[s][2], orig[s][3]}
		local a0, a1 = e[1], e[2]
		if (a0 >> 8) & 3 ~= 2 then
			local x = a1 & 0x1FF
			if x < 240 or x >= 448 then
				local size = OGSOamSize[(a0 >> 14) & 3]
				size = size and size[((a1 >> 14) & 3) + 1]
				if size and size[1] <= 32 and size[2] <= 32 then
					local y = a0 & 0xFF
					if y < 160 or y > 224 then --160-224 is below the screen
						if y > 224 then y = y - 256 end
						e.bottom = y + size[2]
					end
				end
				e.on = true
			end
		end
		list[#list + 1] = e
	end
	--remote player blocks. Invisible ones stay at the end
	local blocks = {}
	for k = 0, n - 1 do
		local blk = OGSBlock[k]
		if blk then
			local entries, prio = {}, 4
			for j = 0, blk.len - 1 do
				local o = orig[at[blk.start + j]]
				local e = {o[1], o[2], o[3]}
				local x = e[2] & 0x1FF
				if x < 240 or x >= 448 then
					local p = (e[3] >> 10) & 3
					if p < prio then prio = p end
				end
				entries[#entries + 1] = e
			end
			if prio == 4 then
				for _, e in ipairs(entries) do list[#list + 1] = e end
			else
				for _, e in ipairs(entries) do e.on = true end
				blocks[#blocks + 1] = {entries = entries, prio = prio, bottom = OGSBottom[k], k = k}
			end
		end
	end
	--south players first
	table.sort(blocks, function(a, b)
		if (a.bottom or 0) ~= (b.bottom or 0) then return (a.bottom or 0) > (b.bottom or 0) end
		return a.k < b.k
	end)
	for _, b in ipairs(blocks) do
		local P
		for i, e in ipairs(list) do
			if e.on then
				local a0, a2 = e[1], e[3]
				local eprio = (a2 >> 10) & 3
				--fog: first semi-transparent sprite whose priority is not better than ours
				if ((a0 >> 10) & 3) == 1 and ((a0 >> 8) & 3) ~= 2 and eprio >= b.prio then
					P = i
					break
				end
				if YSortPlayers and b.bottom then
					if eprio > b.prio then
						P = i
						break
					elseif eprio == b.prio and e.bottom and e.bottom < b.bottom then
						P = i
						break
					end
				end
			end
		end
		P = P or (#list + 1)
		for _, e in ipairs(b.entries) do e.bottom = b.bottom end
		for j, e in ipairs(b.entries) do
			table.insert(list, P + j - 1, e)
		end
	end
	if #list ~= #pos then return end --never write a list that does not fit the slots
	for s = 1, #pos do
		local e, o = list[s], orig[s]
		if e[1] ~= o[1] or e[2] ~= o[2] or e[3] ~= o[3] then
			local base = oamBase + pos[s] * 8
			emu:write16(base, e[1])
			emu:write16(base + 2, e[2])
			emu:write16(base + 4, e[3])
		end
	end
end
OGCSaved = {} --grid index -> {orig = value before, set = value we wrote}
OGCMap, OGCW, OGCH = nil, nil, nil

--takes our collision bit out of a tile again. Normally the tile still holds exactly what we wrote. When the game rewrote other
--bits meanwhile (elevation...) but the metatile and our bit are still there, only the bit is removed. Anything else is the game's.
function OGCPutBack(map, idx, r)
	local addr = map + idx * 2
	local v = emu:read16(addr)
	if v == r.set then
		emu:write16(addr, r.orig)
	elseif (r.orig & 0x0C00) == 0 and (v & 0x0C00) == 0x0400 and (v & 0x3FF) == (r.orig & 0x3FF) then
		emu:write16(addr, v & ~0x0C00)
	end
end

--put every tile back (only if the game did not change it meanwhile)
function OGCRelease()
	local a = OGCAddress[GameID]
	if a and OGCMap and emu:read32(a.layout + 8) == OGCMap then
		for idx, r in pairs(OGCSaved) do OGCPutBack(OGCMap, idx, r) end
	end
	OGCSaved = {}
end

--called every frame from DynamicRender, renderplayertable holds where the remote players are drawn (pixels from the screen center)
function OGCUpdate()
	local a = OGCAddress[GameID]
	if not a then return end
	if not PlayerCollision and not ServerNPCHasCollision() then
		if next(OGCSaved) then OGCRelease() end
		return
	end
	local width, height, map = emu:read32(a.layout), emu:read32(a.layout + 4), emu:read32(a.layout + 8)
	if not MPInEwram(map) or width < 1 or width > 512 or height < 1 or height > 512 then
		--the layout cannot be read right now: give the tiles back through the grid we know, if it is still there
		if OGCMap and MPInEwram(OGCMap) then
			for idx, r in pairs(OGCSaved) do OGCPutBack(OGCMap, idx, r) end
		end
		OGCSaved = {}
		OGCMap = nil
		return
	end
	if OGCMap ~= map or OGCW ~= width or OGCH ~= height then
		--another map was loaded: the grid was rebuilt, there is nothing to put back
		OGCSaved = {}
		OGCMap, OGCW, OGCH = map, width, height
	end
	local wanted = {}
	for id, r in pairs(renderplayertable) do
		if PlayerCollision and id ~= PlayerID and r.Visible == 1 then
			local rx, ry = math.floor(r.FinalMapX - 112), math.floor(r.FinalMapY - 56)
			local tx0, ty0 = rx // 16, ry // 16
			for tx = tx0, tx0 + 1 do
				if math.abs(rx - tx * 16) < 13 then
					for ty = ty0, ty0 + 1 do
						if math.abs(ry - ty * 16) < 13 then
							local gx = PositionData.CurrentX + 7 + tx --7 = MAP_OFFSET of the map grid
							local gy = PositionData.CurrentY + 7 + ty
							if gx >= 0 and gx < width and gy >= 0 and gy < height then wanted[gy * width + gx] = true end
						end
					end
				end
			end
		end
	end

	ServerNPCCollisionTiles(wanted, width, height)
	for idx, r in pairs(OGCSaved) do
		if not wanted[idx] then
			OGCPutBack(map, idx, r)
			OGCSaved[idx] = nil
		end
	end
	for idx in pairs(wanted) do
		local addr = map + idx * 2
		local v = emu:read16(addr)
		local r = OGCSaved[idx]
		if r and v ~= r.set then
			if (r.orig & 0x0C00) == 0 and (v & 0x0C00) == 0x0400 and (v & 0x3FF) == (r.orig & 0x3FF) then
				r.orig = v & ~0x0C00 --the game changed other bits (elevation...) but our bit is still in: keep the record with its new value
				r.set = v
			else
				OGCSaved[idx] = nil --the game rewrote the tile (cut tree, door...): start over with its value
				r = nil
			end
		end
		if not r and (v & 0x0C00) == 0 and (v & 0x3FF) ~= 0x3FF then --already blocked / outside the map: leave alone
			OGCSaved[idx] = {orig = v, set = v | 0x0400}
			emu:write16(addr, v | 0x0400)
		end
	end
end

--console: ogcstate() lists the tiles that are blocked by this script (x, y of the map, value before / written / now) and the NPCs
function ogcstate()
	local n = 0
	for idx, r in pairs(OGCSaved) do
		n = n + 1
		local x, y = (OGCW and (idx % OGCW) or 0) - 7, (OGCW and (idx // OGCW) or 0) - 7
		local now = OGCMap and emu:read16(OGCMap + idx * 2) or -1
		console:log(string.format("blocked tile x=%d y=%d  before %04X  written %04X  now %04X", x, y, r.orig, r.set, now))
	end
	console:log(n .. " tiles blocked")
	for id, npc in pairs(ServerNPCs) do
		console:log(string.format("NPC %d map %s tile %s,%s prev %s,%s moving=%s visible=%s solid=%s", id, tostring(npc.map), tostring(npc.x), tostring(npc.y), tostring(npc.prev_x), tostring(npc.prev_y), tostring(npc.moving), tostring(npc.visible), tostring(npc.collision)))
	end
end

--console: collision() toggles, collision(true) / collision(false) sets
function collision(on)
	if on == nil then PlayerCollision = not PlayerCollision else PlayerCollision = on and true or false end
	if not PlayerCollision then OGCRelease() end
	if OGCAddress[GameID] then
		console:log("Player collision " .. (PlayerCollision and "ON" or "OFF"))
	else
		console:log("Player collision is not available for this game version")
	end
end

-- ===========================================================================================================================
-- 12. SERVER NPCS AND MESSAGES
-- ===========================================================================================================================

-- Dedicated server support.
-- gbapk_server.py is not an emulator. It joins as player 1 (hidden, so nobody sees a trainer) and adds NPCs of its own. The
-- client only draws these NPCs, blocks their tile when told to and tells the server when the player talks to one. Where they
-- stand, how they move and what they say is decided by the server. Packets (all 64 byte frames like the others):
--   DEDI server -> client: this is a dedicated server (protocol version)
--   NPCS server -> client: state of one NPC: id, map, tile, previous tile, facing, sprite, flags
--   NMSG server -> client: one piece of a message that is shown to the player in a message box
--   NTLK client -> server: the player talked to the NPC with this id
DedicatedServer = false
ServerNPCs = {}            --npc id -> state
ServerNPCGfx = {}          --sprite id -> graphics read from the ROM (false when it cannot be used)
ServerNPCTagCount = 0
ServerMsgParts = {}        --message id -> pieces that arrived
ServerMsgQueue = {}        --finished messages waiting for a free moment
ServerMsgText = ""         --text of the message script (Loadscript 38)
ServerMsgStart = -1        --frame in which the message box was started (-1 = no message box)
ServerTalkLast = -1000

function ServerNPCReset()
	DedicatedServer = false
	ServerNPCs = {}
	ServerMsgParts = {}
	ServerMsgQueue = {}
	ServerScriptParts = {}
	ServerScriptQueue = {}
	ServerScriptCurrent = nil
	if ServerMsgStart >= 0 and LockFromScript == 40 then LockFromScript = 0 end
	ServerMsgStart = -1
end

function ServerDedicated(packet)
	if not DedicatedServer then console:log("Connected to a dedicated server") end
	DedicatedServer = true
end

-- ------------------------------------------------------------------ NPC states (NPCS frames)
--payload of an NPCS frame (byte 21 on): id u16, map u16, x u16, y u16, facing (1 left, 2 right, 3 up, 4 down), sprite u16,
--flags (1 visible, 2 blocks its tile, 4 walking, 8 teleport (no walk), 16 can be talked to), previous x u16, previous y u16
function ServerNPCReceive(frame)
	local function u8(i) return string.byte(frame, i) or 0 end
	local function u16(i) return u8(i) | (u8(i + 1) << 8) end
	local id = u16(21)
	local npc = ServerNPCs[id]
	local flags = u8(32)
	local x, y = u16(25), u16(27)
	local new = (npc == nil)
	if new then
		npc = {id = id, stepFrame = 16, stepAlt = false, moving = false}
		ServerNPCs[id] = npc
	end
	npc.map = u16(23)
	npc.sprite = u16(30)
	local dir = u8(29)
	npc.direction = (dir >= 1 and dir <= 4) and dir or 4
	npc.visible = (flags & 1) ~= 0
	npc.collision = (flags & 2) ~= 0
	npc.talk = (flags & 16) ~= 0
	if new or npc.x == nil or (flags & 8) ~= 0 or math.abs(x - npc.x) + math.abs(y - npc.y) > 1 then
		npc.x, npc.y, npc.prev_x, npc.prev_y = x, y, x, y
		npc.moving = false
		npc.stepFrame = 16
	elseif x ~= npc.x or y ~= npc.y then
		npc.prev_x, npc.prev_y = npc.x, npc.y
		npc.x, npc.y = x, y
		npc.moving = true
		npc.stepFrame = 0
		npc.stepAlt = not npc.stepAlt
	end
end

--once per frame: advance the walk of the NPC (16 frames per tile, like the game)
function ServerNPCTick(npc)
	if npc.moving then
		npc.stepFrame = npc.stepFrame + 1
		if npc.stepFrame >= 16 then
			npc.moving = false
			npc.stepFrame = 16
			npc.prev_x, npc.prev_y = npc.x, npc.y
		end
	end
end

-- ------------------------------------------------------------------ graphics (from the ROM of this game)
--the 16 colors of an object event palette tag from the game's table
function ServerNPCReadPalette(tag)
	local tbl = gAddress[GameID].sObjectEventSpritePalettes
	if not tbl then return nil end
	for i = 0, 127 do
		local data = ROMCARD:read32(tbl + 8 * i)
		local t = ROMCARD:read16(tbl + 8 * i + 4)
		if data == 0 and t == 0 then break end
		if t == tag and MPInRom(data) then
			local colors = {}
			for c = 0, 15 do colors[c + 1] = ROMCARD:read16(data + 2 * c) end
			return colors
		end
	end
	return nil
end

--graphics of an object event graphics id: sheet, size, palette. false when the id does not exist in this game
function ServerNPCGraphics(sprite)
	local g = ServerNPCGfx[sprite]
	if g ~= nil then return g end
	ServerNPCGfx[sprite] = false
	local base = gAddress[GameID].gGraphicsInfo
	if not base then return false end
	local info = ROMCARD:read32(base + 4 * sprite)
	if not MPInRom(info) then return false end
	local images = ROMCARD:read32(info + 28)
	if not MPInRom(images) then return false end
	local w, h = ROMCARD:read16(info + 8), ROMCARD:read16(info + 10)
	if w >= 0x8000 then w = w - 0x10000 end
	if h >= 0x8000 then h = h - 0x10000 end
	local size, xAdj, yAdj = "16x32", 0, 0
	if w == 16 and h == 16 then
		size, yAdj = "16x16", 16
	elseif w == 32 and h == 32 then
		size, xAdj = "32x32", -8
	end
	local tag = ROMCARD:read16(info + 2)
	local key = nil
	local palette = ServerNPCReadPalette(tag)
	if palette then
		key = "NPC" .. tostring(tag)
		if not OGSPalettes[key] then
			OGSPalettes[key] = palette
			ServerNPCTagCount = ServerNPCTagCount + 1
			OGSTags[key] = 0xFC00 + ServerNPCTagCount
		end
	end
	g = {images = images, size = size, xAdj = xAdj, yAdj = yAdj, palKey = key, tag = tag, inanimate = ((ROMCARD:read8(info + 12) >> 6) & 1) == 1}
	ServerNPCGfx[sprite] = g
	return g
end

--frame of the sprite sheet: 0 down, 1 up, 2 left (right = flipped), 3-4 walk down, 5-6 walk up, 7-8 walk left
function ServerNPCFrame(npc, g)
	local d = npc.direction
	if npc.moving and not g.inanimate and npc.stepFrame < 8 then
		local walk = (d == 4) and 3 or ((d == 3) and 5 or 7)
		return walk + (npc.stepAlt and 1 or 0)
	end
	return (d == 4) and 0 or ((d == 3) and 1 or 2)
end

--copies the current frame to the tiles of draw slot "slot" and loads the palette. Returns size, xAdj, yAdj, palette slot or nil
function ServerNPCUpload(npc, slot)
	local g = ServerNPCGraphics(npc.sprite)
	if not g then return nil end
	local frame = ServerNPCFrame(npc, g)
	local data, size
	for _ = 1, 2 do
		local entry = g.images + 8 * frame
		data, size = ROMCARD:read32(entry), ROMCARD:read16(entry + 4)
		if MPInRom(data) and size > 0 then break end
		data = nil
		frame = (npc.direction == 4) and 0 or ((npc.direction == 3) and 1 or 2) --a sheet without walking frames
	end
	if not data then return nil end
	local words = math.min(size // 4, 128)
	local addr = MPHw.OBJ_TILES + MPBankTile(slot) * 32
	for i = 0, words - 1 do
		emu:write32(addr + 4 * i, ROMCARD:read32(data + 4 * i))
	end
	local palSlot = 0
	if g.palKey then
		palSlot = OGSNPCPalette(g.palKey)
	end
	return g.size, g.xAdj, g.yAdj, palSlot
end

-- ------------------------------------------------------------------ drawing and blocking
--pixel offset of the sprite while it walks from the previous to the current tile
function ServerNPCOffset(npc)
	if not npc.moving then return 0, 0 end
	local left = 16 - npc.stepFrame
	return (npc.prev_x - npc.x) * left, (npc.prev_y - npc.y) * left
end

--draws the NPCs of the current map (called by DynamicRender, uses the same draw slots as other players)
function ServerNPCRender(MaxDraw)
	if not DedicatedServer then return end
	local player = FindPlayerByID(PlayerID)
	if not player then return end
	local PlayerBarrier = {MinX = -48, MaxX = 256, MinY = -48, MaxY = 160}
	local PlayerX, PlayerY, PlayerDirection, PlayerMapID, _, _, _, PlayerMapDirection, PlayerPrevMapID, PlayerMapEntrance, PlayerMapPrevX, PlayerMapPrevY, PlayerBorderX, PlayerBorderY, PlayerConnections, PlayerGameID, AnimationData = player:GetPosition()
	local ids = {}
	for id in pairs(ServerNPCs) do ids[#ids + 1] = id end
	table.sort(ids)
	for _, id in ipairs(ids) do
		local npc = ServerNPCs[id]
		ServerNPCTick(npc)
		if npc.visible and npc.map == PlayerMapID then
			local ax, ay = ServerNPCOffset(npc)
			local DrawX, DrawY, Visible, _ = CalculateRelative(PlayerGameID, npc.x, npc.y, npc.x, npc.y, ax, ay, npc.map, npc.map, PlayerBorderX, PlayerBorderY, PlayerBorderX, PlayerBorderY, PlayerX, PlayerY, PlayerDirection, PlayerMapID, PlayerPrevMapID, PlayerMapDirection, PlayerMapDirection, 0, 0, PlayerMapEntrance, PlayerMapEntrance, PlayerMapPrevX, PlayerMapPrevY, PlayerBorderX, PlayerBorderY, 0, PlayerConnections, PlayerGameID, false)
			local FinalMapX = DrawX + 112
			local FinalMapY = DrawY + 56
			if IDsToDraw < MaxDraw and Visible == 1 and not (FinalMapX > PlayerBarrier.MaxX or FinalMapX < PlayerBarrier.MinX or FinalMapY > PlayerBarrier.MaxY or FinalMapY < PlayerBarrier.MinY) then
				local size, xAdj, yAdj, palette = ServerNPCUpload(npc, IDsToDraw)
				if size then
					FinalMapX = FinalMapX + xAdj
					FinalMapY = FinalMapY + yAdj
					if FinalMapX < 0 then FinalMapX = FinalMapX + 511 end
					if FinalMapY < 0 then FinalMapY = FinalMapY + 256 end
					DrawPlayer(IDsToDraw, FinalMapX, FinalMapY, 0, npc.direction, 0, 0, 0, 0, 9999, size, palette)
					IDsToDraw = IDsToDraw + 1
				end
			end
		end
	end
end

--does any NPC block its tile? (keeps the collision code running)
function ServerNPCHasCollision()
	if not DedicatedServer then return false end
	for _, npc in pairs(ServerNPCs) do
		if npc.visible and npc.collision then return true end
	end
	return false
end

--adds the tiles of the NPCs on the current map to the blocked tiles of OGCUpdate (grid index = y * width + x)
function ServerNPCCollisionTiles(wanted, width, height)
	if not DedicatedServer then return end
	for _, npc in pairs(ServerNPCs) do
		if npc.visible and npc.collision and npc.map == PositionData.PlayerMapID then
			local gx, gy = npc.x + 7, npc.y + 7 --7 = MAP_OFFSET of the map grid
			if gx >= 0 and gx < width and gy >= 0 and gy < height then wanted[gy * width + gx] = true end
			if npc.moving then
				gx, gy = npc.prev_x + 7, npc.prev_y + 7
				if gx >= 0 and gx < width and gy >= 0 and gy < height then wanted[gy * width + gx] = true end
			end
		end
	end
end

-- ------------------------------------------------------------------ talking (NTLK) and messages (NMSG)
--A button: is there an NPC in front of the player? Returns true when it was talked to
function ServerNPCTryTalk(PlayerX, PlayerY, PlayerDirection, PlayerMapID)
	if not DedicatedServer then return false end
	for _, npc in pairs(ServerNPCs) do
		if npc.visible and npc.talk and npc.map == PlayerMapID then
			local dx, dy = PlayerX - npc.x, PlayerY - npc.y
			local face = 0 --direction the NPC turns to
			if PlayerDirection == 1 and dx == 1 and dy == 0 then face = 2
			elseif PlayerDirection == 2 and dx == -1 and dy == 0 then face = 1
			elseif PlayerDirection == 3 and dx == 0 and dy == 1 then face = 4
			elseif PlayerDirection == 4 and dx == 0 and dy == -1 then face = 3 end
			if face > 0 then
				if TotalFrame - ServerTalkLast >= 30 then --at most twice a second
					ServerTalkLast = TotalFrame
					SendSpecialData(SocketMain, "NTLK", 1, PlayerID, npc.id)
				end
				return true
			end
		end
	end
	return false
end

--a piece of a message: message id u8, piece number u8 (from 1), number of pieces u8, length u8, text (39 bytes at most)
function ServerMsgReceive(frame)
	local id, part, total, len = string.byte(frame, 21) or 0, string.byte(frame, 22) or 1, string.byte(frame, 23) or 1, string.byte(frame, 24) or 0
	local m = ServerMsgParts[id]
	if not m or m.total ~= total then
		m = {total = total, got = 0, parts = {}}
		ServerMsgParts[id] = m
	end
	if not m.parts[part] then
		m.parts[part] = string.sub(frame, 25, 24 + math.min(len, 39))
		m.got = m.got + 1
	end
	if m.got >= m.total then
		ServerMsgParts[id] = nil
		local text = table.concat(m.parts)
		--line break and new page of the text codes of the mod
		text = string.gsub(text, "\n", "\\n")
		text = string.gsub(text, "\f", "\\p")
		if #ServerMsgQueue < 16 then ServerMsgQueue[#ServerMsgQueue + 1] = text end
	end
end

-- ------------------------------------------------------------------ scripts of the server (NSCR) and their answers (NRES)
-- The server sends a script in the game's own script language (the source, like the scripts of this file); this file's compiler
-- (MPScriptAssemble) makes the bytes the game runs, exactly as for the scripts of the mod. The text of the request is
--   kind "S", code, text of the message box, then the entries of a menu (when there are some), separated by byte 0x1E.
-- Because the source comes from outside only a small set of commands is accepted (ServerScriptAllowed): boxes, questions, menus,
-- variables 0x8000 - 0x800F, delays. No native code, no specials, no battles. The answer of the player goes back in NRES.
ServerScriptParts = {}     --request id -> pieces that arrived
ServerScriptCurrent = nil  --the request that runs now: {id, code, text, options}
ServerScriptText = ""      --TEXT of the running script
ServerScriptOptions = {}   --entries of its menu

ServerScriptAllowed = {
	nop = true, pad = true, ["end"] = true, goto_if = true, callstd = true, loadword = true, setvar = true, addvar = true, copyvar = true,
	compare = true, delay = true, message = true, waitmessage = true, closemessage = true, lock = true, lockall = true, release = true,
	releaseall = true, multichoice = true, multichoicegrid = true, waitstate = true,
}

--nil when the source may run, else the reason
function ServerScriptCheck(code)
	if #code > 700 then return "too long" end
	local lines = 0
	local function isvar(tok)
		local n = tonumber(tok)
		if n then return n >= 0x8000 and n <= 0x800F end
		return MPScriptNames[tok] ~= nil and string.sub(tok, 1, 4) == "VAR_" and MPScriptNames[tok] >= 0x8000 and MPScriptNames[tok] <= 0x800F
	end
	for rawLine in string.gmatch(code .. "\n", "([^\n]*)\n") do
		local line = string.gsub(string.gsub(rawLine, "%-%-.*$", ""), ";.*$", "")
		line = string.match(line, "^%s*(.-)%s*$")
		if line ~= "" and not string.match(line, "^([%w_]+):$") then
			lines = lines + 1
			if lines > 60 then return "too many lines" end
			local name, rest = string.match(line, "^([%w_]+)%s*(.*)$")
			if not name or not ServerScriptAllowed[name] then return "command not allowed: " .. tostring(name) end
			local ops = {}
			for tok in string.gmatch(rest, "[^,]+") do ops[#ops + 1] = string.match(tok, "^%s*(.-)%s*$") end
			if name == "pad" then
				if ops[1] and ops[1] ~= "lock" and ops[1] ~= "lockall" then return "pad: only lock / lockall" end
			elseif name == "callstd" then
				local v = tonumber(ops[1]) or MPScriptNames[ops[1] or ""]
				if not v or v < 2 or v > 6 then return "callstd: only the message boxes" end
			elseif name == "loadword" then
				if not (ops[2] == "TEXT" and (tonumber(ops[1]) or 9) <= 1) then return "loadword: only TEXT" end
			elseif name == "message" then
				if ops[1] ~= "TEXT" then return "message: only TEXT" end
			elseif name == "setvar" or name == "addvar" or name == "compare" then
				if not isvar(ops[1] or "") then return name .. ": variable out of range" end
			elseif name == "copyvar" then
				if not (isvar(ops[1] or "") and isvar(ops[2] or "")) then return "copyvar: variable out of range" end
			elseif name == "delay" then
				if (tonumber(ops[1]) or 9999) > 600 then return "delay: too long" end
			elseif name == "multichoice" then
				if tonumber(ops[3]) ~= 2 then return "multichoice: only the list of the server" end
			elseif name == "multichoicegrid" then
				if tonumber(ops[3]) ~= 2 then return "multichoicegrid: only the list of the server" end
			end
		end
	end
	return nil
end

function ServerScriptAnswer(id, status)
	SendSpecialData(SocketMain, "NRES", 1, PlayerID, {id = id, status = status, answer = Var8000[2], choice = Var8000[1], result = Var8000[14]})
end

--a piece of a request: request id u8, piece number u8 (from 1), number of pieces u8, length u8, text (39 bytes at most)
function ServerScriptReceive(frame)
	local id, part, total, len = string.byte(frame, 21) or 0, string.byte(frame, 22) or 1, string.byte(frame, 23) or 1, string.byte(frame, 24) or 0
	local m = ServerScriptParts[id]
	if not m or m.total ~= total then
		m = {total = total, got = 0, parts = {}}
		ServerScriptParts[id] = m
	end
	if not m.parts[part] then
		m.parts[part] = string.sub(frame, 25, 24 + math.min(len, 39))
		m.got = m.got + 1
	end
	if m.got < m.total then return end
	ServerScriptParts[id] = nil
	local fields, pos, text = {}, 1, table.concat(m.parts)
	while true do
		local e = string.find(text, "\30", pos, true)
		fields[#fields + 1] = string.sub(text, pos, (e or (#text + 1)) - 1)
		if not e then break end
		pos = e + 1
	end
	local code = fields[2] or ""
	local why = (fields[1] ~= "S") and "unknown kind" or ServerScriptCheck(code)
	if not why then
		--the compiler: a script that does not compile is refused as well
		local ok, err = pcall(MPScriptAssemble, code, {base = 0, text = 0, A = gAddress[GameID], names = {}})
		if not ok then why = tostring(err) end
	end
	if why then
		console:log("Script of the server refused: " .. why)
		local keep1, keep2, keep14 = Var8000[1], Var8000[2], Var8000[14]
		Var8000[1], Var8000[2], Var8000[14] = 0, 0, 0
		ServerScriptAnswer(id, 1)
		Var8000[1], Var8000[2], Var8000[14] = keep1, keep2, keep14
		return
	end
	local boxText = string.gsub(string.gsub(fields[3] or "", "\n", "\\n"), "\f", "\\p")
	local options = {}
	for i = 4, math.min(#fields, 11) do options[#options + 1] = string.sub(fields[i], 1, 20) end
	if #ServerMsgQueue < 16 then
		ServerMsgQueue[#ServerMsgQueue + 1] = {id = id, code = code, text = boxText, options = options}
	end
end

--the running script of the server ended (status 0), was taken over (2)
function ServerScriptFinish(status)
	local r = ServerScriptCurrent
	ServerScriptCurrent = nil
	ServerMsgStart = -1
	if LockFromScript == 40 then LockFromScript = 0 end
	if r then ServerScriptAnswer(r.id, status) end
end

--once per frame: shows the next message when the player is free, ends the message box when it was closed
function ServerMsgTick()
	if ServerMsgStart >= 0 then
		if ServerScriptCurrent then
			if LockFromScript ~= 40 then
				ServerScriptFinish(2)                                    --something else took over
			elseif TotalFrame - ServerMsgStart > 5 and Var8000[2] ~= 0 then
				ServerScriptFinish(0)                                    --the script set VAR_ANSWER
			elseif TotalFrame - ServerMsgStart > 10800 then
				ServerScriptFinish(2)                                    --three minutes without an answer
			end
		elseif LockFromScript ~= 40 then
			ServerMsgStart = -1 --something else took over
		elseif (TotalFrame - ServerMsgStart > 5 and Var8000[2] ~= 0) or TotalFrame - ServerMsgStart > 3600 then --the script sets variable 0x8001 when the box was closed
			LockFromScript = 0
			ServerMsgStart = -1
		end
		return
	end
	if #ServerMsgQueue == 0 then return end
	if LockFromScript ~= 0 or emu:read8(gAddress[GameID].gLockControls) ~= 0 or IsInMenu() ~= 0 or not FindPlayerByID(PlayerID) then return end
	--a script of the game is running (a trainer, an event): a message would take its place. Waits for it, but not for ever
	if emu:read8(gAddress[GameID].gScriptLoad) ~= 2 then
		MPMsgWait = (MPMsgWait or 0) + 1
		if MPMsgWait < 600 then return end
	end
	MPMsgWait = 0
	local item = table.remove(ServerMsgQueue, 1)
	if type(item) == "table" then
		--a script of the server: its source goes into script 43 and is compiled by the loader
		ServerScriptCurrent = item
		ServerScriptText = item.text
		ServerScriptOptions = item.options
		MPScriptSource[45].code = item.code
		LockFromScript = 40
		ServerMsgStart = TotalFrame
		Loadscript(45)
		return
	end
	ServerMsgText = item
	LockFromScript = 40
	ServerMsgStart = TotalFrame
	Loadscript(38)
end

function DynamicRender()
	if DebugMessages.Render then console:log("DYNAMIC RENDER START") end
	local MaxDraw = 0
	OGSUsed = {}
	OGSBegin()
	MaxDraw = OGSLimit
	OGCUpdate()
	for i, player in pairs(players) do
		local PlayerBarrier = {
			MinX = -48,
			MaxX = 256,
			MinY = -48,
			MaxY = 160,
		}
		id = player:GetID()
		if not drawplayertable[id] and previousdrawplayertable[id] then drawplayertable[id] = previousdrawplayertable[id] end
		if DebugMessages.Render then console:log("DYNAMIC RENDER PLAYER " .. id .. " START") end
		if drawplayertable[id] and renderplayertable[id] and PlayerID ~= id then
			local FinalMapX = renderplayertable[id].FinalMapX
			local FinalMapY = renderplayertable[id].FinalMapY
			local SlotSize = GetAnimationSizeSlot(id, 1)
			--	console:log("CAN SEE. VIS: " .. renderplayertable[i].Visible)
			if IDsToDraw < MaxDraw and renderplayertable[id].Visible == 1 and not (FinalMapX > PlayerBarrier.MaxX or FinalMapX < PlayerBarrier.MinX or FinalMapY > PlayerBarrier.MaxY or FinalMapY < PlayerBarrier.MinY) then
				if FinalMapX < 0 then FinalMapX = FinalMapX + 511 end
				if FinalMapY < 0 then FinalMapY = FinalMapY + 256 end
				if DebugMessages.Render then console:log("FOUND PLAYER " .. id .. " NEARBY. DRAWING AS ID " .. IDsToDraw) end
				CreatePlayer(id, IDsToDraw)
				CreateSprite(id, IDsToDraw)
				if DebugMessages.Render then console:log("ANIMATION DATA OF PLAYER " .. id .. ": " .. renderplayertable[id].AnimationData) end
				DrawPlayer(IDsToDraw, FinalMapX, FinalMapY, renderplayertable[id].SpriteType, renderplayertable[id].Direction, renderplayertable[id].AnimationFrame, renderplayertable[id].AnimationCycle, renderplayertable[id].SurfFrame, renderplayertable[id].AnimationData, id)
				IDsToDraw = IDsToDraw + 1
			end
		elseif drawplayertable[id] and renderplayertable[id] then
			if DebugMessages.Render then console:log("PLAYER " .. i .. " HAS DATA. PLAYERID: " .. PlayerID .. " PLAYER " .. i .. " ID: " .. player:GetID()) end
		end
	end

	ServerNPCRender(MaxDraw)
	for i = 1, MaxDraw do
		if i > IDsToDraw then
			-- Too many messages
			--console:log("ERASING ID " .. i)
			if not OGSValid then ErasePlayer(i - 1) end
		end
	end
	OGSReleaseUnused()
	OGSParkVacated()
	OGSHideReflections(IDsToDraw)
	ReorderPlayerOAM(IDsToDraw)
	RefreshRenderPlayer()
end

--Bobbing phase (0-32) of every underwater player, same cycle and offsets that surfing uses in Ruby/Sapphire/Emerald
local UnderwaterBobFrame = {}


function DrawPlayerRaw(id, FinalMapX, FinalMapY, SpriteType, Direction, AnimationFrame, AnimationCycle, SurfFrame, MenuType, RealID, SizeOpt, PaletteOpt)

	local PlayerAddress = gAddress[GameID].gSprite - (id * 24)
	--UNUSED
	local PaletteAddress = MPHw.OBJ_PALETTE
	--local PaletteFRLG = {1532973838, 979061535, 1025974543, 681783525, 2006654082, 709442350, 555232671, 32767}
	--local PaletteRSE = {569725424, 979061535, 1762140431, 1653488871, 2143098029, 633301718, 796859640, 7799}
	--local PaletteUse = {}
	--2608 = 190 = 0000101000110000
	--First 4 bits are palette, next 2 are priority, then the rest is the sprite bank. 560 is tile 190 in sprite bank.
	local Bank = MPBankTile(id)
	--Palette is 4 bits. 0-F = 0-15 (16 palettes). DO NOT GO ABOVE 16!!! -1 means it will not use a custom palette
	local Palette = 0
	if PaletteOpt then Palette = PaletteOpt end
	--2 bits. Can be 0-2. 0 = drawn first, 1 = drawn same prio as player, 2 = drawn last
	local Priority = 2
	local Palette2 = 0
	local isHotSprings = 0
	local grassSplit = false --long grass: the lower half of the body is a second sprite of priority 3 (behind the grass of the map)
	local leaveGrass = false --long grass that is left: its sprite is entry 0 of the block
	if RealID then
		if RealID < 9999 then
			local drawplayer = FindPlayerByID(RealID)
			local tile = drawplayer:GetMetaTile()
			local height = drawplayer:GetElevation() & 0xF

			if gAddress[GameID].sGameType == "RSE" then
				--hot spring / long grass: the sprite that the movement block put into slot 2 of this player
				if GetAnimationSizeSlot(RealID, 1) ~= "32x32" then
					local fxTable = GetAnimationTableSlot(RealID, 2)
					if fxTable == 1004 then
						isHotSprings = 8
						--claim a free palette slot (14 only if none is free) and keep the effect palette loaded in it
						Palette2 = OGSUseSlot("HOT", 14)
					elseif fxTable == 1005 then
						isHotSprings = 8
						Palette2 = OGSUseSlot("GRASS", 14)
						--the body is in two sprites only while it stands in / walks between long grass tiles (not on the step in or out)
						grassSplit = drawplayer.Mv ~= nil and drawplayer.Mv.split == true
					elseif GetSlotUsed(RealID, 3) and GetAnimationTableSlot(RealID, 3) == 1005 then
						--leaving long grass: the grass of the tile that is left is drawn in front of the body (entry 0, body at 1)
						isHotSprings = 8
						Palette2 = OGSUseSlot("GRASS", 14)
						leaveGrass = true
					end
				end
				--cycling road
				if tile == 0x70 and height == 4 then
					--	console:log("PLAYER " .. RealID .. " IS ON CYCLING ROAD")
					Priority = 1
					--fortree city
				elseif tile == 0x78 and height == 4 then
					Priority = 1
				elseif tile ~= 0 and height == 4 then
					Priority = 1
				elseif tile ~= 0 then
					--	console:log("TILE: " .. tile .. " height: " .. height)
				end
			end
		end
	end
	--if weather is fog or dive and DisableRenderWeather is off, make players prio 1. still looks wierd, but at least it works
	if (PositionData.Weather == 6 or PositionData.Weather == 9 or PositionData.Weather == 10 or PositionData.Weather == 14) and DisableRenderWeather == false then
		Priority = FogPlayerPriority
	end


	local Flip = 128
	if Direction == 2 then Flip = 144 end

	local IsInBattle = false

	--use palette of sprite if enabled
	if OwnGameSprites and RealID and RealID < 9999 and SpriteType ~= 6 and not PositionData.Underwater and not PaletteOpt then
		local ogsSlot = OGSGetSlot(RealID)
		if ogsSlot then Palette = ogsSlot end
	end
	OGSBottom[id] = ((FinalMapY >= 192) and (FinalMapY - 256) or FinalMapY) + 32
	--underwater players use the dive palette. If you are not diving yourself, palette 0 is not it, so use palette 14 for them
	if SpriteType == 6 and not PositionData.Underwater and gAddress[GameID].sGameType == "RSE" then
		Palette = OGSUseSlot("DIVE", 14)

	end
	local ConstructSprite = (Palette * 4096) + (Priority * 1024) + Bank
	local ConstructSprite2 = ConstructSprite + 16
	local ConstructSprite3 = (Palette * 4096) + (1 * 1024) + Bank + 32
	local ConstructSprite4 = (Palette * 4096) + (Priority * 1024) + Bank + 32
	local ConstructSprite5 = (Palette2 * 4096) + (Priority * 1024) + Bank + 16

	--NOT USED. Palettes are actually way more complex to simply swap.
	local PaletteSwap = PaletteAddress + (Palette * 32)
	local function WritePalette(addr, data)
		for i = 1, #data do
			emu:write32(addr, data[i])
			addr = addr + 4
		end
	end

	--Swap Palette first
	--if Palette > -1 then
	--	WritePalette(PaletteSwap, PaletteUse)
	--end

	if DebugMessages.Render then console:log("FinalMapX: " .. FinalMapX .. " FinalMapY: " .. FinalMapY) end

	ErasePlayer(id)

	--Bike
	if SpriteType == 1 or SpriteType == 5 then
		FinalMapX = FinalMapX - 8
		local SlotSize = GetAnimationSizeSlot(RealID, 1)
		WriteToSpriteList(PlayerAddress, FinalMapX, FinalMapY, Flip, SlotSize, ConstructSprite, 0, 0, isHotSprings)
		if gAddress[GameID].sGameType == "RSE" then	FinalMapX = FinalMapX + 8 end

		--Surf
	elseif SpriteType == 2 then
		--	console:log("CYCLE: " .. AnimationCycle .. " FRAME: " .. AnimationFrame)
		local bobR, bobA, bobB, bobX = nil, nil, nil, nil
		if MPMvSurfBob and RealID then bobR, bobA, bobB, bobX = MPMvSurfBob(RealID) end
		if bobR and HasAnimationInRange(37, 41) then bobR, bobA, bobB, bobX = 0, 0, nil, nil end --the pose of the field move is drawn here for a moment: no bob
		if not bobR and AnimationCycle > 0 and HasAnimationInRange(28, 36) and gAddress[GameID].sGameType == "FRLG" then
			FinalMapY = FinalMapY + 1
		end
		local playersitx = FinalMapX
		if gAddress[GameID].sGameType == "RSE" then
			if HasAnimationInRange(34, 36) or HasAnimationInRange(37, 41) or HasAnimationInRange(101, 103) then playersitx = playersitx - 8 end
			if not bobR then
				if SurfFrame >= 9 and SurfFrame <= 16 then FinalMapY = FinalMapY - 1 end
				if SurfFrame >= 17 and SurfFrame <= 24 then FinalMapY = FinalMapY - 2 end
				if SurfFrame >= 25 and SurfFrame <= 32 then FinalMapY = FinalMapY - 1 end
			end
		end
		local SlotSize = GetAnimationSizeSlot(RealID, 1)
		local riderY, blobY = FinalMapY + (bobR or 0), FinalMapY + 8 + (bobA or 0)
		WriteToSpriteList(PlayerAddress, playersitx, riderY, Flip, SlotSize, ConstructSprite, 0, 0, isHotSprings)
		if GetSlotUsed(RealID, 2) then
			local SlotSize = GetAnimationSizeSlot(RealID, 2)
			WriteToSpriteList(PlayerAddress + 8, FinalMapX-8 + (bobX or 0), blobY, Flip, SlotSize, ConstructSprite2, 0, 0, isHotSprings)
			--the second copy of the blob (Emerald, Ruby, Sapphire): the third sprite of the block
			if bobB and isHotSprings == 0 and not GetSlotUsed(RealID, 3) then
				WriteToSpriteList(PlayerAddress + 16, FinalMapX-8, FinalMapY + 8 + bobB, Flip, SlotSize, ConstructSprite2, 0, 0, 0)
			end
		end
		--Throwing pokemon
	elseif SpriteType == 3 then
		if gAddress[GameID].sGameType == "RSE" then FinalMapX = FinalMapX - 8 end
		local SlotSize = GetAnimationSizeSlot(RealID, 1)
		WriteToSpriteList(PlayerAddress, FinalMapX, FinalMapY, Flip, SlotSize, ConstructSprite, 0, 0, isHotSprings)
		--Fishing
	elseif SpriteType == 4 then
		if HasAnimationInRange(28, 33) then
			if gAddress[GameID].sGameType == "RSE" then
				if SurfFrame >= 9 and SurfFrame <= 16 then FinalMapY = FinalMapY - 1 end
				if SurfFrame >= 17 and SurfFrame <= 24 then FinalMapY = FinalMapY - 2 end
				if SurfFrame >= 25 and SurfFrame <= 32 then FinalMapY = FinalMapY - 1 end
			end
			local SlotSize = GetAnimationSizeSlot(RealID, 1)
			WriteToSpriteList(PlayerAddress + 8, FinalMapX-8, FinalMapY+8, Flip, SlotSize, ConstructSprite2, 0, 0, isHotSprings)
		end
		local SlotSize = GetAnimationSizeSlot(RealID, 1)
		local sitx = FinalMapX
		local sity = FinalMapY
		if Direction == 1 then sitx = sitx - 16
		elseif Direction == 4 then sitx = sitx - 8 sity = sity + 8
		elseif Direction == 3 then sitx = sitx - 8
		end
		WriteToSpriteList(PlayerAddress, sitx, sity, Flip, SlotSize, ConstructSprite, 0, 0, isHotSprings)
		--Underwater (dive): 32x32 sprite centered over the tile
	elseif SpriteType == 6 then
		--bob up and down all the time, also while moving (advances once per drawn frame)
		local ubob = MPMvUnderBob and RealID and MPMvUnderBob(RealID)
		if ubob then
			FinalMapY = FinalMapY + ubob
		else
			local bob = ((UnderwaterBobFrame[RealID] or -1) + 1) % 33
			UnderwaterBobFrame[RealID] = bob
			if bob >= 9 and bob <= 16 then FinalMapY = FinalMapY - 1
			elseif bob >= 17 and bob <= 24 then FinalMapY = FinalMapY - 2
			elseif bob >= 25 then FinalMapY = FinalMapY - 1
			end
		end
		local SlotSize = GetAnimationSizeSlot(RealID, 1)
		WriteToSpriteList(PlayerAddress, FinalMapX - 8, FinalMapY, Flip, SlotSize, ConstructSprite, 0, 0, isHotSprings)
		--On Foot
	else
		local SlotSize = GetAnimationSizeSlot(RealID, 1)

		if RealID == 9999 and SizeOpt then SlotSize = SizeOpt --NPC of the dedicated server: size of its own sprite
		elseif not SlotSize and SizeOpt then SlotSize = SizeOpt end
		if grassSplit and SlotSize == "16x32" then
			--the game draws the upper half normally and the lower half at priority 3, so the grass of the map covers it
			WriteToSpriteList(PlayerAddress + 8, FinalMapX, FinalMapY, Flip, "16x16", ConstructSprite, 0, 0, 0)
			WriteToSpriteList(PlayerAddress + 16, FinalMapX, FinalMapY + 16, Flip, "16x16", (Palette * 4096) + (3 * 1024) + Bank + 4, 0, 0, 0)
		else
			WriteToSpriteList(PlayerAddress, FinalMapX - ((SlotSize == "32x32" and RealID ~= 9999) and 8 or 0), FinalMapY, Flip, SlotSize, ConstructSprite, 0, 0, isHotSprings)
		end
	end


	local function fxOffset(pos)
		local t = drawspritetable[RealID] and drawspritetable[RealID][pos]
		return (t and t.x) or 0, (t and t.y) or 0
	end
	--slot 3: menu symbols, the shadow of a jump, the grass of the tile that is left. With the body in two sprites (long grass) the
	--fourth sprite of the block is used for it, when there is one
	local slot3Addr = PlayerAddress + 16
	local slot3Ok = true
	if grassSplit then
		slot3Addr = PlayerAddress + 24
		slot3Ok = OGSCap ~= nil and DynamicOAM
	elseif leaveGrass then
		slot3Addr = PlayerAddress
	end
	if GetSlotUsed(RealID, 3) and slot3Ok then
		local xoff, yoff = fxOffset(3)
		local SlotSize = GetAnimationSizeSlot(RealID, 3)
		local table3 = GetAnimationTableSlot(RealID, 3)
		if table3 == 1003 then
			WriteToSpriteList(slot3Addr, FinalMapX + xoff, FinalMapY + yoff + 24, Flip, SlotSize, ConstructSprite4, 0, 0, 0)
		elseif table3 == 1005 then
			WriteToSpriteList(slot3Addr, FinalMapX + xoff, FinalMapY + yoff + 16, 128, SlotSize, ConstructSprite5, 0, 0, 0)
		else
			local sx, sy = FinalMapX + xoff, FinalMapY + yoff
			if gAddress[GameID].sGameType == "FRLG" and SpriteType == 1 then sx = sx + 8 sy = sy - 8 end
			WriteToSpriteList(slot3Addr, sx, sy, Flip, SlotSize, ConstructSprite3, 0, 0, 0)
		end
	end
	if GetSlotUsed(RealID, 2) then
		local xoff, yoff = fxOffset(2)
		local SlotSize = GetAnimationSizeSlot(RealID, 2)
		local fxTable = GetAnimationTableSlot(RealID, 2)
		if GetAnimationSizeSlot(RealID, 1) ~= "32x32" and (fxTable == 1004 or fxTable == 1005) and gAddress[GameID].sGameType == "RSE" then
			WriteToSpriteList(PlayerAddress, FinalMapX + xoff, FinalMapY + 16 + yoff, 128, SlotSize, ConstructSprite5, 0, 0, 0)
		end
	end
	if MPFxDrawBird and RealID and RealID < 9999 then MPFxDrawBird(RealID, PlayerAddress, FinalMapX, FinalMapY, Palette) end
	RefreshDrawSprite(RealID, 2)
	RefreshDrawSprite(RealID, 3)
end

function ErasePlayer(id)
	local PlayerAddress = gAddress[GameID].gSprite - (id * 24)

	--For Reference: WriteToSpriteList(PlayerAddress, X, Y, Facing, SpriteID, Extra1, Extra3, Extra4)
	WriteToSpriteList(PlayerAddress, 160, 48, 1, 0, 12, 0, 1)
	--Surfing char
	WriteToSpriteList(PlayerAddress + 8, 160, 48, 1, 0, 12, 0, 1)
	--Extra Char
	WriteToSpriteList(PlayerAddress + 16, 160, 48, 1, 0, 12, 0, 1)
	if OGSCap then OGSTouched = {} end
end

-- Tate Addition
function WriteToSpriteList(Player1Address, X, Y, Facing, SpriteSize, ConstructSprite, Extra3, Extra4, isHotSprings)
	local Player1Address = Player1Address
	if isHotSprings then
		Player1Address = Player1Address + isHotSprings
	end
	local PlayerXAddress = Player1Address + 2
	local PlayerFaceAddress = Player1Address + 3
	local PlayerSpriteAddress = Player1Address + 1
	local PlayerExtra1Address = Player1Address + 4
	local PlayerExtra2Address = Player1Address + 5
	local PlayerExtra3Address = Player1Address + 6
	local PlayerExtra4Address = Player1Address + 7

	if SpriteSize == "16x8" then
		Facing = Facing - 128
		SpriteSize = 64
	elseif SpriteSize == "16x16" then
		Facing = Facing - 64
		SpriteSize = 0
	elseif SpriteSize == "16x32" then
		SpriteSize = 128
	elseif SpriteSize == "32x32" then
		SpriteSize = 0
	end
	if X < 0 then X = X + 511 end
	if X > 255 then --Technically X is 9 bits, sooo...
		X = X - 255
		Facing = Facing + 1
	end

	if OGSCap then OGSTouched[(Player1Address - OGSCapBase) // 8] = true end
	OGSW8(PlayerXAddress, X)
	OGSW8(Player1Address, Y)
	OGSW8(PlayerFaceAddress, Facing)
	OGSW8(PlayerSpriteAddress, SpriteSize)
	OGSW16(PlayerExtra1Address, ConstructSprite)
	OGSW8(PlayerExtra3Address, Extra3)
	OGSW8(PlayerExtra4Address, Extra4)
end

function UpdatePlayerConsole()
	if #players > 1 and Hosting then
		ConsoleForText:moveCursor(0,4)
		ConsoleForText:print("Players found!												  ")
	elseif Hosting then
		ConsoleForText:moveCursor(0,4)
		ConsoleForText:print("Searching for players...												")
	end
	local consoleIDs = MaxPlayers
	if consoleIDs < 0 then
		consoleIDs = 8
		for _, p in ipairs(players) do if p:GetID() > consoleIDs then consoleIDs = p:GetID() end end
	end
	for i = 1, consoleIDs do
		local player = FindPlayerByID(i)
		local ConsoleLine = i + 9
		if player then
			if i > 1 then
				--console:log("ADDING " .. player:GetID() .. " TO LINE " .. ConsoleLine)
				ConsoleForText:moveCursor(0, ConsoleLine)
				if player:GetID() == PlayerID then
					ConsoleForText:print("Player ID " .. player:GetID() .. ": " .. player:GetNickname()  .. " (You)							")
				else
					ConsoleForText:print("Player ID " .. player:GetID() .. ": " .. player:GetNickname()  .. "							")
				end
			else
				--	console:log("ADDING HOST " .. player:GetID() .. "TO LINE " .. ConsoleLine)
				ConsoleForText:moveCursor(0,ConsoleLine)
				ConsoleForText:print("Host: " .. player:GetNickname()  .. "										")
			end
		else
			ConsoleForText:moveCursor(0,ConsoleLine)
			ConsoleForText:print("																		")
		end
	end
	--Workaround
	if #players > 1 and Connected then
		local player = FindPlayerByID(1)
		if player then
			ConsoleForText:moveCursor(0,9)
			ConsoleForText:print("																		")
			ConsoleForText:moveCursor(0,10)
			ConsoleForText:print("Host: " .. player:GetNickname()  .. "										")
		end
	end
end



