function MPT(text)
	local t = MPLoc[Language]
	return (t and t[text]) or text
end
function MPTF(format, ...)
	local ok, r = pcall(string.format, MPT(format), ...)
	if ok then return r end
	return string.format(format, ...)
end
--bytes of a label in the character table of the game (UTF-8 text -> game codes)
function MPEncode(text)
	local out = {}
	for _, cp in utf8.codes(text) do
		local ch = utf8.char(cp)
		local c = LanguageTable[LanguageTableType][ch] or LanguageTable["Western"][ch] or 0
		out[#out + 1] = c
	end
	return out
end
--The 8 MB Japanese Ruby/Sapphire ROMs end before 0x8A7FC00. Their free block 0x8658000..0x867D000 (padding) is used instead:
--every free space address of the mod is moved by the same distance (see MPAdjustFreeSpace, gAddress.gScriptData etc. of AXVJ/AXPJ).
MPFreeSpaceShift = {AXVJ = 0x8658000 - MPFreeRom.keypadList, AXPJ = 0x8658000 - MPFreeRom.keypadList}
function MPAdjustFreeSpace()
	local shift = MPFreeSpaceShift[GameID]
	if not shift then return end
	MPLabelAddress = MPFreeRom.label + shift
	MPKeypadList = MPFreeRom.keypadList + shift
	MPKeypadText = MPFreeRom.keypadText + shift
end

