function MPMenuMode()
	return ServerType == "m" or ServerType == "M"
end

--a message box for the player (shown when the player is free, through the message queue of the dedicated server support)
function MPSay(text)
	text = string.gsub(text, "\n", "\\n")  --line break of the mod's text codes
	text = string.gsub(text, "\f", "\\p")  --new page
	if #ServerMsgQueue < 16 then ServerMsgQueue[#ServerMsgQueue + 1] = text end
end

--the console window of the script: cleared and written again, so nothing of an earlier state stays
function MPConsole(text)
	pcall(function()
		ConsoleForText:clear()
		ConsoleForText:moveCursor(0, 0)
		ConsoleForText:print("GBA-PK multiplayer " .. MPVersion)
		ConsoleForText:moveCursor(0, 2)
		ConsoleForText:print("Nickname is " .. tostring(Nickname))
		ConsoleForText:moveCursor(0, 3)
		ConsoleForText:print(text)
	end)
end

-- ------------------------------------------------------------------ the ini file
function MPIniPath()
	local ok, src = pcall(function() return debug.getinfo(1, "S").source end)
	if ok and type(src) == "string" and string.sub(src, 1, 1) == "@" then
		local dir = string.match(string.sub(src, 2), "^(.*[/\\])")
		if dir then return dir .. MPIniName end
	end
	return MPIniName
end

--reads the file into MPIni (keys that are missing stay nil)
function MPIniRead()
	local ok, f = pcall(io.open, MPIniPath(), "r")
	MPIni = {}
	if not ok or not f then return false end
	for line in f:lines() do
		local k, v = string.match(line, "^%s*([%w_]+)%s*=%s*(.-)%s*$")
		if k and v ~= "" then
			k = string.lower(k)
			if k == "ip" then MPIni.ip = v
			elseif k == "port" then MPIni.port = tonumber(v)
			elseif k == "mode" then MPIni.mode = v
			elseif k == "friendcode" then MPIni.code = string.upper(v)
			elseif k == "partner" then MPIni.partner = string.upper(v)
			elseif k == "soullink" then MPIni.soul = (v == "1" or string.lower(v) == "on")
			elseif k == "soullink_time" then MPIni.soulTime = tonumber(v)
			else MPIniDebugKey(MPIni, k, v) end
		end
	end
	f:close()
	return true
end

function MPIniWrite()
	local ok, f = pcall(io.open, MPIniPath(), "w")
	if not ok or not f then
		console:log("Could not write " .. MPIniPath())
		return false
	end
	local lines = {"[GBA-PK]"}
	if MPIni.ip then lines[#lines + 1] = "ip=" .. tostring(MPIni.ip) end
	if MPIni.port then lines[#lines + 1] = "port=" .. tostring(MPIni.port) end
	if MPIni.mode then lines[#lines + 1] = "mode=" .. tostring(MPIni.mode) end
	if MPIni.code then lines[#lines + 1] = "friendcode=" .. tostring(MPIni.code) end
	if MPIni.partner then lines[#lines + 1] = "partner=" .. tostring(MPIni.partner) end
	if MPIni.soul then lines[#lines + 1] = "soullink=1" end
	if MPIni.soulTime then lines[#lines + 1] = "soullink_time=" .. tostring(MPIni.soulTime) end
	lines[#lines + 1] = "log=" .. (MPIni.log and "on" or "off")
	lines[#lines + 1] = "debug=" .. (MPIni.debug and "on" or "off")
	if MPIni.dbg then
		local names = {}
		for name in pairs(MPIni.dbg) do names[#names + 1] = name end
		table.sort(names)
		for _, name in ipairs(names) do lines[#lines + 1] = "debug_" .. name .. "=" .. (MPIni.dbg[name] and "on" or "off") end
	end
	f:write(table.concat(lines, "\r\n") .. "\r\n")
	f:close()
	return true
end

--ip and port of the ini file, or nil when it has no address
function MPLoadIni()
	MPIniRead()
	if MPIni.ip and MPIni.ip ~= "" then return MPIni.ip, MPIni.port or Port end
	return nil
end

function MPSaveIni(ip, port)
	MPIni.ip = ip
	MPIni.port = port
	return MPIniWrite()
end

-- ------------------------------------------------------------------ game mode and friend code
function MPRandomCode()
	if not MPSeeded then
		math.randomseed(os.time() + math.floor(os.clock() * 100000))
		MPSeeded = true
	end
	local t = {}
	for i = 1, MPCodeLength do
		local n = math.random(1, #MPCodeChars)
		t[i] = string.sub(MPCodeChars, n, n)
	end
	return table.concat(t)
end

function MPValidCode(code)
	return type(code) == "string" and #code == MPCodeLength and string.match(code, "^[A-Z0-9]+$") ~= nil
end

--index of the current game mode in MPModes (the first one when the file names an unknown mode)
function MPModeIndex()
	if MPIni.mode == "Coop Doubles" then MPIni.mode = "Coop" end   --the mode is gone
	for i, m in ipairs(MPModes) do
		if m.name == MPIni.mode and not (m.name == "Versus" and not MPMon.Standard) then return i end
	end
	return 1
end

function MPMode()
	return MPModes[MPModeIndex()]
end

--direction 1 / -1: the next / previous game mode
--why the game mode does not work with the paired partner: "engine" (another battle engine), "family" (Coop: another game family),
--"own" (Versus: the Pokemon of this game are not in the layout of the decomp), or nil when it works / there is nothing to work with
function MPModeOffReason()
	local n = MPGameMode()
	if n ~= "Coop" and n ~= "Versus" then return nil end
	if n == "Versus" and not MPMon.Standard then return "own" end
	local id = MPPartnerID()
	if not id then return nil end
	local p = FindPlayerByID(id)
	if not p then return nil end
	if not MPSameEngine(id) then return "engine" end
	if n == "Coop" and gAddress[GameID] and MPCoopFamily(p:GetGameID()) ~= gAddress[GameID].sGameVersion then return "family" end
	return nil
end

--the text of the mode that was switched to: one short box, OFF when the games vary too much
function MPModeText(name)
	if name == "Free Roam" then return MPT("Free Roam: no sharing.") end
	if MPModeOffReason() then return MPTF("%s OFF: games differ.", MPT(name)) end
	if name == "Coop" then return MPT("Coop ON: trainers, money\nand items are shared.") end
	return MPT("Versus ON: your partner\nplays the trainers.")
end

--once per partner and mode: the mode does not work because the games differ
function MPModeNote()
	local why = MPModeOffReason()
	if not why then return end
	local id = MPPartnerID()
	local key = MPGameMode() .. tostring(id)
	if MPEngineWarned[key] then return end
	MPEngineWarned[key] = true
	MPSay(MPModeText(MPGameMode()))
end

function MPChangeMode(direction)
	local i = MPModeIndex() + (direction or 1)
	if i > #MPModes then i = 1 end
	if i < 1 then i = #MPModes end
	if MPModes[i].name == "Versus" and not MPMon.Standard then      --the trainer team is built in the layout of the decomp
		i = i + (direction or 1)
		if i > #MPModes then i = 1 end
		if i < 1 then i = #MPModes end
	end
	MPIni.mode = MPModes[i].name   --a saved pairing stays, it is only not used in a mode without pairing
	MPIniWrite()
	MPModeSync()
	MPSay(MPModeText(MPModes[i].name))
end

--name of the game mode (for the parts of the script that change the game)
function MPGameMode()
	return MPMode().name
end

--reads the ini file and makes sure there is a mode and a friend code
function MPSettingsInit()
	MPIniRead()
	local changed = false
	--the first start makes the file: address and port of the top of this script, the mode and a friend code. From then on the file
	--is what counts (delete it to make it again)
	if not MPIni.ip or MPIni.ip == "" then MPIni.ip = IPAddress changed = true end
	if not MPIni.port then MPIni.port = Port changed = true end
	if not MPValidCode(MPIni.code) then MPIni.code = MPRandomCode() changed = true end
	if not MPIni.mode then MPIni.mode = MPModes[1].name changed = true end
	if MPIni.partner and not MPValidCode(MPIni.partner) then MPIni.partner = nil changed = true end
	if MPIni.log == nil then MPIni.log = false changed = true end            --log / debug: off, the lines are written so they can be found
	if MPIni.debug == nil then MPIni.debug = false changed = true end
	if changed then MPIniWrite() end
end

--name of the town / route / area of a map of another player (or nil). gameId is the game of that player
function MPMapName(gameId, mapId)
	local prefix = string.sub(tostring(gameId), 1, 3)
	local fam = (prefix == "BPR" or prefix == "BPG") and "FRLG" or (prefix == "BPE" and "E") or ((prefix == "AXV" or prefix == "AXP") and "RS") or nil
	if not fam or not MPMapSection or not MPMapSection[fam] or not mapId then return nil end
	local row = MPMapSection[fam][mapId & 0xFF]
	local idx = row and row[(mapId >> 8) + 1]
	if idx and idx > 0 then return MPSectionNames[idx] end
	return nil
end

--the id of the player on this server whose friend code is the partner, or nil
function MPPartnerID()
	if not MPIni.partner then return nil end
	for id, code in pairs(MPFriendCodes) do
		if code == MPIni.partner and FindPlayerByID(id) then return id end
	end
	return nil
end

-- the friend codes travel in packets of their own (64 bytes like the others): game id, FFFF, sender id + 1000, target id + 1000, the
-- type, the payload, filler, "U". Everything that is not for the host is passed on by the host / dedicated server unchanged.
--   FRCD  own friend code (4) + the friend code that player has entered for pairing, "----" when none (4)
--   FRRQ  request to pair: own friend code (4)
--   FRRP  answer to a request: own friend code (4) + "Y" accepted / "N" declined
function MPSendPacket(kind, id, payload)
	if not id or id == PlayerID or id == 0 then return false end
	if DedicatedServer and id == 1 then return false end        --the dedicated server is nobody to pair with
	local me = FindPlayerByID(PlayerID)
	local target = FindPlayerByID(id)
	if not me or not target then return false end
	local sock = Hosting and target:GetSocket() or SocketMain
	if not sock then return false end
	local frame = tostring(me:GetGameID()) .. "FFFF" .. string.format("%04d%04d", PlayerID + 1000, id + 1000) .. kind .. payload
	frame = frame .. string.rep("F", 63 - #frame) .. "U"
	if #frame ~= 64 then return false end
	NetSend(sock, frame)
	return true
end

function MPSendCode(id)
	if not MPValidCode(MPIni.code) then return end
	if MPSendPacket("FRCD", id, MPIni.code .. (MPIni.partner or "----") .. MPModeChar()) then MPSentCode[id] = true end
end

function MPAnnounceCode()
	for _, p in ipairs(players) do
		if p:GetID() ~= PlayerID then MPSendCode(p:GetID()) end
	end
end

--a friend code arrived from player id
function MPFriendCodeReceive(id, data)
	local code = string.sub(data, 21, 20 + MPCodeLength)
	if not MPValidCode(code) then return end
	local partner = string.sub(data, 21 + MPCodeLength, 20 + 2 * MPCodeLength)
	MPFriendCodes[id] = code
	MPFriendPartner[id] = MPValidCode(partner) and partner or nil
	MPFriendMode[id] = string.sub(data, 21 + 2 * MPCodeLength, 21 + 2 * MPCodeLength)
	if not MPSentCode[id] then MPSendCode(id) end
	if MPIni.partner and code == MPIni.partner then
		local p = FindPlayerByID(id)
		console:log("Your paired friend is here: " .. tostring(p and p:GetNickname() or id) .. " (" .. code .. ")")
	end
end

--asks the player with the id to pair with us too (they choose)
function MPSendPairRequest(id)
	return MPSendPacket("FRRQ", id, MPIni.code)
end

--a request (FRRQ) or an answer (FRRP) arrived
function MPPairPacket(kind, id, data)
	local code = string.sub(data, 21, 20 + MPCodeLength)
	if not MPValidCode(code) then return end
	local p = FindPlayerByID(id)
	local who = tostring(p and p:GetNickname() or MPTF("Player %s", tostring(id)))
	if kind == "FRRQ" then
		if not MPMenuMode() then return end
		if MPPairAsked[id] == code then return end        --asked already
		if MPIni.partner == code then
			MPSendPacket("FRRP", id, MPIni.code .. "Y")   --already paired with them: nothing to ask
			return
		end
		MPPairAsked[id] = code
		MPPairRequests[#MPPairRequests + 1] = {id = id, code = code}
	elseif kind == "FRRP" then
		local answer = string.sub(data, 21 + MPCodeLength, 21 + MPCodeLength)
		if answer == "Y" then
			MPSay(MPTF("%s accepted\nyour friend code.", who))
		else
			MPSay(MPTF("%s declined\nthe pairing.", who))
		end
	end
end

function MPOnPlayerAdded(id)
	if MPMenuMode() and id ~= PlayerID then MPSendCode(id) end
end

function MPOnPlayerRemoved(id)
	MPFriendCodes[id] = nil
	MPFriendPartner[id] = nil
	MPSentCode[id] = nil
	MPPairAsked[id] = nil
	for i = #MPPairRequests, 1, -1 do
		if MPPairRequests[i].id == id then table.remove(MPPairRequests, i) end
	end
end

-- ------------------------------------------------------------------ state of the game
--the variables 0x8000... are only refreshed by MainLogic, which does not run without a network
function MPRefreshVars()
	local base = gAddress[GameID] and gAddress[GameID].gSpecialVar_8000
	if base and base > 0 then
		for i = 1, 14 do
			Var8000Adr[i] = base + (i - 1) * 2
			Var8000[i] = tonumber(emu:read16(Var8000Adr[i]))
		end
	end
end

--the player object of this player while there is no network (a lot of code expects it to exist)
function MPAddIdle()
	if #players == 0 and GameID then
		PlayerID = 0
		AddPlayer(0, SocketMain, Nickname, GameID, GetPosition())
	end
end

function MPResetGameState()
	if LockFromScript ~= 40 and LockFromScript ~= 50 then LockFromScript = 0 end
	TextSpeedWait = 0
	NetOwnPacket = nil
	MPFriendCodes = {}
	MPFriendPartner = {}
	MPSentCode = {}
	MPPairAsked = {}
	MPPairRequests = {}
end

-- The START menu draws its entries when it opens and again whenever a part of it ends (the save question, a screen like the bag).
-- The entry says MULTI only around those moments (START pressed, a part of the menu active, back from a screen) and EXIT the rest
-- of the time, also while the menu just waits for a button. A script that is removed leaves the game's own EXIT behind.
MPLabelOn = false
MPLabelHold = 0           --frame until which the label stays MULTI
MPLabelSubmenus = true    --true: MULTI also while a part of the START menu is active (the save question...): the menu is drawn
--again when it ends and must say MULTI then. false: only the frames after START / coming back from a screen
MPLabelFrames = 20        --how many frames: the START menu draws its entries in the first frames after it opened
MPPrevInMenu = false
MPMenuOpen = false        --the START menu is open (opened by START, until the game is free again)
MPOpenIdle = 0
MPMenuReady = false

--writes the text of the label into free ROM space. Only when the table really is the one of this (English) build
function MPPatchMenu()
	local a = MPAddress[GameID]
	MPMenuReady = false
	if not a or not ROMCARD then return false end
	if ROMCARD:read32(a.entry + 4) ~= a.func then return false end
	local pointer = ROMCARD:read32(a.entry)
	if pointer ~= a.text and pointer ~= MPLabelAddress then return false end   --not the entry we know
	local codes = MPEncode(MPT(MPLabel))
	for i = 1, #codes do
		ROMCARD:write8(MPLabelAddress + i - 1, codes[i])
	end
	ROMCARD:write8(MPLabelAddress + #codes, 0xFF)
	ROMCARD:write32(a.entry, a.text)         --EXIT until the player opens the menu
	MPLabelOn = false
	MPMenuReady = true
	return true
end

--the entry says MULTI (on) or EXIT (off)
function MPSetLabel(on)
	local a = MPAddress[GameID]
	if not MPMenuReady or not a or not ROMCARD then return end
	if on ~= MPLabelOn then
		ROMCARD:write32(a.entry, on and MPLabelAddress or a.text)
		MPLabelOn = on
	end
end

--puts the original text (EXIT) back. Also called when the script is stopped or its Lua state is closed
function MPRestoreMenu()
	local ok = pcall(function()
		local a = MPAddress[GameID]
		if a and a.text and ROMCARD and ROMCARD:read32(a.entry) == MPLabelAddress then
			ROMCARD:write32(a.entry, a.text)
			MPLabelOn = false
		end
	end)
	return ok
end

--called when the game reads the buttons (before it handles them): START was pressed, so the menu opens now
function MPKeyHook()
	if not MPMenuReady or not MPMenuMode() or not EnableScript then return end
	if (emu:getKeys() & 8) ~= 0 then
		MPSetLabel(true)
		MPLabelHold = TotalFrame + MPLabelFrames
		--START in the free field opens the START menu: it counts as open until the game is free again
		if emu:read8(gAddress[GameID].gLockControls) == 0 and IsInMenu() == 0 then
			MPMenuOpen = true
			MPOpenIdle = 0
		end
	end
end

--when the Lua state of the script is closed (the script is removed or reset in mGBA) this runs and gives the menu entry back
MPSentinel = setmetatable({}, {__gc = function() MPRestoreMenu() end})

--called by StartScript (also after a reset of the game, which restores the ROM)
function MPOnStart()
	MPRefreshVars()
	MPState = 0
	MPRequest = nil
	--the game keeps the function of the last chosen START menu entry in its variable until the menu is opened again: whatever it holds
	--now was chosen before this script started and must not open the menu
	local a = MPAddress[GameID]
	MPPrevCallback = a and emu:read32(a.callback) or 0
	MPLabelHold = 0
	MPMenuOpen = false
	MPRememberMultichoice()
	MPSettingsInit()
	if MPPatchMenu() then
		MPConsole("Multiplayer: START menu > " .. MPLabel .. ". Console: host(), connect(), disconnect()")
	else
		MPConsole("No START menu entry for this game version. Console: host(), connect(), disconnect()")
		console:log("Multiplayer menu: the START menu entry is only available for English builds of FireRed, LeafGreen, Emerald, Ruby and Sapphire. Use host() and connect() in this console.")
	end
	MPAddIdle()
end

-- ------------------------------------------------------------------ hosting and connecting
function MPHost()
	if Hosting or Connected then return false, "busy" end
	local sock = socket:tcp()
	local ok, err = sock:bind(nil, Port)
	if not ok then
		pcall(sock.close, sock)
		console:log("Hosting could not be started: " .. tostring(err))
		return false, err
	end
	sock:listen()
	SocketMain = sock
	players = {}
	Hosting = true
	PlayerID = 1
	AddPlayer(PlayerID, SocketMain, Nickname, GameID, GetPosition())
	MPConsole("Hosting game on port " .. tostring(Port) .. ". Port forwarding may be required.")
	pcall(UpdatePlayerConsole)
	return true
end

function MPStopHost()
	if not Hosting then return end
	local ids = {}
	for _, p in ipairs(players) do
		if p:GetID() ~= PlayerID then ids[#ids + 1] = p:GetID() end
	end
	for _, id in ipairs(ids) do RemovePlayer(id) end            --flushes and closes their connections
	for i = #temp_players, 1, -1 do pcall(RemoveTempPlayer, temp_players[i]) end
	NetForget(SocketMain)
	NetUnhook(SocketMain)
	pcall(SocketMain.close, SocketMain)
	SocketMain = socket:tcp()
	Hosting = false
	players = {}
	PlayerID = 0
	ServerNPCReset()
	MPResetGameState()
	MPAddIdle()
	MPConsole("Not hosting.")
end

function MPConnect(ip, port)
	if Hosting or Connected then return false, "busy" end
	ip = ip or IPAddress
	port = port or Port
	MPLastIP, MPLastPort = ip, port
	local sock = socket:tcp()
	local ok, err = sock:connect(ip, port)   --blocks the emulator until the connection is made or refused
	if not ok then
		pcall(sock.close, sock)
		console:log("Could not connect to " .. tostring(ip) .. ":" .. tostring(port) .. ": " .. tostring(err))
		MPConsole("Could not connect to " .. tostring(ip) .. ":" .. tostring(port))
		return false, err
	end
	SocketMain = sock
	players = {}
	PlayerID = 0
	Connected = true
	NetUnhook(SocketMain)
	MPConnectPending = true
	MPConnectSince = TotalFrame
	MPRefusedCode = nil
	SendData(SocketMain, "Request")
	MPConsole("Connecting to " .. tostring(ip) .. ":" .. tostring(port) .. "...")
	return true
end

--leaves the server without a message (used by the menu and by the failed connections)
function MPDropConnection()
	NetForget(SocketMain)
	NetUnhook(SocketMain)
	pcall(SocketMain.close, SocketMain)
	SocketMain = socket:tcp()
	Connected = false
	MPConnectPending = false
	players = {}
	PlayerID = 0
	ServerNPCReset()
	MPResetGameState()
	MPAddIdle()
	MPConsole("Not connected.")
end

function MPDisconnect()
	if Connected then MPDropConnection() end
end

--Disconnect() (the server went away or stopped answering) in menu mode: no automatic reconnect
function MPAfterDisconnect()
	MPConnectPending = false
	MPResetGameState()
	MPAddIdle()
	MPConsole("Not connected.")
	MPSay(MPT("Lost the connection\nto the server."))
end

--the server refused the join (RFSE): 1 the nickname is used, 2 the server is full
function MPRefused(code)
	if MPMenuMode() and MPConnectPending then MPRefusedCode = code end
end

-- ------------------------------------------------------------------ menus
--asks the player something: opens a list menu (kind is what MPOnChoice gets back)
function MPAsk(kind, title, options)
	MPRequest = {kind = kind, title = title, options = options}
	MPState = 1
	MPWait = 0
	MPRequestAt = TotalFrame
end

--asks Yes / No, yes runs the function. no (optional) runs when the answer is No (else the settings are shown again)
function MPConfirm(title, yes, no)
	MPConfirmYes = yes
	MPConfirmNo = no
	MPAsk("confirm", title, {MPT("Yes"), MPT("No")})
end

--the keypad for the address (kind "ip"), the port ("port") or a friend code ("code")
function MPKeypad(kind, text, note)
	MPKeyKind = kind
	MPKeyText = text or ""
	MPKeyNote = note
	MPRequest = {kind = "key"}
	MPState = 1
	MPWait = 0
	MPRequestAt = TotalFrame
end

--the text of the box that says which address did not work
function MPFailText(ip, port)
	local line = MPTF("IP %s port %s", tostring(ip), tostring(port))
	if #line > 25 then line = "IP " .. tostring(ip) .. "\f" .. MPT("Port") .. " " .. tostring(port) end
	return MPT("Connection failed with") .. "\n" .. line
end

--tries to connect; when it does not work the player is asked whether to type another address
function MPTryConnect(ip, port)
	local ok = MPConnect(ip, port)
	if not ok and not Hosting and not Connected then
		MPSay(MPFailText(ip, port))                                  --first a box that says what failed ...
		MPAsk("retry", MPT("Try a different IP?"), {MPT("Yes"), MPT("No")})         --... then a new box with the question
	end
end

function MPStartConnect()
	local ip, port = MPLoadIni()
	if not ip then ip, port = IPAddress, Port end
	MPTryConnect(ip, port)
end

function MPKeyLimit()
	if MPKeyKind == "ip" then return 15 elseif MPKeyKind == "code" then return MPCodeLength end
	return 5
end

--the keys of the keypad that is on the screen
function MPCurrentKeys()
	if MPKeyKind == "code" then return MPCodeKeys end
	return MPKeypadKeys
end

--the player pressed a key of the keypad (choice = index + 1, 128 = B button)
function MPKeyChoice(choice)
	local key = (choice == 128) and "Back" or MPCurrentKeys()[choice]
	local text = MPKeyText
	MPKeyNote = nil
	if key == nil then
		-- nothing
	elseif key == "Back" then
		if MPKeyKind == "port" then
			MPKeypad("ip", MPKeyIP or MPLastIP or IPAddress)
		elseif MPKeyKind == "code" then
			MPOpenSettings()                           --Back on the friend code: the settings
		end
		return                                         --Back on the address: the menu is closed
	elseif key == "OK" then
		if MPKeyKind == "ip" then
			local a, b, c, d = string.match(text, "^(%d+)%.(%d+)%.(%d+)%.(%d+)$")
			local valid = a and #a <= 3 and #b <= 3 and #c <= 3 and #d <= 3 and tonumber(a) <= 255 and tonumber(b) <= 255 and tonumber(c) <= 255 and tonumber(d) <= 255
			if valid then
				MPKeyIP = text
				MPKeypad("port", tostring(MPLastPort or Port))
			else
				MPKeypad("ip", text, MPT("Not a valid IP address!"))
			end
		elseif MPKeyKind == "port" then
			local port = tonumber(text)
			if port and port >= 1 and port <= 65535 then
				MPSaveIni(MPKeyIP, port)
				MPTryConnect(MPKeyIP, port)
			else
				MPKeypad("port", text, MPT("Port: 1 to 65535"))
			end
		else
			if not MPValidCode(text) then
				MPKeypad("code", text, MPTF("The code has %s characters", tostring(MPCodeLength)))
			elseif text == MPIni.code then
				MPKeypad("code", text, MPT("That is your own code"))
			else
				MPIni.partner = text
				MPIniWrite()
				MPSentCode = {}
				MPAnnounceCode()                               --the others see who we paired with
				MPSay(MPTF("Paired with friend code\n%s.", text))
				MPConfirm(MPT("Ask that player to pair\nwith you too?"), function()
					local id = MPPartnerID()
					if id and MPSendPairRequest(id) then
						MPSay(MPT("Request sent."))
					else
						MPSay(MPT("That player is not on\nthe server right now."))
					end
					MPOpenSettings()
				end)
			end
		end
		return
	elseif key == "123" then
		MPKeyPage = "digits"
		MPCodeKeys = MPCodeDigits
	elseif key == "ABC" then
		MPKeyPage = "letters"
		MPCodeKeys = MPCodeLetters
	elseif key == "Del" then
		text = string.sub(text, 1, -2)
	elseif key == "Clr" then
		text = ""
	elseif key == "." then
		local _, dots = string.gsub(text, "%.", "")
		if MPKeyKind == "ip" and text ~= "" and string.sub(text, -1) ~= "." and dots < 3 and #text < MPKeyLimit() then text = text .. "." end
	else
		if #text < MPKeyLimit() then text = text .. key end
	end
	MPKeypad(MPKeyKind, text, nil)
end

-- ------------------------------------------------------------------ settings
--the entries of the settings list. Pairing is only listed in the modes that use it. MPSettingsActions says what every line does
function MPSettingsLabels()
	local mode = MPMode()
	local mark = ""
	if mode.name ~= "Free Roam" then mark = MPModeOffReason() and " OFF" or " ON" end       --OFF: the games vary too much for this mode
	local labels, actions = {MPTF("Mode:%s", MPT(mode.name) .. mark)}, {"mode"}
	if mode.pair then
		labels[#labels + 1] = MPIni.partner and MPT("Clear Pairing") or MPT("Pair Friend")
		actions[#actions + 1] = "pair"
		labels[#labels + 1] = MPT("Check Pairing")
		actions[#actions + 1] = "check"
	end
	labels[#labels + 1] = MPSoulLabel()
	actions[#actions + 1] = "soul"
	labels[#labels + 1] = MPTF("Code: %s", tostring(MPIni.code))
	actions[#actions + 1] = "code"
	labels[#labels + 1] = MPT("Exit")
	actions[#actions + 1] = "exit"
	MPSettingsActions = actions
	return labels
end

function MPOpenSettings()
	MPKeyNote = nil
	local info = MPModeOffReason() and MPT("Off: games too different") or MPT(MPMode().desc)
	MPAsk("settings", MPTF("Game Mode Info:\n%s", info), nil)   --the info of the mode is shown above the list
end

--says who the player is paired with, whether that player is on the server, where, and whether they entered our code too
function MPCheckPairing()
	if not MPIni.partner then
		MPSay(MPT("You are not paired."))
		return
	end
	local text = MPTF("Paired with code\n%s", MPIni.partner)
	local id = MPPartnerID()
	if id then
		local p = FindPlayerByID(id)
		local who = tostring(p and p:GetNickname() or MPTF("Player %s", tostring(id)))
		local place = nil
		if p then
			local ok, _, _, _, mapId = pcall(function() return p:GetCoords() end)
			if ok then place = MPMapName(p:GetGameID(), mapId) end
		end
		if place then
			text = text .. "\f" .. MPTF("%s is online,\nin %s.", who, place)
		else
			text = text .. "\f" .. MPTF("%s is online.", who)
		end
		local theirs = MPFriendPartner[id]
		if theirs == MPIni.code then
			text = text .. "\f" .. MPT("Paired both ways.")
		elseif theirs then
			text = text .. "\f" .. MPTF("%s is paired\nwith someone else.", who)
		else
			text = text .. "\f" .. MPTF("%s has not\nentered your code.", who)
		end
	else
		text = text .. "\f" .. MPT("That player is not online.")
	end
	MPSay(text)
end

function MPSettingsChoice(choice)
	local action = (choice == 128) and "exit" or MPSettingsActions[choice]
	if action == "mode" then
		MPChangeMode(1)                                  --a click goes to the next mode
		MPOpenSettings()
	elseif action == "pair" then
		if MPIni.partner then
			local who = MPIni.partner
			local id = MPPartnerID()
			local p = id and FindPlayerByID(id)
			if p then who = p:GetNickname() end
			MPConfirm(MPTF("Clear the pairing with\n%s?", who), function()
				MPIni.partner = nil
				MPIniWrite()
				MPSentCode = {}
				MPAnnounceCode()
				MPSay(MPT("Pairing cleared."))
				MPOpenSettings()
			end)
		else
			MPKeyPage = "letters"
			MPCodeKeys = MPCodeLetters
			MPKeypad("code", "", nil)
		end
	elseif action == "check" then
		MPCheckPairing()
		MPOpenSettings()
	elseif action == "soul" then
		MPSoulToggle()
		MPOpenSettings()
	elseif action == "code" then
		MPConfirm(MPT("Change your friend code?"), function()
			MPIni.code = MPRandomCode()
			MPIniWrite()
			MPSentCode = {}
			MPAnnounceCode()
			MPSay(MPTF("Your friend code is now\n%s", MPIni.code))
			MPOpenSettings()
		end)
	else
		MPAsk("main", MPT("Multiplayer\nWhat would you like to do?"), nil)    --Exit (or B): the multiplayer menu again
	end
end

--what the player chose in the main menu (1 Host / Stop Hosting, 2 Connect / Disconnect, 3 Settings, 4 Cancel)
function MPChoose(choice)
	if choice == 1 then
		if Hosting then
			MPStopHost()
			MPSay(MPT("Server closed."))
		elseif Connected then
			MPSay(MPT("You are connected to a\nserver. Disconnect first."))
		else
			local ok, err = MPHost()
			if ok then
				MPSay(MPTF("Server opened!\nPort %s is open.", tostring(Port)))
			else
				MPSay(MPT("The server could not be\nopened.\fTry again from the\nmultiplayer menu."))
			end
		end
	elseif choice == 2 then
		if Connected then
			MPDisconnect()
			MPSay(MPT("Disconnected."))
		elseif Hosting then
			MPSay(MPT("You are hosting. Stop\nhosting first."))
		else
			MPStartConnect()
		end
	elseif choice == 3 then
		MPOpenSettings()
	end
end

function MPOnChoice(kind, choice)
	if kind == "main" then
		MPChoose(choice)
	elseif kind == "retry" then
		if choice == 1 then
			MPKeypad("ip", MPLastIP or IPAddress)
		end
	elseif kind == "settings" then
		MPSettingsChoice(choice)
	elseif kind == "confirm" then
		local yes, no = MPConfirmYes, MPConfirmNo
		MPConfirmYes, MPConfirmNo = nil, nil
		if choice == 1 and yes then
			yes()
		elseif no then
			no()
		else
			MPOpenSettings()
		end
	elseif kind == "learn" then
		MPLvlChoice(choice)
	elseif kind == "key" then
		MPKeyChoice(choice)
	end
end

--the list of the game (entry 2 of the multichoice table) that the menus replace: the original is remembered at the start
function MPRememberMultichoice()
	local g = gAddress[GameID]
	if not g or not g.gMultiChoice or not ROMCARD then return end
	local pointer = ROMCARD:read32(g.gMultiChoice)
	local ours = pointer == g.gMultiChoiceData or pointer == MPKeypadList
	if not ours and MPInRom(pointer) then
		MPMultiOrig = {pointer, ROMCARD:read8(g.gMultiChoiceAmount)}
	end
end

--the menu script replaced the entries of a multichoice list of the game: put them back (also when the menu was interrupted)
function MPRestoreMultichoice()
	local g = gAddress[GameID]
	if not g or not ROMCARD then return end
	local pointer, count = nil, nil
	if PrevExtraAdr ~= 0 then
		pointer, count = PrevExtraAdr, PrevExtraAdrNum
	elseif MPMultiOrig then
		local now = ROMCARD:read32(g.gMultiChoice)
		if now == g.gMultiChoiceData or now == MPKeypadList then pointer, count = MPMultiOrig[1], MPMultiOrig[2] end
	end
	if pointer then
		ROMCARD:write32(g.gMultiChoice, pointer)
		ROMCARD:write8(g.gMultiChoiceAmount, count)
	end
	PrevExtraAdr = 0
	PrevExtraAdrNum = 0
end

--gives up the menu that is open or waiting and makes everything free again. Used when the game was interrupted (a trainer, a
--wild Pokemon, a script of the game...) and when something is wrong.
function MPAbort(reason)
	if reason then console:log("Multiplayer menu closed: " .. tostring(reason)) end
	if LockFromScript == 50 then LockFromScript = 0 end
	MPState = 0
	MPRequest = nil
	MPActiveKind = nil
	MPConfirmYes = nil
	MPNoLockFrames = 0
	MPMenuBusyFrames = 0
	pcall(MPRestoreMultichoice)
	--our script waits for a choice that will never come (its menu is gone): without this the script engine of the game stays
	--waiting and the game does not take the controls back. A script of the game (a trainer...) is left alone.
	pcall(function()
		if MPScriptStatus() ~= 2 and MPScriptIsOurs() then
			emu:write8(gAddress[GameID].gScriptLoad, 2)
		end
	end)
end

--status of the script engine of the game: 0 running, 1 waiting (a menu or message is open), 2 no script. It is the first byte
--of the area the mod loads its scripts into (gScriptLoad), the context of the running script follows at +8 (its script pointer at +16)
function MPScriptStatus()
	return emu:read8(gAddress[GameID].gScriptLoad)
end

--is the script that is running one of ours (the pointer of the script engine is inside the area the mod loads scripts into)?
function MPScriptIsOurs()
	local g = gAddress[GameID]
	local ptr = emu:read32(g.gScriptLoad + 16)
	return ptr >= g.gScriptData and ptr < g.gScriptData + 0x100
end

--the player is free to get a menu: the game has no menu, message or script open
function MPPlayerFree()
	return FindPlayerByID(PlayerID) and LockFromScript == 0 and ServerMsgStart < 0 and #ServerMsgQueue == 0
	and emu:read8(gAddress[GameID].gLockControls) == 0 and IsInMenu() == 0
	and (MPScriptStatus() == 2 or TotalFrame - MPRequestAt > 600)   --(after 10 s the status is not looked at any more)
end

