	[128] = {14, 9},   --MAPSEC_S_S_ANNE
	[137] = {2, 3},   --MAPSEC_POKEMON_LEAGUE
	[133] = {11, 6},   --MAPSEC_ROCKET_HIDEOUT
	[187] = {18, 13},   --MAPSEC_BIRTH_ISLAND
	[174] = {10, 8},   --MAPSEC_NAVEL_ROCK
	[179] = {5, 6},   --MAPSEC_TRAINER_TOWER_2
	[175] = {2, 3},   --MAPSEC_MT_EMBER
	[176] = {14, 12},   --MAPSEC_BERRY_FOREST
