	[178] = {17, 11},   --MAPSEC_ROCKET_WAREHOUSE
	[191] = {9, 12},   --MAPSEC_DILFORD_CHAMBER
	[189] = {9, 12},   --MAPSEC_LIPTOO_CHAMBER
	[188] = {9, 12},   --MAPSEC_MONEAN_CHAMBER
	[193] = {9, 12},   --MAPSEC_RIXY_CHAMBER
