MPBase = {lastSent = nil, nextSend = 0, parts = {}, got = 0}

function MPBaseSend(id)
	local g = gAddress[GameID]
	local off = MPBaseOffset[g.sGameVersion]
	local base = off and MPCoopBase()
	if not base then return end
	local bytes = {}
	for i = 0, 159 do bytes[i] = emu:read8(base + off + i) end
	if bytes[0] == 0 then return end                          --no secret base of our own
	local hex = {}
	for i = 0, 159 do hex[#hex + 1] = string.format("%02X", bytes[i]) end
	local all = table.concat(hex)
	if all == MPBase.lastSent then return end
	MPBase.lastSent = all
	for part = 0, 7 do
		MPSendPacket("SBAS", id, tostring(part) .. string.sub(all, part * 42 + 1, part * 42 + 42))
	end
end

function MPBaseTick()
	if TotalFrame < MPBase.nextSend then return end
	MPBase.nextSend = TotalFrame + 300
	local id = MPCoopPartnerOK()
	if not id or not MPBaseOffset[gAddress[GameID].sGameVersion] then return end
	MPBaseSend(id)
end

function MPBaseReceive(id, data)
	if id ~= MPCoopPartner or MPGameMode() ~= "Coop" then return end
	local g = gAddress[GameID]
	local off = MPBaseOffset[g.sGameVersion]
	local base = off and MPCoopBase()
	if not base then return end
	local part = tonumber(string.sub(data, 21, 21))
	local hex = string.sub(data, 22, 63)
	if not part or part > 7 or not string.match(hex, "^%x+$") then return end
	MPBase.parts[part] = hex
	MPBase.got = MPBase.got | (1 << part)
	if MPBase.got ~= 0xFF then return end
	MPBase.got = 0
	local all = ""
	for i = 0, 7 do all = all .. (MPBase.parts[i] or "") end
	MPBase.parts = {}
	if #all < 320 then return end
	local rec = {}
	for i = 0, 159 do rec[i] = tonumber(string.sub(all, i * 2 + 1, i * 2 + 2), 16) end
	if rec[0] == 0 then return end
	local own = emu:read8(base + off)
	if rec[0] == own then return end                           --that spot is the player's own base
	--the slot: the same trainer's base that was stored earlier, else the first free one (slot 0 is the player's base)
	local slot
	for i = 1, 19 do
		local a = base + off + i * 160
		if emu:read8(a) ~= 0 then
			local same = true
			for k = 0, 10 do                                    --name (7) and trainer id (4): equal bytes
				if emu:read8(a + 2 + k) ~= rec[2 + k] then same = false break end
			end
			if same then slot = i break end
		elseif not slot then
			slot = i
		end
	end
	if not slot then return end
	for i = 0, 159 do emu:write8(base + off + slot * 160 + i, rec[i]) end
	MPBase.stored = slot
	console:log("Coop: the secret base of the partner was stored in slot " .. slot)
end

-- ------------------------------------------------------------------ the name of the player in the game is the nickname
-- A save that is loaded or the name that is entered in a new game changes the nickname of the script (when the script has no fixed
-- name): this player's name on the server follows, and the others are told (NICK packet).
MPNameNext = 0
MPNameLast = nil
function MPInGameNameRaw()
	local g = gAddress[GameID]
	local base = (g.sGameVersion ~= "RS") and emu:read32(g.gSaveBlock2Ptr) or g.gSaveBlock2Ptr
	if not MPInEwram(base) then return "" end
	local name = ""
	for i = 0, 7 do
		local b = emu:read8(base + i)
		if b == 0xFF then break end
		local letter = findKeyByValue(LanguageTable[LanguageTableType], b)
		if not letter then return "" end              --a byte that is no letter: the name is not (completely) there yet
		name = name .. letter
	end
	return name
end

function MPNameTick()
	if not MPNameAuto or TotalFrame < MPNameNext then return end
	MPNameNext = TotalFrame + 60
	local g = GameID and gAddress[GameID]
	if not g or not EnableScript then return end
	local name = MPInGameNameRaw()
	if name == "" or name == MPNameLast then return end
	MPNameLast = name
	if utf8_length(name) > 10 then name = utf8_cut(name, 10) end
	if name == Nickname then return end
	Nickname = name
	console:log("Your name in the game is " .. name .. ": it is your nickname now")
	pcall(function() ConsoleForText:moveCursor(0, 2) ConsoleForText:print("Nickname is now " .. Nickname .. "          ") end)
	local me = FindPlayerByID(PlayerID)
	if me then me.Nickname = Nickname end
	pcall(UpdatePlayerConsole)
	if Hosting then
		for _, p in ipairs(players) do
			if p:GetID() ~= PlayerID and p:GetSocket() ~= SocketMain then
				CreateSpecialPacket(p:GetSocket(), "NICK", p:GetID(), PlayerID)
			end
		end
	elseif Connected then
		SendSpecialData(SocketMain, "NICK", 1)
	end
end

MPHoenn = {pending = nil, wasOpen = false, bank = nil, patched = nil, nameOk = nil}

--where this player's icon is on the Hoenn map: {mapsec, cx, cy, outside, kanto = true when it can be drawn}
function MPHoennPlace()
	local a, g = MPHoennAddr[GameID], gAddress[GameID]
	if not a or not g then return nil end
	local sb = MPCoopBase()
	if not sb then return nil end
	local group, num = emu:read8(sb + 4), emu:read8(sb + 5)
	local function header(gr, nu)
		local arr = emu:read32(a.groups + gr * 4)
		if not MPInRom16(arr) then return nil end
		local h = emu:read32(arr + nu * 4)
		if not MPInRom16(h) then return nil end
		return h
	end
	local hd = header(group, num)
	if not hd then return nil end
	local mtype, rms, layout = emu:read8(hd + 0x17), emu:read8(hd + 0x14), emu:read32(hd)
	local x, y = emu:read16(sb), emu:read16(sb + 2)
	local outside = (mtype == 1 or mtype == 2 or mtype == 3 or mtype == 5 or mtype == 6)
	local function warp(off)
		local h2 = header(emu:read8(sb + off), emu:read8(sb + off + 1))
		if not h2 then return nil end
		return emu:read8(h2 + 0x14), emu:read32(h2), emu:read16(sb + off + 4), emu:read16(sb + off + 6)
	end
	local r2, l2, x2, y2
	if mtype == 4 or mtype == 7 then r2, l2, x2, y2 = warp(0x24)             --underground / unknown: escape warp
	elseif mtype == 9 then r2, l2, x2, y2 = warp(0x14)                       --secret base: dynamic warp
	elseif mtype == 8 then
		if rms ~= 87 then r2, l2, x2, y2 = warp(0x24) else r2, l2, x2, y2 = warp(0x14) end   --indoor (87 = MAPSEC_DYNAMIC)
	end
	if r2 then rms, layout, x, y = r2, l2, x2, y2 end
	local e = a.entries + rms * 8
	local ex, ey, ew, eh = emu:read8(e), emu:read8(e + 1), emu:read8(e + 2), emu:read8(e + 3)
	if ew == 0 or eh == 0 then return {mapsec = rms, kanto = false, outside = outside} end
	local w, h = emu:read32(layout), emu:read32(layout + 4)
	if w <= 0 or h <= 0 or w > 1000 or h > 1000 then w, h, x, y = ew, eh, 0, 0 end
	local scale = w // ew
	if scale == 0 then scale = 1 end
	local px = x // scale
	if px >= ew then px = ew - 1 end
	scale = h // eh
	if scale == 0 then scale = 1 end
	local py = y // scale
	if py >= eh then py = eh - 1 end
	return {mapsec = rms, cx = ex + px + 1, cy = ey + py + 2, kanto = true, outside = outside}
end

function MPHoennRestoreName()
	local r = MPHoenn.patched
	if not r then return end
	ROMCARD:write32(r.at, r.orig)
	MPHoenn.patched = nil
end

function MPHoennTick()
	local a, g = MPHoennAddr[GameID], gAddress[GameID]
	if not a or not g then return end
	local cb2 = emu:read32(g.gMainCallback)
	local open = cb2 == a.cb2 + 1
	local partner = MPCoopPartnerOK()
	local prog = partner and MPProgress[partner]
	if not open then
		if MPHoenn.wasOpen then
			MPHoenn.wasOpen = false
			MPHoennRestoreName()
			local p = MPHoenn.pending
			MPHoenn.pending = nil
			if p and cb2 == a.ret + 1 then
				local d = a.warp
				emu:write8(d, p.group) emu:write8(d + 1, p.num) emu:write8(d + 2, 0xFF)
				emu:write16(d + 4, p.x) emu:write16(d + 6, p.y)
				console:log("Coop: flying to the partner (map " .. p.group .. "," .. p.num .. " at " .. p.x .. "," .. p.y .. ")")
			end
		end
		return
	end
	MPHoenn.wasOpen = true
	if not prog or not prog.mapsec or not prog.kanto then
		MPHoennRestoreName()
		MPHoenn.pending = nil
		return
	end
	local reg = emu:read32(a.regionPtr)
	if not MPInEwram(reg) then return end
	-- the icon of this player and its entry in the OAM buffer
	local sprite = emu:read32(reg + 0x20)
	if MPInEwram(sprite) then
		local attr2 = emu:read16(sprite + 4)
		local oam = OGSOamBase()
		for i = 0, 126 do
			local e = oam + i * 8
			if emu:read16(e + 4) == attr2 and (emu:read16(e) >> 8) & 3 ~= 2 then
				local bank = MPHoenn.bank
				local own = attr2 >> 12
				if not bank or bank == own then MPHoenn.bank = MPRegionFreeBank(own) bank = MPHoenn.bank end
				if bank then
					for k = 0, 15 do
						local u = emu:read16(MPRegionRAM.plttUnfaded + 512 + own * 32 + k * 2)
						local f = emu:read16(MPRegionRAM.plttFaded + 512 + own * 32 + k * 2)
						emu:write16(MPRegionRAM.plttUnfaded + 512 + bank * 32 + k * 2, MPRegionRecolor(u))
						emu:write16(MPRegionRAM.plttFaded + 512 + bank * 32 + k * 2, MPRegionRecolor(f))
					end
				end
				local a0, a1 = emu:read16(e), emu:read16(e + 2)
				local px, py = prog.cx * 8 - 4, prog.cy * 8 - 4
				local slot = oam + 127 * 8
				emu:write16(slot, (a0 & 0xFF00) | (py & 0xFF))
				emu:write16(slot + 2, (a1 & 0xFE00) | (px & 0x1FF))
				emu:write16(slot + 4, bank and ((attr2 & 0x0FFF) | (bank << 12)) or attr2)
				break
			end
		end
	end
	-- the name of the section: "<place> <nickname>" (the pointer of its entry in gRegionMapEntries)
	local p = FindPlayerByID(partner)
	local nick = p and tostring(p:GetNickname()) or ""
	local at = a.entries + prog.mapsec * 8 + 4
	local r = MPHoenn.patched
	if not r or r.at ~= at or r.nick ~= nick then
		MPHoennRestoreName()
		if MPHoenn.nameOk == nil then
			MPHoenn.nameOk = true
			for i = 0, 31 do if emu:read8(MPRegionNameAt + i) ~= 0xFF then MPHoenn.nameOk = false end end
		end
		if MPHoenn.nameOk then
			local orig = emu:read32(at)
			local name = {}
			if MPInRom16(orig) then
				for i = 0, 30 do
					local c = emu:read8(orig + i)
					if c == 0xFF then break end
					name[#name + 1] = c
				end
			end
			local who = MPEncode(nick)
			local bytes = {}
			if #name + 1 + #who <= 19 then
				for _, c in ipairs(name) do bytes[#bytes + 1] = c end
				bytes[#bytes + 1] = 0x00
				for _, c in ipairs(who) do bytes[#bytes + 1] = c end
			else
				for i = 1, math.min(19, #who) do bytes[i] = who[i] end
			end
			bytes[#bytes + 1] = 0xFF
			for i, c in ipairs(bytes) do ROMCARD:write8(MPRegionNameAt + i - 1, c) end
			MPHoenn.patched = {at = at, orig = orig, nick = nick}
			ROMCARD:write32(at, MPRegionNameAt)
		end
	end
	-- flying to the partner: its section can be chosen when it is outside
	local cur = emu:read16(reg + a.secId)
	if cur == prog.mapsec and prog.outside and prog.group then
		emu:write8(reg + a.secType, 2)              --a city that can be flown to (type 2 in both games)
		MPHoenn.pending = {group = prog.group, num = prog.num, x = prog.x, y = prog.y}
	else
		MPHoenn.pending = nil
	end
end


-- ------------------------------------------------------------------ Coop: progress of the partner and the gym rule
-- PRGS  every second to the partner: badges (3 digits, count), map group (3), map number (3), x (4), y (4)
-- Rule (FireRed / LeafGreen): you can challenge a Gym Leader only when your partner has at least as many badges as the leader's
-- number minus one (the first gym is always open). The partner at 0 badges can not be left behind by more than one gym.
-- The fight is held back with the same replaced start of the trainer battle that Versus uses.
MPProgress = {}           --player id -> {badges, group, num, x, y, frame}
MPProgressNext = 0
--number (1 - 8) of the gym of a leader's trainer id, or nil. Hoenn: Roxanne 265, Brawly, Wattson, Flannery, Norman, Winona, Tate & Liza, Juan / Wallace 272
function MPGymNumber(trainer)
	local v = GameID and gAddress[GameID] and gAddress[GameID].sGameVersion
	if v == "FRLG" then return MPGyms[trainer] end
	if (v == "E" or v == "RS") and trainer >= 265 and trainer <= 272 then return trainer - 264 end
	return nil
end

--number of badges of this game (flags 0x820 - 0x827 of FireRed / LeafGreen)
function MPBadgeCount()
	local base = MPCoopBase()
	local info = base and MPCoopFlags[gAddress[GameID].sGameVersion]
	local first = MPBadgeFirst[gAddress[GameID].sGameVersion]
	if not info or not first then return 0 end
	local n = 0
	for f = first, first + 7 do
		if (emu:read8(base + info.offset + (f >> 3)) & (1 << (f & 7))) ~= 0 then n = n + 1 end
	end
	return n
end

--group, number, x, y of the player on the map (the save block)
function MPWhere()
	local base = MPCoopBase()
	if not base then return nil end
	return emu:read8(base + 4), emu:read8(base + 5), emu:read16(base) & 0x3FFF, emu:read16(base + 2) & 0x3FFF
end

function MPProgressTick()
	if TotalFrame < MPProgressNext then return end
	MPProgressNext = TotalFrame + 60
	local id = MPCoopPartnerOK()
	if not id then return end
	local group, num, x, y = MPWhere()
	if not group then return end
	local pl = MPRegionPlace()
	local extra = pl and string.format("%03d%02d%02d%d%d", pl.mapsec % 1000, pl.cx or 0, pl.cy or 0, pl.outside and 1 or 0, pl.kanto and 1 or 0) or "255000000"
	MPSendPacket("PRGS", id, string.format("%03d%03d%03d%04d%04d", MPBadgeCount(), group, num, x, y) .. extra)
end

function MPProgressReceive(id, data)
	local p = string.sub(data, 21, 37)
	local b, gr, nu, x, y = tonumber(string.sub(p, 1, 3)), tonumber(string.sub(p, 4, 6)), tonumber(string.sub(p, 7, 9)),
	tonumber(string.sub(p, 10, 13)), tonumber(string.sub(p, 14, 17))
	if not b or not gr or not nu or not x or not y then return end
	local e = string.sub(data, 38, 46)
	MPProgress[id] = {badges = b, group = gr, num = nu, x = x, y = y, frame = TotalFrame,
		mapsec = tonumber(string.sub(e, 1, 3)), cx = tonumber(string.sub(e, 4, 5)), cy = tonumber(string.sub(e, 6, 7)),
		outside = string.sub(e, 8, 8) == "1", kanto = string.sub(e, 9, 9) == "1"}
end

--the partner is known and in Coop: the leaders are held back and checked
function MPCoopGateWanted()
	local g = GameID and gAddress[GameID]
	if not g or not MPBadgeFirst[g.sGameVersion] or not MPBattleAddress[GameID] then return false end
	if MPGameMode() ~= "Coop" then return false end
	return MPCoopPartnerOK() ~= nil and MPProgress[MPCoopPartnerOK()] ~= nil
end

--the trainer battle of a trainer was held back: Gym Leaders of a partner that is too far behind do not fight
function MPCoopGate(trainer)
	local gym = MPGymNumber(trainer)
	local id = MPCoopPartnerOK()
	local prog = id and MPProgress[id]
	if gym and prog and prog.badges < gym - 1 then
		console:log("Coop: gym " .. gym .. " is closed, the partner has " .. prog.badges .. " badge(s)")
		MPVsStub(false)
		MPVsCleanup()
		MPVs.coolUntil = TotalFrame + 120
		MPVs.held = nil
		local g = gAddress[GameID]
		MPVsMessageThen(string.format("%s has to beat the\nGym Leader %d first.\\pBeat it together!",
			tostring(FindPlayerByID(id) and FindPlayerByID(id):GetNickname() or "Your partner"), gym - 1), function()
				--bytes: pad, releaseall, end (the script of the leader was stopped by the held back battle)
				local words = {0x6A | (0x6B << 8) | (0x02 << 16)}
				ROMCARD:write32(g.gScriptData, words[1])
				LoadScriptIntoMemory("Data")
		end)
		return
	end
	if MPCoopTrainerShared(trainer) then
		--(a) the partner beat this trainer while we were walking up: no battle, the script of the trainer goes on
		if MPVsTrainerFlagSet(trainer) then
			console:log("Coop: trainer " .. trainer .. " was already beaten by the partner, no battle")
			MPVsStub(false)
			MPVsCleanup()
			MPVs.coolUntil = TotalFrame + 300
			local h = MPVs.held
			MPVs.held = nil
			if h and h.resume then MPVsGotoScript(h.resume) else
				ROMCARD:write32(gAddress[GameID].gScriptData, 0x6A | (0x6B << 8) | (0x02 << 16))
				LoadScriptIntoMemory("Data")
			end
			return
		end
		--(b) the partner is fighting it right now: this player does not fight it, the NPC says so
		local e = MPCoopEngaged[trainer]
		if e and MPCoopPartnerOK() and TotalFrame - e.since < 36000 then
			console:log("Coop: trainer " .. trainer .. " is being fought by the partner, message")
			MPVsStub(false)
			MPVsCleanup()
			MPVs.coolUntil = TotalFrame + 300
			MPVs.held = nil
			MPVsMessageThen(string.format("%s is battling\n%s.", MPSpecPartnerName(), MPSpecTrainerText(trainer)), function()
				MPSpecReleaseScript()
			end)
			return
		end
		--this player fights it: the partner is told
		MPCoopEngageSend("TRST", trainer)
		MPCoopMine = {trainer = trainer, since = TotalFrame}
	end
	MPVsFallback()             --allowed: the battle of the game goes on
end


-- ------------------------------------------------------------------ Versus: the replaced start of the trainer battle

-- ===========================================================================================================================
-- 18. VERSUS
-- ===========================================================================================================================

--the id of the partner when everything for Versus is true: both are in Versus mode and paired with each other
function MPVsPartner()
	if not MPMenuMode() or not EnableScript or not MPAddress[GameID] or not MPBattleAddress[GameID] then return nil end
	if MPGameMode() ~= "Versus" then return nil end
	local id = MPPartnerID()
	if not id or MPFriendMode[id] ~= "V" then return nil end
	if MPFriendPartner[id] ~= MPIni.code then return nil end        --the partner has to have entered our code too
	if not MPSameEngine(id) then return nil end                     --another battle engine: no Versus
	return id
end

--a replacement of an earlier run of the script is still in the ROM: put the original code back
function MPVsCleanup()
	local a = MPBattleAddress[GameID]
	local o = MPBattleOrig[GameID]
	if not a or not o or MPVs.stub then return end
	if ROMCARD:read32(a.start) == MPVsStubCode[1] and ROMCARD:read32(a.start + 4) == MPVsStubCode[2] then
		for i = 0, 6 do ROMCARD:write32(a.start + i * 4, o[i + 1]) end
		console:log("Versus: the start of the trainer battle was still replaced, the original code is back")
	end
end

--puts the replacement of the start of the trainer battle in (on = true) or the original code back
function MPVsStub(on)
	local a = MPBattleAddress[GameID]
	local g = gAddress[GameID]
	if not a or not g then return end
	if not MPVs.stub then MPVsCleanup() end
	if on and not MPVs.stub then
		local orig = {}
		for i = 0, 6 do orig[i] = ROMCARD:read32(a.start + i * 4) end
		if (orig[0] & 0xFF00) ~= 0xB500 then return end             --not the start of a function: not this build
		MPVs.stub = orig
		--ldr r0,[status] ; movs r1,#1 ; strb r1,[r0]  (the script stops) ; ldr r0,[flags] ; ldr r1,[mark] ; str r1,[r0] ; bx lr
		local words = {MPVsStubCode[1], MPVsStubCode[2], MPVsStubCode[3], MPVsStubCode[4], g.gScriptLoad, g.gBattleTypeFlags, MPVsRequestBit}
		for i = 0, 6 do ROMCARD:write32(a.start + i * 4, words[i + 1]) end
	elseif not on and MPVs.stub then
		for i = 0, 6 do ROMCARD:write32(a.start + i * 4, MPVs.stub[i]) end
		MPVs.stub = nil
	end
end

--runs a script of the game at an address (goto address ; end). The mod starts "Data" scripts one byte after their start, so
--there is a dummy byte in front
function MPVsGotoScript(p)
	local g = gAddress[GameID]
	--bytes: dummy, closemessage, goto p, end
	local words = {0x6A | (0x68 << 8) | (0x05 << 16) | ((p & 0xFF) << 24),
		((p >> 8) & 0xFF) | (((p >> 16) & 0xFF) << 8) | (((p >> 24) & 0xFF) << 16) | (0x02 << 24)}
	for i = 1, #words do ROMCARD:write32(g.gScriptData + (i - 1) * 4, words[i]) end
	LoadScriptIntoMemory("Data")
end

--a message box now, then fn when it was closed (the message goes before whatever comes next, it is not queued)
function MPVsMessageThen(text, fn)
	text = string.gsub(text, "\n", "\\n")
	ServerMsgText = text
	LockFromScript = 40
	ServerMsgStart = TotalFrame
	Loadscript(38)
	MPVs.after = {fn = fn, since = TotalFrame}
end

--lets the trainer script of the game go on with the battle of the game (trainer fights as always)
function MPVsFallback()
	local a = MPBattleAddress[GameID]
	local g = gAddress[GameID]
	MPVsStub(false)
	MPVsCleanup()
	MPVs.coolUntil = TotalFrame + 900
	--goto EventScript_DoTrainerBattle ; end. The mod starts a "Data" script one byte after its start (all its scripts begin
	--with a byte that is skipped), so there is a dummy byte in front
	local p = a.dobattle
	--bytes: dummy, closemessage, goto p, end
	local words = {0x6A | (0x68 << 8) | (0x05 << 16) | ((p & 0xFF) << 24),
		((p >> 8) & 0xFF) | (((p >> 16) & 0xFF) << 8) | (((p >> 24) & 0xFF) << 16) | (0x02 << 24)}
	for i = 1, #words do ROMCARD:write32(g.gScriptData + (i - 1) * 4, words[i]) end
	local h = MPVs.held
	if a.approach and h and h.approach then emu:write8(a.approach, h.approach) end
	LoadScriptIntoMemory("Data")
	if h and h.resume then MPVs.watch = {resume = h.resume, trainer = h.trainer, since = TotalFrame, seen = false, idle = 0, primed = false} end
end

--is the trainer flag set?
function MPVsTrainerFlagSet(trainer)
	local base = MPCoopBase()
	local info = MPCoopFlags[gAddress[GameID].sGameVersion]
	if not base or not info or not trainer or trainer < 0 or trainer >= info.count then return false end
	local n = info.first + trainer
	return (emu:read8(base + info.offset + (n >> 3)) & (1 << (n & 7))) ~= 0
end

--sets / clears the trainer flag of a trainer (true = beaten)
function MPVsTrainerFlag(trainer, on)
	local base = MPCoopBase()
	local info = MPCoopFlags[gAddress[GameID].sGameVersion]
	if not base or not info or not trainer or trainer < 0 or trainer >= info.count then return end
	local n = info.first + trainer
	local addr = base + info.offset + (n >> 3)
	local v = emu:read8(addr)
	local bit = 1 << (n & 7)
	if on then v = v | bit else v = v & ~bit end
	emu:write8(addr, v)
end

function MPVsClearReq()
	local r = MPVs.req
	if r and r.savedBattle ~= nil then Battle = r.savedBattle end
	if r and r.flagSet and not r.keepFlag then MPVsTrainerFlag(r.trainer, false) end
	MPVs.req = nil
end

--the battle request to the partner (sent again when the partner was busy)
function MPVsSendRequest()
	local r = MPVs.req
	local g = gAddress[GameID]
	local target = r and FindPlayerByID(r.partner)
	if not r or not target then return false end
	--the partner is asked (Yes: plays the trainer, No: the game plays it). The battle counts: no healing before, the party is
	--not put back afterwards (the exp stays), exp is on
	local flags = r.savedBattle & ~(BATTLE_FLAGS.FORCE_BATTLE | BATTLE_FLAGS.HEAL_PRE_BATTLE | BATTLE_FLAGS.OVERWRITE_POST_BATTLE | BATTLE_FLAGS.HEAL_POST_BATTLE)
	flags = flags | BATTLE_FLAGS.EXP_ALLOWED | MPVersusFlag
	r.double = false
	if r.team.double and r.team.count >= 2 and emu:read8(g.gPartyCount) >= 2 then
		flags = flags | BATTLE_FLAGS.DOUBLE_BATTLE
		r.double = true
	end
	Battle = flags                     --stays until the battle is over: the partner and we have to agree who is host
	BattleMain = flags
	BattleLevelCap = Level_Cap
	BattlePokemonCap = Pokemon_Cap
	if Hosting then
		SendData(target:GetSocket(), "RBAT", target:GetID())
	else
		SendData(SocketMain, "RBAT", target:GetID())
	end
	return true
end

--the trainer battle was started by the script: ask the partner
function MPVsBegin(trainer)
	local g = gAddress[GameID]
	local partner = MPVsPartner()
	local me = FindPlayerByID(PlayerID)
	local keep = partner and (MPFamilyOfPlayer(partner) == gAddress[GameID].sGameVersion)
	local team = partner and MPBuildTeam(trainer, keep)
	if not partner or not team or not me or LockFromScript ~= 0 or emu:read8(g.gPartyCount) < 1 then
		console:log("Versus: not possible now (partner " .. tostring(partner) .. ", team " .. tostring(team ~= nil) .. ", lock " .. tostring(LockFromScript) .. "), the trainer fights as usual")
		MPVsFallback()
		return
	end
	MPVsStub(false)
	MPVs.req = {partner = partner, trainer = trainer, team = team, since = TotalFrame, retryAt = nil, started = false, savedBattle = Battle}
	local resume = emu:read32(g.gScriptLoad + 16)        --the script of the game goes on there after the battle
	if MPInRom(resume) then MPVs.req.resume = resume end
	MPVsTrainerFlag(trainer, true)         --the trainer does not see the player again (the "!") while this goes on
	MPVs.req.flagSet = true
	for pos = 0, 5 do MPSendRaw("VSTM", partner, team.raw[pos], pos) end
	me:SetTalking(partner)
	OtherPlayerHasCancelled = 0
	LockFromScript = 20
	Loadscript(4)                      --"Waiting for other player" (B cancels)
	Keypressholding = 1
	MPVsSendRequest()
end

--looks if the replaced start of the trainer battle was called
function MPVsPoll()
	local a = MPBattleAddress[GameID]
	local g = gAddress[GameID]
	if not a or not g then return end
	if emu:read32(g.gBattleTypeFlags) ~= MPVsRequestBit then return end
	emu:write32(g.gBattleTypeFlags, 0)
	local approach = a.approach and emu:read8(a.approach) or nil
	if a.approach then emu:write8(a.approach, 0) end
	local trainer = emu:read16(a.opp)
	local resume = emu:read32(g.gScriptLoad + 16)         --the script of the game goes on there after the battle
	if not MPInRom(resume) then resume = nil end
	MPVs.held = {resume = resume, trainer = trainer, approach = approach}
	console:log("Versus: the trainer battle (trainer " .. tostring(trainer) .. ") was held back")
	if not MPVsPartner() then
		MPCoopGate(trainer)
		return
	end
	local ok, err = pcall(MPVsBegin, trainer)
	if not ok then
		console:log("Versus error, the battle of the game goes on: " .. tostring(err))
		MPVs.req = nil
		if LockFromScript == 20 then LockFromScript = 0 end
		MPVsFallback()
	end
end

--a TBUS (partner is busy) arrived while we wait: ask again later. true = handled
function MPVsBusy()
	if MPVs.req and LockFromScript == 20 then
		MPVs.req.retryAt = TotalFrame + 240
		return true
	end
	return false
end

--console command: ends the wait for the partner of a Versus battle (the trainer then fights as in the game)
function clear()
	local r = MPVs.req
	if not r then
		console:log("Nothing to clear: no Versus battle is waiting for the partner.")
		return
	end
	local target = FindPlayerByID(r.partner)
	if target then
		SendData(Hosting and target:GetSocket() or SocketMain, "CBAT", target:GetID())
	end
	console:log("Versus: the wait was cleared (as if the partner declined).")
	if not MPVsDeclined() then
		if LockFromScript == 20 then LockFromScript = 0 end
		MPVsClearReq()
		MPVsFallback()
	end
end

--the partner answered No: the game plays the trainer (the battle of the game goes on). true = handled
function MPVsDeclined()
	if not MPVs.req or LockFromScript == 21 then return false end
	LockFromScript = 0
	MPVsClearReq()
	MPVsMessageThen("Your partner let the\ngame play the trainer.", MPVsFallback)
	return true
end

--the money the game gives for the trainer (as the game calculates it), added to the money of the player
function MPVsGiveMoney(team, double)
	local a = MPBattleAddress[GameID]
	local ver = gAddress[GameID].sGameVersion
	local base = MPCoopBase()
	if not a or not a.money or not base or not team or team.lastLevel < 1 then return 0 end
	local i = 0
	while true do
		local c = emu:read8(a.money + i * 4)
		if c == 0xFF or c == team.class or i > 300 then break end
		i = i + 1
	end
	local value = emu:read8(a.money + i * 4 + 1)
	local reward = 4 * team.lastLevel * value * (double and 2 or 1)
	local off = ({FRLG = 0x290, E = 0x490, RS = 0x490})[ver]
	local key = 0
	if ver == "FRLG" or ver == "E" then
		local save2 = emu:read32(gAddress[GameID].gSaveBlock2Ptr)
		if not MPInEwram(save2) then return 0 end
		key = emu:read32(save2 + (ver == "FRLG" and 0xF20 or 0xAC))
	end
	local money = (emu:read32(base + off) ~ key) & 0xFFFFFFFF
	money = math.min(999999, money + reward)
	emu:write32(base + off, (money ~ key) & 0xFFFFFFFF)
	return reward
end

--once per frame
function MPVsTick()
	local a = MPBattleAddress[GameID]
	local g = gAddress[GameID]
	if not a or not g or not MPMenuMode() or not EnableScript then return end
	MPVsCleanup()
	--a message box that was started by us was closed: the next step
	local af = MPVs.after
	if af then
		if LockFromScript == 0 and ServerMsgStart < 0 then
			af.closed = af.closed or TotalFrame
		else
			af.closed = nil
		end
		if (af.closed and TotalFrame - af.closed >= 15) or TotalFrame - af.since > 3600 then
			MPVs.after = nil
			af.fn()
		end
	end
	--the game played the trainer: back on the field after the battle with the script engine still waiting = the script did not go on
	local w = MPVs.watch
	if w then
		if not w.primed and emu:read8(g.gScriptLoad) == 1 then
			w.primed = true
			emu:write8(g.gScriptLoad + 8, 0)            --stack depth
			emu:write8(g.gScriptLoad + 9, 1)            --mode: bytecode
			emu:write32(g.gScriptLoad + 12, 0)          --no native function
			emu:write32(g.gScriptLoad + 16, w.resume)   --the script goes on here after the battle
			console:log("Versus: the trainer battle of the game started, the script is set to go on at " .. string.format("%X", w.resume))
		end
		if IsInMenu() ~= 0 then
			w.seen = true
			w.idle = 0
		elseif w.seen then
			w.idle = w.idle + 1
			if w.idle >= 90 then
				MPVs.watch = nil
				local ptr = emu:read32(g.gScriptLoad + 16)
				local status = emu:read8(g.gScriptLoad)
				local outcome = emu:read8(a.outcome)
				console:log(string.format("Versus: after the battle: script status %d, script pointer %X, outcome %d", status, ptr, outcome))
				--the pointer did not move: the script of the game never went on
				if ptr == w.resume and LockFromScript == 0 and ServerMsgStart < 0 and outcome == 1 then
					console:log("Versus: the script of the trainer did not go on, it is continued")
					MPVsTrainerFlag(w.trainer, true)
					MPVsGotoScript(w.resume)
				end
			end
		end
		if TotalFrame - w.since > 36000 or (not w.seen and TotalFrame - w.since > 1800) then MPVs.watch = nil end
	end
	--after the Versus battle: when the game is back on the field the result message, then the trainer script goes on
	local post = MPVs.post
	if post and not MPVs.after then
		local ready = LockFromScript == 0 and ServerMsgStart < 0 and IsInMenu() == 0 and emu:read8(g.gLockControls) == 0
		if ready or TotalFrame - post.since > 900 then
			MPVs.post = nil
			local resume = post.resume
			MPVsMessageThen(post.text, function()
				if resume then MPVsGotoScript(resume) end
			end)
		end
	end
	--tell the others when the game mode changed
	local mc = MPModeChar()
	if MPVs.modeChar ~= mc then
		MPVs.modeChar = mc
		MPSentCode = {}
		if Connected or Hosting then MPAnnounceCode() end
	end
	--defender: the question was answered with No (the state of the question ends without a battle): no more questions for a while
	if LockFromScript == 22 and MPVs.def then
		MPVs.was22 = true
	elseif MPVs.was22 then
		MPVs.was22 = false
		if LockFromScript == 0 and MPVs.def and not MPVs.swapped then
			MPVs.refuse[MPVs.def.opponent] = TotalFrame + 1800
			MPVs.def = nil
		end
	end
	--defender: the real party has to come back
	if MPVs.swapped and LockFromScript ~= 21 then
		MPVs.idle = MPVs.idle + 1
		if MPVs.idle > 180 then MPVsRestore() end
	else
		MPVs.idle = 0
	end
	if MPVs.def and not MPVs.swapped and LockFromScript ~= 21 and LockFromScript ~= 22 then
		MPVs.defIdle = (MPVs.defIdle or 0) + 1
		if MPVs.defIdle > 1200 then MPVs.def = nil end
	else
		MPVs.defIdle = 0
	end
	--challenger
	local r = MPVs.req
	if r then
		if not FindPlayerByID(r.partner) or (MPVsPartner() ~= r.partner and LockFromScript == 20) then
			if LockFromScript == 20 then LockFromScript = 0 end
			local target = FindPlayerByID(r.partner)
			if target then
				SendData(Hosting and target:GetSocket() or SocketMain, "CBAT", target:GetID())
			end
			MPVsClearReq()
			MPVsFallback()
		elseif LockFromScript == 20 then
			if r.retryAt and TotalFrame >= r.retryAt then
				r.retryAt = nil
				MPVsSendRequest()
			end
			--no time out: the partner is asked again and again until the partner answers. Only clear() ends the wait
		elseif LockFromScript == 21 then
			r.started = true
		elseif LockFromScript == 0 and not r.started then   --cancelled or declined
			MPVsClearReq()
			MPVs.coolUntil = TotalFrame + 1800
		end
	end
	MPVsPoll()
	MPCoopInactiveTick()
	--not while the game plays the battle it was just allowed to play (MPVs.watch): the script reaches the start of the battle
	--later than the cool down and would be held back again and again
	local want = (MPVsPartner() ~= nil or MPCoopGateWanted()) and not MPVs.req and not MPVs.def and not MPVs.watch and TotalFrame >= MPVs.coolUntil and LockFromScript == 0
	MPVsStub(want)
end

function MPVsTickSafe()
	local ok, err = pcall(MPVsTick)
	if not ok and not MPVs.errorLogged then
		MPVs.errorLogged = true
		console:log("Versus error: " .. tostring(err))
	end
end

-- ------------------------------------------------------------------ Versus: the partner (defender)
--a part of the team of the trainer arrived (VSTM)
function MPVsTeamReceive(id, data)
	local slot = tonumber(string.sub(data, 62, 62))
	local part = tonumber(string.sub(data, 63, 63))
	if not slot or not part or slot > 5 then return end
	local t = MPVs.teams[id]
	if not t or (slot == 0 and part == 0) then
		t = {raw = {}, complete = false}
		MPVs.teams[id] = t
	end
	if part == 0 then t.raw[slot] = "" end
	t.raw[slot] = (t.raw[slot] or "") .. string.sub(data, 21, 45)
	if slot == 5 and part == 9 then
		t.complete = true
		for i = 0, 5 do
			if #(t.raw[i] or "") ~= MPMon.Chars then t.complete = false end
		end
	end
end

--the battle request came with the Versus mark: true when we play along
function MPVsDefend(id)
	if not MPMenuMode() or MPGameMode() ~= "Versus" or MPPartnerID() ~= id or not MPSameEngine(id) then return false end
	if (MPVs.refuse[id] or 0) > TotalFrame then return false end
	local t = MPVs.teams[id]
	if not t or not t.complete then return false end
	if MPVs.swapped then return false end
	MPVs.def = {opponent = id, team = t}
	--the party of this player is the team of the trainer and is put back by us: the mod has to restore it after the battle
	--(otherwise a lost trainer team would send this player to the Pokemon Center)
	BattleMain = (BattleMain | BATTLE_FLAGS.OVERWRITE_POST_BATTLE) & ~BATTLE_FLAGS.HEAL_POST_BATTLE
	return true
end

--before the party is read for the battle: the team of the trainer in, the real party saved
function MPVsSwapIn()
	local d = MPVs.def
	local g = gAddress[GameID]
	if not d or MPVs.swapped then return end
	local words = {}
	for i = 0, MPMon.Words * 6 - 1 do words[i] = emu:read32(g.gParty + i * 4) end
	MPVs.swapped = {words = words, count = emu:read8(g.gPartyCount)}
	local n = 0
	for pos = 1, 6 do
		local raw = d.team.raw[pos - 1] or MPEmptyRaw()
		SetPokemonTeam(raw, pos, 0)
		if CheckPokemonValid(raw) then n = n + 1 end
	end
	emu:write8(g.gPartyCount, n > 0 and n or 1)
end

function MPVsRestore()
	local s = MPVs.swapped
	local g = gAddress[GameID]
	if s then
		for i = 0, MPMon.Words * 6 - 1 do emu:write32(g.gParty + i * 4, s.words[i]) end
		emu:write8(g.gPartyCount, s.count)
	end
	MPVs.swapped = nil
	MPVs.def = nil
	MPVs.idle = 0
end

--after the names of the link players were written: the opponent has the name of the trainer
function MPVsAfterInitiate()
	local r = MPVs.req
	if not r or not r.team or not r.team.name then return end
	local g = gAddress[GameID]
	local player = FindPlayerByID(PlayerID)
	local opponent = player and FindPlayerByID(player:GetTalking())
	if not opponent then return end
	local name = {}
	for i = 1, 7 do name[i] = r.team.name[i] or 0xFF end
	name[8] = 0xFF
	for i = #r.team.name + 1, 7 do name[i] = 0xFF end
	local addrs = {g.gLinkPlayers + opponent:GetBattleID() * 0x1C + 0x8, g.gLinkPlayers + 4 * 0x1C + 0x8}
	for _, addr in ipairs(addrs) do
		for i = 1, 8 do emu:write8(addr + i - 1, name[i]) end
	end
end

--the end of a battle of the mod (both players): the trainer is beaten, the real party comes back
function MPVsEnd()
	local r = MPVs.req
	if r and r.started then
		local a = MPBattleAddress[GameID]
		local won = a and emu:read8(a.outcome) == 1
		if won then
			MPVsTrainerFlag(r.trainer, true)
			r.keepFlag = true
			local reward = MPVsGiveMoney(r.team, r.double)
			MPVs.post = {text = "You won the Versus battle!\nYou got $" .. tostring(reward) .. "\nfor winning.", resume = r.resume, since = TotalFrame}
		else
			MPVs.post = {text = "You lost the Versus battle.", since = TotalFrame}
		end
		MPVs.coolUntil = TotalFrame + 300
	end
	if r then MPVsClearReq() end
	if MPVs.swapped or MPVs.def then MPVsRestore() end
end

--a player left (RemovePlayer)
function MPVsPlayerRemoved(id)
	if MPCoopPartner == id then
		MPCoopEngaged = {}               --(the NPCs come back, MPCoopInactiveTick)
		MPCoopMine = nil
	end
	MPFriendMode[id] = nil
	MPVs.teams[id] = nil
	MPCD.lead[id] = nil
	if MPVs.def and MPVs.def.opponent == id then MPVsRestore() end
end

--the script is stopped
function MPVsShutdown()
	pcall(function()
		MPVsStub(false)
		if MPVs.swapped then MPVsRestore() end
		if MPCD.backup then MPCDRestore() end
	end)
end

-- ------------------------------------------------------------------ game mode sync, shared rewards of Coop

-- ===========================================================================================================================
-- 19. SHARED REWARDS, XP, COOP DOUBLES, SOUL LINK
-- ===========================================================================================================================

--   MODE  the game mode a player chose (V Versus, C Coop, - Free Roam): the paired player gets the same mode
--   TRWN  a trainer was beaten in Coop: trainer (4), money gained (7), address of the script of the trainer after the battle (8,
--         hex, 0 = none), map (5). The partner gets the same money and runs the same script (when on the same map)
MPCS = {
	cur = nil,            --the trainer battle that is running: {trainer, money, script, since, seen, idle}
	pending = nil,        --a result of the partner to apply: {trainer, money, script, map, sameBuild, name, since, paid}
	lastCb = 0,
}

--the players that are paired with this player (either way) and on the server
function MPPairedIDs()
	local ids, seen = {}, {}
	local id = MPPartnerID()
	if id then ids[#ids + 1] = id seen[id] = true end
	for pid, code in pairs(MPFriendPartner) do
		if code == MPIni.code and not seen[pid] and FindPlayerByID(pid) then ids[#ids + 1] = pid seen[pid] = true end
	end
	return ids
end

--the game mode was changed in the settings: the paired player gets the same one
function MPModeSync()
	for _, id in ipairs(MPPairedIDs()) do MPSendPacket("MODE", id, MPModeChar()) end
end

function MPModeReceive(id, data)
	local ch = string.sub(data, 21, 21)
	local name = ({V = "Versus", C = "Coop"})[ch] or "Free Roam"
	local paired = (MPIni.partner and MPFriendCodes[id] == MPIni.partner) or MPFriendPartner[id] == MPIni.code
	if not paired or MPIni.mode == name then return end
	MPIni.mode = name
	MPIniWrite()
	local p = FindPlayerByID(id)
	MPSay(MPModeText(name))
end

-- ------------------------------------------------------------------ money of the save
--address of the money and its key (RS: none), or nil
function MPMoneyLoc()
	local g = gAddress[GameID]
	local ver = g.sGameVersion
	local base = MPCoopBase()
	if not base then return nil end
	local off = ({FRLG = 0x290, E = 0x490, RS = 0x490})[ver]
	local key = 0
	if ver ~= "RS" then
		local save2 = emu:read32(g.gSaveBlock2Ptr)
		if not MPInEwram(save2) then return nil end
		key = emu:read32(save2 + (ver == "FRLG" and 0xF20 or 0xAC))
	end
	return base + off, key
end

function MPGetMoney()
	local a, k = MPMoneyLoc()
	if not a then return nil end
	return (emu:read32(a) ~ k) & 0xFFFFFFFF
end

function MPAddMoney(n)
	local a, k = MPMoneyLoc()
	if not a or n <= 0 then return 0 end
	local m = math.min(999999, ((emu:read32(a) ~ k) & 0xFFFFFFFF) + n)
	emu:write32(a, (m ~ k) & 0xFFFFFFFF)
	return n
end

--map id (bank, number) of this player
function MPMyMap()
	local me = FindPlayerByID(PlayerID)
	if not me then return nil end
	local _, _, _, mapid = me:GetCoords()
	return mapid
end

--evolution as the Rare Candy does it: a small routine (Thumb, in free ROM) that asks the game for the species the Pokemon
-- evolves to (GetEvolutionTargetSpecies, level-up evolutions) and starts the evolution scene (BeginEvolutionScene) with
-- gCB2_AfterEvolution = CB2_ReturnToField. It runs once as the main callback when the player is free in the overworld.
MPEvoStubCode = {0xB5F0, 0x4D0A, 0x1C28, 0x2100, 0x2200, 0x4C09, 0xF000, 0xF80D, 0x2800, 0xD009, 0x1C01, 0x1C28, 0x2201, 0x4B06,
	0x4E06, 0x4F07, 0x6037, 0x4C07, 0xF000, 0xF801, 0xBDF0, 0x4720}
MPEvoPool = 44            --offset of the literal pool: mon, GetEvolutionTargetSpecies, party slot, &gCB2_AfterEvolution, CB2_ReturnToField, BeginEvolutionScene
MPXpEvo = {slot = nil, running = false}
function MPXpEvoTick()
	if not MPMon.Standard then return end
	local g, ad = gAddress[GameID], MPEvoAddr[GameID]
	if not g or not ad then return end
	local cb2 = emu:read32(g.gMainCallback)
	if MPXpEvo.running then                        --the routine ran for one frame: the game goes on with its own callback
		MPXpEvo.running = false
		if cb2 == MPEvoStubAt + 1 then emu:write32(g.gMainCallback, ad.over + 1) end
		return
	end
	local slot = MPXpEvo.slot
	if slot == nil then return end
	local ready = LockFromScript == 0 and ServerMsgStart < 0 and not MPVs.after and not MPVs.post and not MPCS.pending
	and IsInMenu() == 0 and cb2 == ad.over + 1 and emu:read8(g.gLockControls) == 0 and emu:read8(g.gScriptLoad) == 2
	if not ready then return end
	MPXpEvo.slot = nil
	for i = 0, MPEvoPool - 1, 2 do                  --the place has to be free ROM (0xFF) or hold this routine already
		local old = ROMCARD:read16(MPEvoStubAt + i)
		local mine = MPEvoStubCode[i // 2 + 1]
		if old ~= 0xFFFF and old ~= (mine or 0x46C0) then return end
	end
	local pool = {g.gParty + slot * 100, ad.getevo | 1, slot, ad.after, ad.ret | 1, ad.begin | 1}
	for i, h in ipairs(MPEvoStubCode) do ROMCARD:write16(MPEvoStubAt + (i - 1) * 2, h) end
	for i = #MPEvoStubCode, MPEvoPool // 2 - 1 do ROMCARD:write16(MPEvoStubAt + i * 2, 0x46C0) end
	for i, v in ipairs(pool) do ROMCARD:write32(MPEvoStubAt + MPEvoPool + (i - 1) * 4, v) end
	emu:write32(g.gMainCallback, MPEvoStubAt + 1)
	MPXpEvo.running = true
end

-- ------------------------------------------------------------------ Coop: shared experience
-- When the partner wins a trainer battle the first healthy Pokemon of the party gets MPXpShare of the experience the trainer
-- would give one participant (yield * level * 1.5 / 7 for each Pokemon of the trainer). A partner who is behind (the level of the
-- highest Pokemon of the winner minus our lead) gets more: +MPXpCatch per level of difference above MPXpGap, up to +MPXpCatchMax.
MPXpShare = 0.5
MPXpGap = 2
MPXpCatch = 0.15
MPXpCatchMax = 1.5

--the level of the strongest Pokemon of the party (sent with the result of a battle)
function MPCoopTopLevel()
	local g = gAddress[GameID]
	local top = 0
	for i = 0, 5 do
		local base = g.gParty + i * 100
		if (emu:read8(base + 0x13) & 2) ~= 0 then top = math.max(top, emu:read8(base + 0x54)) end
	end
	return math.min(top, 100)
end

--experience a trainer gives one participant, from the data of the ROM
function MPXpOfTrainer(trainer)
	local a, g = MPBattleAddress[GameID], gAddress[GameID]
	local t = MPTrainerInfo(trainer)
	if not a or not t then return 0 end
	local size = ({[0] = 8, [1] = 16, [2] = 8, [3] = 16})[t.flags]
	local total = 0
	for i = 0, t.size - 1 do
		local p = t.party + i * size
		local level, species = emu:read8(p + 2), emu:read16(p + 4)
		if species >= 1 and species <= 411 then
			total = total + (emu:read8(g.gSpeciesInfo + 0x1C * species + 9) * level * 3) // 14
		end
	end
	return total
end

--experience needed for a level (growth rate of the species)
function MPXpForLevel(growth, level)
	return emu:read32(MPBattleAddress[GameID].exp + (growth * 101 + level) * 4)
end

--gives experience to the Pokemon at RAM address base: level, stats, new moves (empty slots only). Returns a table or nil.
function MPCoopGiveExp(base, amount, noMoves)
	local a, g = MPBattleAddress[GameID], gAddress[GameID]
	local b = {}
	for i = 0, 99 do b[i] = emu:read8(base + i) end
	local pers, otid = MPGet32(b, 0), MPGet32(b, 4)
	local key = pers ~ otid
	local order = MPSubOrder[pers % 24]
	local d = {}
	for i = 0, 11 do MPPut32(d, i * 4, MPGet32(b, 0x20 + i * 4) ~ key) end
	local off = {}
	for j = 1, 4 do off[order[j]] = (j - 1) * 12 end      --offset of substructure 1 growth, 2 attacks, 3 EVs, 4 misc
	local species = MPGet16(d, off[1])
	if species < 1 or species > 411 then return nil end
	local exp = MPGet32(d, off[1] + 4)
	local growth = emu:read8(g.gSpeciesInfo + 0x1C * species + 0x13)
	local oldLevel = b[0x54]
	if oldLevel >= 100 or oldLevel < 1 then return nil end
	local newExp = math.min(exp + amount, MPXpForLevel(growth, 100))
	local newLevel = oldLevel
	while newLevel < 100 and MPXpForLevel(growth, newLevel + 1) <= newExp do newLevel = newLevel + 1 end
	MPPut32(d, off[1] + 4, newExp)
	local moves = 0
	if newLevel > oldLevel and not noMoves then
		local known, free = {}, {}
		for i = 0, 3 do
			local mv = MPGet16(d, off[2] + i * 2)
			if mv == 0 then free[#free + 1] = i else known[mv] = true end
		end
		local ptr = emu:read32(a.learn + species * 4)
		if MPInRom(ptr) then
			for i = 0, 63 do
				local v = emu:read16(ptr + i * 2)
				if v == 0xFFFF then break end
				local lvl, mv = v >> 9, v & 0x1FF
				if lvl > oldLevel and lvl <= newLevel and not known[mv] and #free > 0 then
					local slot = table.remove(free, 1)
					MPPut16(d, off[2] + slot * 2, mv)
					d[off[2] + 8 + slot] = emu:read8(a.moves + mv * 12 + 4)      --PP
					known[mv] = true
					moves = moves + 1
				end
			end
		end
	end
	--stats: IVs of the misc substructure (5 bits each), EVs of substructure 3, nature = personality % 25
	local ivs = MPGet32(d, off[4] + 4)
	local nature = pers % 25
	local function stat(id)
		return SetPokemonStat(species, newLevel, id, (ivs >> (5 * id)) & 31, d[off[3] + id] or 0, nature)
	end
	local oldMax = MPGet16(b, 0x58)
	local newMax = stat(0)
	local cur = MPGet16(b, 0x56)
	if cur > 0 then cur = math.min(newMax, cur + math.max(0, newMax - oldMax)) end
	b[0x54] = newLevel
	MPPut16(b, 0x56, cur)
	MPPut16(b, 0x58, newMax)
	MPPut16(b, 0x5A, stat(1))
	MPPut16(b, 0x5C, stat(2))
	MPPut16(b, 0x5E, stat(3))
	MPPut16(b, 0x60, stat(4))
	MPPut16(b, 0x62, stat(5))
	--encrypt, checksum
	local sum = 0
	for i = 0, 23 do sum = (sum + MPGet16(d, i * 2)) & 0xFFFF end
	for i = 0, 11 do MPPut32(b, 0x20 + i * 4, MPGet32(d, i * 4) ~ key) end
	MPPut16(b, 0x1C, sum)
	for i = 0x1C, 0x1D do emu:write8(base + i, b[i]) end
	for i = 0x20, 0x4F do emu:write8(base + i, b[i]) end
	for i = 0x54, 0x63 do emu:write8(base + i, b[i]) end
	return {oldLevel = oldLevel, newLevel = newLevel, gain = newExp - exp, moves = moves, species = species}
end

--the partner won a trainer battle: our first healthy Pokemon gets experience. Returns {name, gain, oldLevel, newLevel, moves} or nil
function MPCoopShareExp(trainer, theirLevel)
	if not MPBattleAddress[GameID] or MPXpShare <= 0 or not MPMon.Standard then return nil end
	local lead = MPCDOwnLead()
	if not lead then return nil end
	local mult = 1
	local gap = (theirLevel or 0) - emu:read8(lead + 0x54) - MPXpGap
	if gap > 0 then mult = 1 + math.min(MPXpCatchMax, gap * MPXpCatch) end
	local amount = math.floor(MPXpOfTrainer(trainer) * MPXpShare * mult)
	if amount < 1 then return nil end
	local gain = MPLvlStart((lead - gAddress[GameID].gParty) // 100, amount)      --the levels follow one at a time (MPLvlTick)
	if not gain then return nil end
	local lvl = emu:read8(lead + 0x54)
	return {name = "Your lead", gain = gain, oldLevel = lvl, newLevel = lvl, moves = 0}
end

--the partner set the flag of a trainer: in the burst after the connection it is a trainer that was beaten while we were away
function MPCoopCatchNote(tr)
	local c = MPCoopCatch
	if TotalFrame >= c.untilFrame or c.known[tr] or MPCoopWon[tr] then return end
	if not MPCoopTrainerShared(tr) then return end
	if #c.list >= MPCoopCatchCap then c.skipped = c.skipped + 1 return end
	c.known[tr] = true
	c.list[#c.list + 1] = tr
end

--money and experience for the trainers of the list (the same amounts as if the partner had beaten them while we were there, with
--the level gap bonus left out), one message box
function MPCoopCatchPay()
	local c = MPCoopCatch
	local list, skipped = c.list, c.skipped
	c.list, c.skipped = {}, 0
	local a, g = MPBattleAddress[GameID], gAddress[GameID]
	if not a or not a.money or not g then return end
	local money, exp, n = 0, 0, 0
	for _, tr in ipairs(list) do
		local t = MPTrainerInfo(tr)
		if t and t.size >= 1 then
			local rec = ({[0] = 8, [1] = 16, [2] = 8, [3] = 16})[t.flags]
			local last = emu:read8(t.party + (t.size - 1) * rec + 2)
			local i = 0
			while true do
				local cl = emu:read8(a.money + i * 4)
				if cl == 0xFF or cl == t.class or i > 300 then break end
				i = i + 1
			end
			money = money + 4 * last * emu:read8(a.money + i * 4 + 1) * (t.double == 1 and 2 or 1)
			exp = exp + MPXpOfTrainer(tr)
			n = n + 1
		end
	end
	if n == 0 then return end
	local p = FindPlayerByID(MPCoopPartner or 0)
	local who = tostring(p and p:GetNickname() or "Your partner")
	local text = who .. " beat " .. tostring(n + skipped) .. (n + skipped == 1 and " trainer" or " trainers") .. "\nwhile you were away!"
	local got = MPAddMoney(money)
	if got > 0 then text = text .. "\\pYou got $" .. tostring(got) .. " too." end
	local share = math.floor(exp * MPXpShare)
	local lead = MPMon.Standard and MPCDOwnLead() or nil
	if lead and share >= 1 then
		local gained = MPLvlStart((lead - g.gParty) // 100, share)         --the levels follow one at a time (MPLvlTick)
		if gained then text = text .. "\\pYour lead got " .. tostring(gained) .. " Exp. Points!" end
	end
	if skipped > 0 then text = text .. "\\p(" .. tostring(skipped) .. " more were left out.)" end
	console:log("Coop: catch-up for " .. tostring(n) .. " trainers: $" .. tostring(got) .. ", " .. tostring(share) .. " exp")
	MPVsMessageThen(text, function() end)
end


-- ------------------------------------------------------------------ shared experience: one level at a time
-- A share of experience does not jump to the last level. The lead is raised one level after the other: at every level the moves of
-- that level are learned (a Pokemon that has four moves asks which one to forget, a menu with the move names), then the game's own
-- check for an evolution runs (BeginEvolutionScene as the Rare Candy does it), then the next level follows. An evolved form goes on
-- with the moves of its own learnset. The exp that does not reach the next level is added at the end.
MPMoveNameAt = {          --gMoveNames per game (13 bytes per move, game text)
	AXP1 = 0x81F82B0,
	AXP2 = 0x81F82C8,
	AXPD = 0x8205230,
	AXPF = 0x82006B8,
	AXPI = 0x81F9F4C,
	AXPS = 0x81FCFD0,
	AXV1 = 0x81F8320,
	AXV2 = 0x81F8338,
	AXVD = 0x820529C,
	AXVF = 0x8200728,
	AXVI = 0x81F9FBC,
	AXVS = 0x81FD040,
	BPED = 0x832E0EC,
	BPEE = 0x831977C,
	BPEF = 0x83212AC,
	BPEI = 0x8319140,
	BPES = 0x831F9E0,
	BPG1 = 0x8247070,
	BPG2 = 0x82470E0,
	BPGD = 0x8246F40,
	BPGF = 0x824147C,
	BPGI = 0x8240114,
	BPGS = 0x82427DC,
	BPR1 = 0x8247094,
	BPR2 = 0x8247104,
	BPRD = 0x8246F64,
	BPRF = 0x82414A0,
	BPRI = 0x8240138,
	BPRS = 0x8242800,
}
MPLvl = nil               --{pers, otid, target = exp to reach, phase, moves, text, ask, gain, since}

--text of the game (nickname, move name) as letters
function MPLvlText(addr, len)
	local tbl = LanguageTable and LanguageTable[LanguageTableType]
	local t = {}
	for i = 0, len - 1 do
		local c = emu:read8(addr + i)
		if c == 0xFF then break end
		local ch = tbl and findKeyByValue(tbl, c)
		if type(ch) ~= "string" or #ch ~= 1 then ch = "?" end
		t[#t + 1] = ch
	end
	return table.concat(t)
end

function MPMoveName(move)
	local at = MPMoveNameAt[GameID]
	if not at or move < 1 or move > 354 then return "MOVE " .. tostring(move) end
	return MPLvlText(at + move * 13, 12)
end

--the Pokemon with this identity in the party: RAM address, slot (or nil)
function MPLvlFind(pers, otid)
	local g = gAddress[GameID]
	for i = 0, 5 do
		local base = g.gParty + i * 100
		if emu:read32(base) == pers and emu:read32(base + 4) == otid and (emu:read8(base + 0x13) & 2) ~= 0 then return base, i end
	end
	return nil
end

--the Pokemon at base with its substructures decrypted: {b = 100 bytes, d = 48 bytes, off[1..4], key, species, exp, level}
function MPLvlOpen(base)
	local b = {}
	for i = 0, 99 do b[i] = emu:read8(base + i) end
	local pers, otid = MPGet32(b, 0), MPGet32(b, 4)
	local key = pers ~ otid
	local order = MPSubOrder[pers % 24]
	local d = {}
	for i = 0, 11 do MPPut32(d, i * 4, MPGet32(b, 0x20 + i * 4) ~ key) end
	local off = {}
	for j = 1, 4 do off[order[j]] = (j - 1) * 12 end
	return {b = b, d = d, off = off, key = key, species = MPGet16(d, off[1]), exp = MPGet32(d, off[1] + 4), level = b[0x54]}
end

--a move into one of the four slots (PP from the move data)
function MPLvlSetMove(base, slot, move)
	local a = MPBattleAddress[GameID]
	local m = MPLvlOpen(base)
	MPPut16(m.d, m.off[2] + slot * 2, move)
	m.d[m.off[2] + 8 + slot] = emu:read8(a.moves + move * 12 + 4)
	local sum = 0
	for i = 0, 23 do sum = (sum + MPGet16(m.d, i * 2)) & 0xFFFF end
	for i = 0, 11 do MPPut32(m.b, 0x20 + i * 4, MPGet32(m.d, i * 4) ~ m.key) end
	MPPut16(m.b, 0x1C, sum)
	for i = 0x1C, 0x1D do emu:write8(base + i, m.b[i]) end
	for i = 0x20, 0x4F do emu:write8(base + i, m.b[i]) end
end

--the moves the learnset of the species has at exactly this level
function MPLvlMovesAt(species, level)
	local out = {}
	local a = MPBattleAddress[GameID]
	if not a or species < 1 or species > 411 then return out end
	local ptr = emu:read32(a.learn + species * 4)
	if not MPInRom(ptr) then return out end
	for i = 0, 63 do
		local v = emu:read16(ptr + i * 2)
		if v == 0xFFFF then break end
		if (v >> 9) == level then out[#out + 1] = v & 0x1FF end
	end
	return out
end

--a share of experience for the Pokemon in this party slot: returns what it gets, or nil. The part that does not reach the next
--level is written at once, the levels follow one at a time (MPLvlTick)
function MPLvlStart(slot, amount)
	if not MPMon.Standard or not amount or amount < 1 then return nil end
	local a, g = MPBattleAddress[GameID], gAddress[GameID]
	if not a or not g then return nil end
	local base = g.gParty + slot * 100
	local m = MPLvlOpen(base)
	if m.species < 1 or m.species > 411 or m.level < 1 or m.level >= 100 then return nil end
	local pers, otid = MPGet32(m.b, 0), MPGet32(m.b, 4)
	local growth = emu:read8(g.gSpeciesInfo + 0x1C * m.species + 0x13)
	local cap = MPXpForLevel(growth, 100)
	local gain = math.min(amount, cap - m.exp)
	if gain < 1 then return nil end
	if MPLvl then
		if MPLvl.pers ~= pers or MPLvl.otid ~= otid then return nil end
		MPLvl.target = math.min(cap, MPLvl.target + gain)         --more arrives while the levels are going on
		MPLvl.gain = MPLvl.gain + gain
		return gain
	end
	MPLvl = {pers = pers, otid = otid, target = m.exp + gain, phase = "next", moves = {}, text = {}, gain = gain, since = TotalFrame}
	local room = MPXpForLevel(growth, m.level + 1) - 1 - m.exp
	if room > 0 then MPCoopGiveExp(base, math.min(gain, room), true) end
	return gain
end

--nothing else is going on: no script, no box, no menu, no evolution, the field is there
function MPLvlReady()
	local g = gAddress[GameID]
	local ad = MPEvoAddr[GameID]
	local cb2 = emu:read32(g.gMainCallback)
	return LockFromScript == 0 and ServerMsgStart < 0 and not MPVs.after and not MPVs.post and not MPCS.pending and MPState == 0
		and MPRequest == nil and IsInMenu() == 0 and emu:read8(g.gLockControls) == 0 and emu:read8(g.gScriptLoad) == 2
		and not MPXpEvo.running and MPXpEvo.slot == nil and (not ad or cb2 == ad.over + 1)
end

--the menu: which move is forgotten for the new one
function MPLvlAsk(base, move)
	local m = MPLvlOpen(base)
	local opts = {}
	for i = 0, 3 do opts[#opts + 1] = MPMoveName(MPGet16(m.d, m.off[2] + i * 2)) end
	opts[#opts + 1] = MPT("Don't learn")
	MPAsk("learn", MPLvl.ask.name .. " wants to learn\n" .. MPMoveName(move) .. ". Forget which?", opts)
end

--the answer of the menu (1-4 the move to forget, 5 or B: do not learn)
function MPLvlChoice(choice)
	local s = MPLvl
	if not s or not s.ask then return end
	local base = MPLvlFind(s.pers, s.otid)
	local ask = s.ask
	s.ask = nil
	s.phase = "moves"
	if not base then return end
	local newName = MPMoveName(ask.move)
	if choice >= 1 and choice <= 4 then
		local m = MPLvlOpen(base)
		local old = MPGet16(m.d, m.off[2] + (choice - 1) * 2)
		MPLvlSetMove(base, choice - 1, ask.move)
		s.text[#s.text + 1] = ask.name .. " forgot\n" .. MPMoveName(old) .. "!"
		s.text[#s.text + 1] = "...and learned\n" .. newName .. "!"
	else
		s.text[#s.text + 1] = ask.name .. " did not learn\n" .. newName .. "."
	end
end

--once per frame
function MPLvlTick()
	local s = MPLvl
	if not s then return end
	if TotalFrame - s.since > 108000 then MPLvl = nil return end           --half an hour: give up
	if not MPLvlReady() then return end
	local g = gAddress[GameID]
	local base, slot = MPLvlFind(s.pers, s.otid)
	if not base then MPLvl = nil return end
	local ad = MPEvoAddr[GameID]

	if s.phase == "next" then
		local m = MPLvlOpen(base)
		local growth = emu:read8(g.gSpeciesInfo + 0x1C * m.species + 0x13)
		if m.level < 100 and MPXpForLevel(growth, m.level + 1) <= s.target then
			local at = MPXpForLevel(growth, m.level + 1)
			if not MPCoopGiveExp(base, at - m.exp, true) then MPLvl = nil return end       --exactly the next level
			local upper = (m.level + 2 <= 100) and (MPXpForLevel(growth, m.level + 2) - 1) or s.target
			local room = math.min(s.target, upper) - at                                     --the rest that does not reach the one after
			if room > 0 then MPCoopGiveExp(base, room, true) end
			s.level = m.level + 1
			s.moves = MPLvlMovesAt(m.species, s.level)
			s.text[#s.text + 1] = MPLvlText(base + 8, 10) .. " grew to\nLv. " .. tostring(s.level) .. "!"
			s.phase = "moves"
		else
			local left = s.target - m.exp
			if left > 0 then MPCoopGiveExp(base, left, true) end
			MPLvl = nil
		end
	elseif s.phase == "moves" then
		local mv = s.moves[1]
		if mv == nil then
			if #s.text > 0 then
				local t = table.concat(s.text, "\\p")
				s.text = {}
				MPVsMessageThen(t, function() end)
			end
			s.phase = "evo"
			return
		end
		local m = MPLvlOpen(base)
		local known, free = false, nil
		for i = 0, 3 do
			local x = MPGet16(m.d, m.off[2] + i * 2)
			if x == mv then known = true end
			if x == 0 and not free then free = i end
		end
		if known then
			table.remove(s.moves, 1)
		elseif free then
			table.remove(s.moves, 1)
			MPLvlSetMove(base, free, mv)
			s.text[#s.text + 1] = MPLvlText(base + 8, 10) .. " learned\n" .. MPMoveName(mv) .. "!"
		else
			table.remove(s.moves, 1)
			s.ask = {move = mv, name = MPLvlText(base + 8, 10)}
			s.askAt = TotalFrame
			s.phase = "asking"
			MPLvlAsk(base, mv)
		end
	elseif s.phase == "asking" then
		if TotalFrame - (s.askAt or 0) > 90 and s.ask then     --the menu went away without an answer: ask again
			s.askAt = TotalFrame
			MPLvlAsk(base, s.ask.move)
		end
	elseif s.phase == "evo" then
		if not ad then s.phase = "next" return end
		s.species0 = MPLvlOpen(base).species
		MPXpEvo.slot = slot
		s.evoAt = TotalFrame
		s.phase = "evo_wait"
	elseif s.phase == "evo_wait" then
		if TotalFrame - s.evoAt < 20 then return end            --MPXpEvoTick starts the routine when the player is free
		local m = MPLvlOpen(base)
		if m.species ~= s.species0 then
			s.moves = MPLvlMovesAt(m.species, m.level)           --the evolved form: the moves of this level that it has not got yet
			s.phase = "moves"
		else
			s.phase = "next"
		end
	end
end

-- ------------------------------------------------------------------ Coop: the partner gets the result of a battle
function MPCoopShareSend(c)
	local id = MPCoopPartnerOK()
	if not id then return end
	local now = MPGetMoney()
	local delta = (now and c.money) and math.max(0, now - c.money) or 0
	local script = 0
	local payload = string.format("%04d%07d%08X%05d%03d", c.trainer % 10000, math.min(delta, 9999999), script, (MPMyMap() or 0) % 100000, MPCoopTopLevel())
	MPSendPacket("TRWN", id, payload)
end

function MPCoopShareReceive(id, data)
	if not MPCoopActive or id ~= MPCoopPartner or MPGameMode() ~= "Coop" then return end
	local trainer = tonumber(string.sub(data, 21, 24))
	local money = tonumber(string.sub(data, 25, 31))
	local script = 0                         --scripts are not shared (the addresses are different in every game)
	local map = tonumber(string.sub(data, 40, 44))
	local theirLevel = tonumber(string.sub(data, 45, 47)) or 0
	local cu = MPCoopCatch
	if trainer and cu.known[trainer] then            --the flag came first (burst): paid by the catch-up, or still on its list
		local inList = false
		for k, v in ipairs(cu.list) do
			if v == trainer then table.remove(cu.list, k) inList = true break end
		end
		cu.known[trainer] = nil
		if not inList then
			MPCoopEngaged[trainer] = nil
			MPCoopWon[trainer] = TotalFrame
			return
		end
	end
	if trainer then
		MPCoopEngaged[trainer] = nil
		MPCoopWon[trainer] = TotalFrame      --the NPC comes back when the flag of the trainer is set (MPCoopInactiveTick)
	end
	if not trainer or not money or not map or not MPCoopTrainerShared(trainer) then return end
	local p = FindPlayerByID(id)
	MPCS.pending = {trainer = trainer, money = money, script = script, map = map,
		sameBuild = (string.sub(data, 1, 4) == tostring(GameID)), name = tostring(p and p:GetNickname() or "Your partner"),
		since = TotalFrame, paid = false, theirLevel = theirLevel}
end

--once per frame
function MPCoopShareTick()
	local a = MPBattleAddress[GameID]
	local g = gAddress[GameID]
	if not a or not g or not MPMenuMode() or not EnableScript then return end
	MPLvlTick()
	--a trainer battle starts: the money and the script of the trainer are noted
	local cb = emu:read32(g.gMainCallback)
	if cb == a.initbattle + 1 and MPCS.lastCb ~= cb then
		local flags = emu:read32(g.gBattleTypeFlags)
		if MPGameMode() == "Coop" and (flags & 8) ~= 0 and (flags & 2) == 0 then
			MPCS.cur = {trainer = emu:read16(a.opp), money = MPGetMoney(), script = emu:read32(a.endscript), since = TotalFrame,
				seen = false, idle = 0}
		else
			MPCS.cur = nil
		end
	end
	MPCS.lastCb = cb
	--the battle is over and the player won
	local c = MPCS.cur
	if c then
		if IsInMenu() ~= 0 then
			c.seen = true
			c.idle = 0
		elseif c.seen then
			c.idle = c.idle + 1
			if c.idle >= 45 then
				MPCS.cur = nil
				if emu:read8(a.outcome) == 1 and MPCoopTrainerShared(c.trainer) then MPCoopShareSend(c)
				elseif MPCoopTrainerShared(c.trainer) then
					console:log("Coop: TREN sent: the battle was not won (outcome " .. emu:read8(a.outcome) .. ")")
					MPCoopEngageSend("TREN", c.trainer)
				end
				MPCoopMine = nil
			end
		end
		if TotalFrame - c.since > 36000 then
			MPCS.cur = nil
			if MPCoopMine then MPCoopEngageSend("TREN", MPCoopMine.trainer) MPCoopMine = nil end
		end
	end
	--the gate allowed the battle but it never started (the script ended, a message...): the partner is released again
	if MPCoopMine and not MPCS.cur and TotalFrame - MPCoopMine.since > 1800 and MPVs.watch == nil then
		console:log("Coop: TREN sent: the battle never started")
		MPCoopEngageSend("TREN", MPCoopMine.trainer)
		MPCoopMine = nil
	end
	--trainers beaten while we were away: paid once the burst after the connection is over and the player is free
	local cu = MPCoopCatch
	if #cu.list > 0 and TotalFrame >= cu.untilFrame and not MPCS.pending then
		local free = LockFromScript == 0 and ServerMsgStart < 0 and not MPVs.after and not MPVs.post and IsInMenu() == 0
			and emu:read8(g.gLockControls) == 0 and emu:read8(g.gScriptLoad) == 2
		if free then MPCoopCatchPay() end
	end
	--the result of the partner: money, message, then the same script
	local p = MPCS.pending
	if p then
		local ready = LockFromScript == 0 and ServerMsgStart < 0 and not MPVs.after and not MPVs.post and IsInMenu() == 0
		and emu:read8(g.gLockControls) == 0 and emu:read8(g.gScriptLoad) == 2
		if not p.paid and ready then
			p.paid = true
			MPVsTrainerFlag(p.trainer, true)
			local got = MPAddMoney(p.money)
			local text = p.name .. " beat a trainer!"
			if got > 0 then text = text .. "\nYou got $" .. tostring(got) .. " too." end
			local xp = MPCoopShareExp(p.trainer, p.theirLevel)
			if xp then
				text = text .. "\\p" .. xp.name .. " got " .. tostring(xp.gain) .. " Exp. Points!"
				if xp.newLevel > xp.oldLevel then text = text .. "\nIt grew to Lv. " .. tostring(xp.newLevel) .. "!" end
				if xp.moves > 0 then text = text .. "\\p" .. xp.name .. " learned " .. tostring(xp.moves) .. " new move(s)!" end
			end
			MPVsMessageThen(text, function() end)
		elseif p.paid and not MPVs.after then
			if p.script ~= 0 and p.sameBuild and TotalFrame - p.since < 36000 then
				if ready and MPMyMap() == p.map then
					MPCS.pending = nil
					MPVsGotoScript(p.script)
				end
			else
				MPCS.pending = nil
			end
		elseif TotalFrame - p.since > 36000 then
			MPCS.pending = nil
		end
	end
end

function MPCoopShareTickSafe()
	local ok, err = pcall(MPCoopShareTick)
	if not ok and not MPCS.errorLogged then
		MPCS.errorLogged = true
		console:log("Coop share error: " .. tostring(err))
	end
end

-- ------------------------------------------------------------------ Coop Doubles
--the RAM address of the first Pokemon of the party that can fight (no egg, HP left), or nil
function MPCDOwnLead()
	local g = gAddress[GameID]
	for i = 0, 5 do
		local base = g.gParty + i * 100
		local flags = emu:read8(base + 0x13)
		if (flags & 2) ~= 0 and (flags & 4) == 0 and emu:read16(base + 0x56) > 0 and emu:read8(base + 0x54) > 0 then return base end
	end
	return nil
end

--a part of the lead Pokemon of the partner arrived (CDLD)
function MPCDLeadReceive(id, data)
	local part = string.byte(data, 63)
	part = part and part - 48
	if not part or part < 0 then return end
	if part == 0 then MPCD.part[id] = "" end
	MPCD.part[id] = (MPCD.part[id] or "") .. string.sub(data, 21, 45)
	if part == MPMon.Sects - 1 and #MPCD.part[id] >= MPMon.Chars then MPCD.lead[id] = string.sub(MPCD.part[id], 1, MPMon.Chars) end
end

--CB2_InitBattle is about to run for a trainer battle: make it a double battle with the lead Pokemon of the partner
function MPCDStart()
	local g = gAddress[GameID]
	local a = MPBattleAddress[GameID]
	if MPGameMode() ~= "Coop Doubles" or MPCD.backup then return end
	local partner = MPCoopPartnerOK()
	if not partner then return end
	local lead = MPCD.lead[partner]
	if not lead then return end
	local flags = emu:read32(g.gBattleTypeFlags)
	if flags ~= 8 then return end                                   --a plain trainer battle (no link, no double, ...)
	local t = MPTrainerInfo(emu:read16(a.opp))
	if not t or t.size < 2 then return end
	local count = emu:read8(g.gPartyCount)
	if count < 1 or count > 6 then return end
	local own = {}
	for i = 0, count - 1 do own[i + 1] = i end
	local words = {}
	for i = 0, MPMon.Words * 6 - 1 do words[i] = emu:read32(g.gParty + i * 4) end
	local bytes = MPBytesFromRaw(lead)
	if MPFamilyOfPlayer(partner) ~= g.sGameVersion then MPClearItem(bytes) end
	--new order: first own Pokemon, the Pokemon of the partner, the other own Pokemon (the last one waits in the backup when there are 6)
	local order = {}
	order[1] = {src = "own", i = 0}
	order[2] = {src = "partner"}
	for i = 1, count - 1 do order[#order + 1] = {src = "own", i = i} end
	local n = math.min(6, #order)
	for k = 1, n do
		local o = order[k]
		for w = 0, 24 do
			local v
			if o.src == "own" then v = words[o.i * 25 + w] else v = MPGet32(bytes, w * 4) end
			emu:write32(g.gParty + (k - 1) * 100 + w * 4, v)
		end
	end
	emu:write8(g.gPartyCount, n)
	emu:write32(g.gBattleTypeFlags, flags | 1)
	MPCD.backup = {words = words, count = count, pers = MPGet32(bytes, 0), otid = MPGet32(bytes, 4), since = TotalFrame, seen = false}
end

--the battle is over: the own Pokemon back in order, the Pokemon of the partner out
function MPCDRestore()
	local b = MPCD.backup
	local g = gAddress[GameID]
	if not b then return end
	MPCD.backup = nil
	local count = emu:read8(g.gPartyCount)
	local cur = {}
	for i = 0, math.max(0, math.min(count, 6) - 1) do
		local w = {}
		for k = 0, 24 do w[k] = emu:read32(g.gParty + i * 100 + k * 4) end
		cur[#cur + 1] = w
	end
	local keep = {}
	local found = false
	for _, w in ipairs(cur) do
		if not found and w[0] == b.pers and w[1] == b.otid then found = true
		else keep[#keep + 1] = w end
	end
	if not found then
		--the Pokemon of the partner is not there: put back what was there before the battle
		keep = {}
		for i = 0, b.count - 1 do
			local w = {}
			for k = 0, 24 do w[k] = b.words[i * 25 + k] end
			keep[#keep + 1] = w
		end
	else
		--own Pokemon that did not fit in the party for the battle come back at the end
		for i = 0, b.count - 1 do
			local pers, otid = b.words[i * 25], b.words[i * 25 + 1]
			local there = false
			for _, w in ipairs(keep) do
				if w[0] == pers and w[1] == otid then there = true end
			end
			if not there and #keep < 6 then
				local w = {}
				for k = 0, 24 do w[k] = b.words[i * 25 + k] end
				keep[#keep + 1] = w
			end
		end
	end
	for i, w in ipairs(keep) do
		for k = 0, 24 do emu:write32(g.gParty + (i - 1) * 100 + k * 4, w[k]) end
	end
	for i = #keep + 1, 6 do
		for k = 0, 24 do emu:write32(g.gParty + (i - 1) * 100 + k * 4, 0) end
	end
	emu:write8(g.gPartyCount, #keep)
end

--once per frame
function MPCDTick()
	local a = MPBattleAddress[GameID]
	local g = gAddress[GameID]
	if not a or not g or not MPMenuMode() or not EnableScript then return end
	--send the lead Pokemon to the partner (when it changed or the partner is new)
	if MPGameMode() == "Coop Doubles" and MPCoopActive and MPCoopPartner and (Connected or Hosting) and TotalFrame >= MPCD.nextLead then
		MPCD.nextLead = TotalFrame + 60
		if not MPCD.backup and IsInMenu() == 0 then
			local base = MPCDOwnLead()
			if base then
				local raw = MPRawAt(base)
				if raw ~= MPCD.sentRaw or MPCD.sentTo ~= MPCoopPartner then
					MPCD.sentRaw = raw
					MPCD.sentTo = MPCoopPartner
					MPSendRaw("CDLD", MPCoopPartner, raw, 0)
				end
			end
		end
	end
	--a trainer battle starts
	local cb = emu:read32(g.gMainCallback)
	if cb == a.initbattle + 1 and MPCD.lastCb ~= cb then MPCDStart() end
	MPCD.lastCb = cb
	--the battle is over (the field is back after the battle was seen)
	local b = MPCD.backup
	if b then
		if IsInMenu() ~= 0 then b.seen = true end
		if (b.seen and IsInMenu() == 0) or TotalFrame - b.since > 36000 then MPCDRestore() end
	end
end

function MPCDTickSafe()
	local ok, err = pcall(MPCDTick)
	if not ok and not MPCD.errorLogged then
		MPCD.errorLogged = true
		console:log("Coop Doubles error: " .. tostring(err))
	end
end

-- BEGIN SOUL LINK
-- ===========================================================================================================================
-- 19b. SOUL LINK
-- ===========================================================================================================================
-- Two paired players link Pokemon of their parties. When a linked Pokemon of the partner faints, yours faints too (also in the
-- middle of a battle). Nothing else of the Nuzlocke is added: no permadeath, no "first catch only".
--
--   * Identity of a Pokemon = personality + OT id (stays when it moves to a box, is traded or evolves).
--   * A Pokemon that the player catches (or is given) after the baseline of the save was taken is linked automatically to the
--     partner's Pokemon that was caught in the same area (the met location) in the same order: first with first, second with second.
--     Pokemon that were there when Soul Link was first turned on, foreign (traded) ones and eggs are not linked by themselves.
--     By hand: soullink(my slot, partner slot) / soulunlink(my slot) in the console of the script.
--   * The faint travels as the state of the Pokemon: every change of HP is sent (SOUL packet). A linked Pokemon of the partner that
--     goes from HP > 0 to 0 makes the Pokemon it is linked to faint. The state of the partner is kept in a file, so a faint
--     that happened while one of the two was offline arrives when both are online again.
--   * Overlay (mGBA 0.11 canvas): in the party menu, the summary screen and in battle a panel says which Pokemon of the partner
--     the one on the screen is linked to and its condition.
--
-- SOUL packet, payload of 43 characters after the type (all printable):
--   M  slot(1) key(16 hex) loc(2) seq(4) species(4) level(2) hp(4) maxhp(4) flags(1: 1 egg, 2 baseline, 4 foreign)
--   N  key(16) nickname(10, upper case)
--   L  key of the sender's Pokemon(16) key of the receiver's Pokemon(16)         link
--   X  the same                                                                   unlink
--   H  startup(1: the partner sends its whole list in answer)                    "Soul Link is on"
--   S  on(1) change counter(10)   the on / off switch: the same for both paired players, the newer change wins (works while off)
