-- ------------------------------------------------------------------ small helpers
function MPSoulKey(pers, otid)
	return string.format("%08X%08X", pers & 0xFFFFFFFF, otid & 0xFFFFFFFF)
end

function MPSoulOn()
	return MPIni ~= nil and MPIni.soul == true
end

--the partner is somebody on the server who is paired with this player
function MPSoulFindPartner()
	local id = MPPartnerID()
	if not id then
		local ids = MPPairedIDs()
		id = ids[1]
	end
	return id
end

--is the link working right now: on, standard layout of the Pokemon and the partner told us that it is on
function MPSoulActive()
	return MPSoulOn() and MPMon.Standard and MPSoul.partner ~= nil and TotalFrame - MPSoul.seen < 900
end

function MPSoulText(bytes)
	local tbl = LanguageTable and LanguageTable[LanguageTableType]
	local t = {}
	for i = 0, 9 do
		local c = bytes[i]
		if c == nil or c == 0xFF then break end
		local ch = tbl and findKeyByValue(tbl, c)
		if type(ch) ~= "string" or #ch ~= 1 or ch < " " or ch > "~" then ch = "?" end
		t[#t + 1] = ch
	end
	return string.upper(table.concat(t))
end

--the text of a Pokemon of the partner (nickname, or the species number when it is not known)
function MPSoulName(rec)
	if rec and rec.nick and rec.nick ~= "" then return rec.nick end
	return "?"
end

function MPSoulPartnerName()
	local p = MPSoul.partner and FindPlayerByID(MPSoul.partner)
	return string.upper(tostring(p and p:GetNickname() or "PARTNER"))
end

function MPSoulSay(text)
	pcall(MPSay, text)
end

-- ------------------------------------------------------------------ the file (per own friend code, partner and save)
function MPSoulPath()
	if not MPSoul.partnerCode or not MPSoul.tid then return nil end
	local dir = string.match(MPIniPath(), "^(.*[/\\])") or ""
	return string.format("%sGBA-PK_SoulLink_%s_%s_%08X.txt", dir, tostring(MPIni.code), tostring(MPSoul.partnerCode), MPSoul.tid)
end

function MPSoulRecLine(tag, r)
	return string.format("%s %s %d %d %d %d %d %d %d %s", tag, r.key, r.loc or 0, r.seq or 0, r.species or 0, r.level or 0,
		r.hp or 0, r.maxhp or 0, (r.egg and 1 or 0) | (r.base and 2 or 0) | (r.foreign and 4 or 0), (string.gsub(r.nick or "", " ", "_")))
end

function MPSoulSave()
	local path = MPSoulPath()
	if not path then return end
	local lines = {"SOULLINK 1", "seq " .. MPSoul.seq, "baseline " .. (MPSoul.baseline and 1 or 0)}
	for _, r in pairs(MPSoul.mine) do lines[#lines + 1] = MPSoulRecLine("m", r) end
	for _, r in pairs(MPSoul.theirs) do lines[#lines + 1] = MPSoulRecLine("t", r) end
	for a, b in pairs(MPSoul.links) do lines[#lines + 1] = "l " .. a .. " " .. b end
	for k in pairs(MPSoul.ignored) do lines[#lines + 1] = "i " .. k end
	local ok, f = pcall(io.open, path, "w")
	if ok and f then
		f:write(table.concat(lines, "\n") .. "\n")
		f:close()
	end
	MPSoul.dirty = false
end

function MPSoulParseRec(line)
	local tag, key, loc, seq, species, level, hp, maxhp, flags, nick =
		string.match(line, "^([mt]) (%x+) (%d+) (%d+) (%d+) (%d+) (%d+) (%d+) (%d+) ?(.*)$")
	if not tag or #key ~= 16 then return nil end
	flags = tonumber(flags)
	return tag, {key = key, pers = tonumber(string.sub(key, 1, 8), 16), otid = tonumber(string.sub(key, 9, 16), 16),
		loc = tonumber(loc), seq = tonumber(seq), species = tonumber(species), level = tonumber(level), hp = tonumber(hp),
		maxhp = tonumber(maxhp), egg = (flags & 1) ~= 0, base = (flags & 2) ~= 0, foreign = (flags & 4) ~= 0,
		nick = (string.gsub(nick or "", "_", " ")), slot = 9}
end

function MPSoulLoad()
	MPSoul.mine, MPSoul.theirs, MPSoul.links, MPSoul.rlinks, MPSoul.ignored = {}, {}, {}, {}, {}
	MPSoul.seq, MPSoul.baseline, MPSoul.bySlot = 0, false, {}
	local path = MPSoulPath()
	if not path then return end
	local ok, f = pcall(io.open, path, "r")
	if not ok or not f then return end
	for line in f:lines() do
		local n = string.match(line, "^seq (%d+)")
		if n then MPSoul.seq = tonumber(n) end
		n = string.match(line, "^baseline (%d)")
		if n then MPSoul.baseline = (n == "1") end
		local tag, rec = MPSoulParseRec(line)
		if tag == "m" then MPSoul.mine[rec.key] = rec
		elseif tag == "t" then MPSoul.theirs[rec.key] = rec end
		local a, b = string.match(line, "^l (%x+) (%x+)$")
		if a then MPSoul.links[a] = b MPSoul.rlinks[b] = a end
		local k = string.match(line, "^i (%x+)$")
		if k then MPSoul.ignored[k] = true end
	end
	f:close()
end

-- ------------------------------------------------------------------ packets
function MPSoulFlags(r)
	return (r.egg and 1 or 0) | (r.base and 2 or 0) | (r.foreign and 4 or 0)
end

function MPSoulQueue(kind, key, payload)
	local qk = kind .. (key or "")
	if MPSoul.queued[qk] then
		for i, item in ipairs(MPSoul.outbox) do
			if item.qk == qk then item.payload = payload break end
		end
		return
	end
	MPSoul.queued[qk] = true
	MPSoul.outbox[#MPSoul.outbox + 1] = {qk = qk, payload = payload}
	if #MPSoul.outbox > 200 then
		local old = table.remove(MPSoul.outbox, 1)
		MPSoul.queued[old.qk] = nil
	end
end

function MPSoulQueueMon(r, withNick)
	local slot = (r.slot and r.slot < 6) and r.slot or 9
	MPSoulQueue("M", r.key, string.format("M%d%s%02X%04X%04X%02X%04X%04X%X", slot, r.key, (r.loc or 0) & 0xFF, (r.seq or 0) & 0xFFFF,
		(r.species or 0) & 0xFFFF, (r.level or 0) & 0xFF, (r.hp or 0) & 0xFFFF, (r.maxhp or 0) & 0xFFFF, MPSoulFlags(r)))
	if withNick then
		local nick = string.upper(string.gsub(r.nick or "", "[^%w%s%.%-']", "?"))
		MPSoulQueue("N", r.key, "N" .. r.key .. string.sub(nick .. string.rep(" ", 10), 1, 10))
	end
end

function MPSoulQueueAll()
	local list = {}
	for _, r in pairs(MPSoul.mine) do list[#list + 1] = r end
	table.sort(list, function(a, b) return (a.seq or 0) < (b.seq or 0) end)   --in the order of the catches (pairing needs it)
	for _, r in ipairs(list) do MPSoulQueueMon(r, true) end
	for a, b in pairs(MPSoul.links) do MPSoulQueue("L", a, "L" .. a .. b) end
end

function MPSoulFlush()
	local id = MPSoul.partner
	if not id then return end
	local n = 0
	while #MPSoul.outbox > 0 and n < 4 do
		local item = MPSoul.outbox[1]
		if not MPSendPacket("SOUL", id, item.payload) then return end
		table.remove(MPSoul.outbox, 1)
		MPSoul.queued[item.qk] = nil
		n = n + 1
	end
end

-- the packet is a record of the partner: payload from character 21 of the 64 byte frame
--is that player paired with this one (either way)?
function MPSoulPaired(id)
	return (MPIni.partner ~= nil and MPFriendCodes[id] == MPIni.partner) or (MPFriendPartner ~= nil and MPFriendPartner[id] == MPIni.code)
end

--tell the paired players the state of the switch (and its change counter)
function MPSoulSendState(only)
	local ids = only and {only} or MPPairedIDs()
	for _, id in ipairs(ids) do
		MPSendPacket("SOUL", id, string.format("S%d%010d", MPSoulOn() and 1 or 0, (MPIni.soulTime or 0) % 10000000000))
	end
end

--the partner's switch: a newer change than ours is taken over; an older one is answered with ours
function MPSoulStateReceive(id, data)
	if not MPSoulPaired(id) then return end
	local on = string.sub(data, 22, 22) == "1"
	local theirs = tonumber(string.sub(data, 23, 32)) or 0
	local mine = MPIni.soulTime or 0
	if theirs > mine then
		MPIni.soulTime = theirs
		local changed = on ~= MPSoulOn()
		MPIni.soul = on
		MPIniWrite()
		if changed then
			MPSoulReset()
			MPSoul.hudSig = nil
			local p = FindPlayerByID(id)
			local who = string.upper(tostring(p and p:GetNickname() or "Your partner"))
			MPSoulSay(MPTF("%s switched Soul Link %s.", who, on and "ON" or "OFF"))
		end
	elseif theirs < mine then
		MPSoulSendState(id)
	end
end

function MPSoulReceive(id, data)
	if string.sub(data, 21, 21) == "S" then MPSoulStateReceive(id, data) return end
	if not MPSoulOn() then return end
	if id ~= MPSoulFindPartner() then return end
	MPSoul.partner = id
	MPSoul.seen = TotalFrame
	local t = string.sub(data, 21, 21)
	if t == "M" then
		local slot = tonumber(string.sub(data, 22, 22))
		local key = string.sub(data, 23, 38)
		if not string.match(key, "^%x+$") or #key ~= 16 then return end
		local flags = tonumber(string.sub(data, 59, 59), 16) or 0
		local old = MPSoul.theirs[key]
		local rec = old or {key = key, pers = tonumber(string.sub(key, 1, 8), 16), otid = tonumber(string.sub(key, 9, 16), 16), nick = ""}
		local oldHp = old and old.hp
		rec.slot = slot or 9
		rec.loc = tonumber(string.sub(data, 39, 40), 16) or 0
		rec.seq = tonumber(string.sub(data, 41, 44), 16) or 0
		rec.species = tonumber(string.sub(data, 45, 48), 16) or 0
		rec.level = tonumber(string.sub(data, 49, 50), 16) or 0
		rec.hp = tonumber(string.sub(data, 51, 54), 16) or 0
		rec.maxhp = tonumber(string.sub(data, 55, 58), 16) or 0
		rec.egg, rec.base, rec.foreign = (flags & 1) ~= 0, (flags & 2) ~= 0, (flags & 4) ~= 0
		MPSoul.theirs[key] = rec
		MPSoul.dirty = true
		MPSoul.pairDirty = true
		--a Pokemon of the partner goes from HP > 0 to 0: the one it is linked to faints; from 0 to HP > 0: it is revived
		if oldHp ~= nil and rec.maxhp > 0 and not rec.egg then
			local mk = MPSoul.rlinks[key]
			if mk then
				if oldHp > 0 and rec.hp == 0 then
					MPSoul.pending[mk] = {from = key, since = TotalFrame, kind = "faint"}
				elseif oldHp == 0 and rec.hp > 0 then
					MPSoul.pending[mk] = {from = key, since = TotalFrame, kind = "revive"}
				end
			end
		end
	elseif t == "N" then
		local key = string.sub(data, 22, 37)
		local rec = MPSoul.theirs[key]
		if rec then
			rec.nick = (string.gsub(string.sub(data, 38, 47), "%s+$", ""))
			MPSoul.dirty = true
		end
	elseif t == "L" or t == "X" then
		local theirKey, myKey = string.sub(data, 22, 37), string.sub(data, 38, 53)
		if MPSoul.mine[myKey] then
			if t == "L" then
				MPSoulSetLink(myKey, theirKey, "remote")
			else
				MPSoulUnlink(myKey, true)
			end
		end
	elseif t == "H" then
		if string.sub(data, 22, 22) == "1" then MPSoulQueueAll() end
		MPSoul.pairDirty = true
	end
end

-- ------------------------------------------------------------------ links
function MPSoulSetLink(mk, tk, how)
	if MPSoul.links[mk] == tk then return end
	local oldT = MPSoul.links[mk]
	if oldT then MPSoul.rlinks[oldT] = nil end
	local oldM = MPSoul.rlinks[tk]
	if oldM then MPSoul.links[oldM] = nil end
	MPSoul.links[mk] = tk
	MPSoul.rlinks[tk] = mk
	MPSoul.ignored[mk], MPSoul.ignored[tk] = nil, nil
	MPSoul.dirty = true
	if how ~= "remote" then MPSoulQueue("L", mk, "L" .. mk .. tk) end
	local mr, tr = MPSoul.mine[mk], MPSoul.theirs[tk]
	if mr and tr and mr.maxhp > 0 and tr.maxhp > 0 and not mr.egg and not tr.egg and tr.hp == 0 and mr.hp > 0 then
		MPSoul.pending[mk] = {from = tk, since = TotalFrame, kind = "faint"}     --(the partner's side does the same for its Pokemon)
	end
	local text = string.format("Soul Link: %s is linked to %s's %s.", MPSoulName(mr), MPSoulPartnerName(), MPSoulName(tr))
	console:log(text)
	MPSoulSay(MPTF("Soul Link!\n%s is linked to\f%s's %s.", MPSoulName(mr), MPSoulPartnerName(), MPSoulName(tr)))
end

function MPSoulUnlink(mk, fromRemote)
	local tk = MPSoul.links[mk]
	if not tk then return false end
	MPSoul.links[mk] = nil
	MPSoul.rlinks[tk] = nil
	MPSoul.ignored[mk], MPSoul.ignored[tk] = true, true
	MPSoul.dirty = true
	if not fromRemote then MPSoulQueue("X", mk, "X" .. mk .. tk) end
	return true
end

--the automatic pairing: the n-th catch of this player in an area with the n-th catch of the partner in the same area.
--Only the records of a player that are complete from catch number 1 on are used (a record that is still on its way may not
--shift the others: both sides must get the same pairs)
function MPSoulPair()
	local function pool(t, mineSide)
		local list = {}
		for key, r in pairs(t) do
			if (r.seq or 0) > 0 then list[#list + 1] = r end
		end
		table.sort(list, function(a, b) return a.seq < b.seq end)
		local out, expect = {}, 1
		for _, r in ipairs(list) do
			if r.seq ~= expect then break end
			expect = expect + 1
			local linked = mineSide and MPSoul.links[r.key] or (not mineSide and MPSoul.rlinks[r.key])
			if not linked and not r.base and not r.foreign and not r.egg and not MPSoul.ignored[r.key] then
				out[r.loc] = out[r.loc] or {}
				table.insert(out[r.loc], r)
			end
		end
		return out
	end
	local A, B = pool(MPSoul.mine, true), pool(MPSoul.theirs, false)
	for loc, la in pairs(A) do
		local lb = B[loc]
		if lb then
			for i = 1, math.min(#la, #lb) do MPSoulSetLink(la[i].key, lb[i].key, "auto") end
		end
	end
end

-- ------------------------------------------------------------------ own party
function MPSoulTrainerID()
	local g = gAddress[GameID]
	if not g or not g.gSaveBlock2Ptr then return nil end
	local base = (g.sGameVersion ~= "RS") and emu:read32(g.gSaveBlock2Ptr) or g.gSaveBlock2Ptr
	if not MPInEwram(base) then return nil end
	local tid = emu:read16(base + 0x0A) | (emu:read16(base + 0x0C) << 16)   --(+0x0A is not word aligned: read32 would rotate)
	if tid == 0 then return nil end
	return tid
end

function MPSoulReadParty()
	local g = gAddress[GameID]
	if not g or not g.gParty or not g.gPartyCount then return nil end
	local n = emu:read8(g.gPartyCount)
	if n > 6 then return nil end
	local out = {}
	for slot = 0, n - 1 do
		local a = g.gParty + slot * 100
		local pers, otid = emu:read32(a), emu:read32(a + 4)
		if pers ~= 0 or otid ~= 0 then
			out[#out + 1] = {slot = slot, addr = a, pers = pers, otid = otid, level = emu:read8(a + 0x54),
				hp = emu:read16(a + 0x56), maxhp = emu:read16(a + 0x58)}
		end
	end
	return out
end

function MPSoulDecode(addr)
	local b = {}
	for i = 0, 24 do MPPut32(b, i * 4, emu:read32(addr + i * 4)) end
	return MPFmtCodec.S100.parse(b)
end

function MPSoulFieldNow()
	local g, c = gAddress[GameID], MPCallback and MPCallback[GameID]
	if not g or not c or not c.Field then return false end
	return emu:read32(g.gMainCallback) == c.Field + 1
end

function MPSoulPoll()
	local party = MPSoulReadParty()
	local tid = MPSoulTrainerID()
	if not party or not tid then return end
	-- the file of this save
	if MPSoul.tid ~= tid or MPSoul.fileName ~= MPSoulPath() then
		if MPSoul.dirty then MPSoulSave() end
		MPSoul.tid = tid
		MPSoulLoad()
		MPSoul.fileName = MPSoulPath()
		MPSoul.helloLeft = 3
		MPSoul.pairDirty = true
	end
	-- the baseline: the Pokemon that are there when Soul Link starts in this save are not linked by themselves
	local sig = {}
	for _, m in ipairs(party) do sig[#sig + 1] = string.format("%08X%08X", m.pers, m.otid) end
	sig = table.concat(sig, ",")
	if sig == MPSoul.sig then MPSoul.stable = MPSoul.stable + 1 else MPSoul.stable = 0 MPSoul.sig = sig end
	local takeBaseline = false
	if not MPSoul.baseline then
		if MPSoul.stable >= 30 and MPSoulFieldNow() then
			takeBaseline = true
			MPSoul.baseline = true
			MPSoul.dirty = true
		else
			return                       --nothing is registered before the baseline
		end
	end
	local present = {}
	MPSoul.bySlot = {}
	for _, m in ipairs(party) do
		local key = MPSoulKey(m.pers, m.otid)
		present[key] = true
		MPSoul.bySlot[m.slot] = key
		local rec = MPSoul.mine[key]
		local changed, nickChanged = false, false
		if not rec or rec.level ~= m.level or rec.egg or takeBaseline then
			local f = MPSoulDecode(m.addr)
			local egg = ((f.ivs >> 30) & 1) == 1
			if not rec then
				rec = {key = key, pers = m.pers, otid = m.otid, foreign = (m.otid ~= tid), base = takeBaseline, seq = 0, slot = m.slot}
				MPSoul.mine[key] = rec
				changed, nickChanged = true, true
			end
			local nick = MPSoulText(f.nick)
			if nick ~= rec.nick then rec.nick = nick nickChanged = true end
			if rec.loc ~= f.metloc or rec.species ~= f.species or rec.egg ~= egg then changed = true end
			rec.loc, rec.species, rec.egg = f.metloc, f.species, egg
			if not egg and (rec.seq or 0) == 0 and not rec.base and not rec.foreign then
				MPSoul.seq = MPSoul.seq + 1               --a catch (or gift, or hatched egg) after the baseline
				rec.seq = MPSoul.seq
				changed = true
				MPSoul.pairDirty = true
			end
		end
		if rec.hp ~= m.hp or rec.maxhp ~= m.maxhp or rec.level ~= m.level or rec.slot ~= m.slot then changed = true end
		rec.hp, rec.maxhp, rec.level, rec.slot = m.hp, m.maxhp, m.level, m.slot
		if changed then
			MPSoul.dirty = true
			MPSoulQueueMon(rec, nickChanged)
		end
	end
	for key, r in pairs(MPSoul.mine) do
		if not present[key] and r.slot ~= 9 then
			r.slot = 9                                   --left the party (box, trade): the state stays as it was
			MPSoul.dirty = true
			MPSoulQueueMon(r, false)
		end
	end
end

-- ------------------------------------------------------------------ the faint of a linked Pokemon
function MPSoulInBattle()
	local a = MPSoulAddr[GameID]
	if a then return MPInEwram(emu:read32(a.res)) end
	local g = gAddress[GameID]
	return g ~= nil and g.BattleMainCB2 ~= nil and emu:read32(g.gMainCallback) == g.BattleMainCB2 + 1   --a hack: the callback of the battle
end

--the battle is a link battle (the two players fight each other, a trade...): the Pokemon are not linked meanwhile
function MPSoulSuspended()
	local g = gAddress[GameID]
	if MPSoulInBattle() and g.gBattleTypeFlags and (emu:read32(g.gBattleTypeFlags) & 0x2) ~= 0 then return true end
	return false
end

--the game's own faint sequence (cry, animation, "X fainted!") for battler b whose HP was just set to 0: the battle script
--"tryfaintmon BS_ATTACKER; end2" in free ROM is started as the game starts a script of its own (BattleScriptExecute: push the main
--function on the callback stack, the main function becomes RunBattleScriptCommands_PopCallbacksStack, gBattlescriptCurrInstr = script).
--Without it the game would only notice the 0 HP at the end of the turn (no animation, the health box would still show the old HP).
MPSoulFaintScriptAt = 0x8FFFF00
MPSoulFaintScript = {0x00000119, 0x3E000000}   --0x19 tryfaintmon, BS_ATTACKER (1), FALSE, NULL(4); 0x3E end2
function MPSoulStartFaint(a, b)
	if not a.popcb or not a.instr or not a.actfn or not a.attacker then return false end
	local at = MPSoulFaintScriptAt
	local w0, w1 = ROMCARD:read32(at), ROMCARD:read32(at + 4)
	if w0 ~= MPSoulFaintScript[1] or w1 ~= MPSoulFaintScript[2] then
		if w0 ~= 0xFFFFFFFF or w1 ~= 0xFFFFFFFF then return false end          --the place is not free: the game notices it by itself
		ROMCARD:write32(at, MPSoulFaintScript[1])
		ROMCARD:write32(at + 4, MPSoulFaintScript[2])
	end
	local res = emu:read32(a.res)
	local cbs = MPInEwram(res) and emu:read32(res + 0x0C) or 0       --gBattleResources->battleCallbackStack
	if not MPInEwram(cbs) then return false end
	local size = emu:read8(cbs + 0x20)
	if size >= 8 then return false end
	emu:write32(cbs + size * 4, emu:read32(a.main))
	emu:write8(cbs + 0x20, size + 1)
	emu:write32(a.main, a.popcb)
	emu:write8(a.actfn, 0)
	emu:write8(a.attacker, b)
	emu:write32(a.instr, at)
	return true
end

--writes HP 0 into a party slot (and into the battle copy at a moment in which the game looks at it). true when done
function MPSoulApplyFaint(slot, key)
	local g = gAddress[GameID]
	local a = MPSoulAddr[GameID]
	local base = g.gParty + slot * 100
	if emu:read32(base) ~= MPSoul.mine[key].pers or emu:read32(base + 4) ~= MPSoul.mine[key].otid then return true end   --not there any more
	if emu:read16(base + 0x56) == 0 then return true end                                     --is down already
	if a and MPSoulInBattle() then
		local count = emu:read8(a.count)
		for b = 0, count - 1 do
			if b % 2 == 0 and emu:read16(a.idx + b * 2) == slot then       --it is on the field: the game must see it fall
				if emu:read32(a.main) ~= a.passed then return false end    --wait for the end of the turn
				local mon = a.mons + b * 0x58
				emu:write16(mon + 0x28, 0)
				emu:write16(base + 0x56, 0)
				MPSoulStartFaint(a, b)
				return true
			end
		end
	end
	if not a and MPSoulInBattle() then return false      --a hack: nothing known about its battle, wait until it is over
	end
	emu:write16(base + 0x56, 0)
	return true
end

--the linked Pokemon is revived: HP in the same proportion as the partner's (at least 1). Done when it is up already
function MPSoulApplyRevive(slot, key, theirs)
	local g = gAddress[GameID]
	local a = MPSoulAddr[GameID]
	local rec = MPSoul.mine[key]
	local base = g.gParty + slot * 100
	if emu:read32(base) ~= rec.pers or emu:read32(base + 4) ~= rec.otid then return true end   --not there any more
	if emu:read16(base + 0x56) ~= 0 then return true end                                      --is up already
	if MPSoulInBattle() then
		if not a then return false end                                                         --a hack: after the battle
		for b = 0, emu:read8(a.count) - 1 do
			--on the field (down, waiting for the next Pokemon to be chosen): the battle must not see it come back
			if b % 2 == 0 and emu:read16(a.idx + b * 2) == slot then return false end
		end
	end
	local maxhp = emu:read16(base + 0x58)
	if maxhp == 0 then return true end
	local hp = math.floor(maxhp * (theirs.hp or 0) / math.max(theirs.maxhp or 1, 1) + 0.5)
	emu:write16(base + 0x56, math.max(1, math.min(maxhp, hp)))
	return true
end

function MPSoulTickPending()
	if not next(MPSoul.pending) then return end
	if not MPSoulActive() or MPSoulSuspended() then return end
	for mk, p in pairs(MPSoul.pending) do
		local r = MPSoul.mine[mk]
		local theirs = MPSoul.theirs[p.from]
		if not r or r.slot == 9 or r.slot == nil or not theirs or MPSoul.links[mk] ~= p.from then
			MPSoul.pending[mk] = nil                       --in a box, or the link is gone: nothing to do
		elseif p.kind == "faint" and theirs.hp > 0 then
			MPSoul.pending[mk] = nil                       --it was up again before the end of the turn
		elseif p.kind == "revive" and theirs.hp == 0 then
			MPSoul.pending[mk] = nil                       --it fell again before this could be applied
		elseif p.kind == "revive" then
			if MPSoulApplyRevive(r.slot, mk, theirs) then
				MPSoul.pending[mk] = nil
				console:log("Soul Link: " .. MPSoulName(r) .. " is up again because " .. MPSoulName(theirs) .. " is")
				MPSoulSay(MPTF("%s's %s is up again,so your %s is back too!", MPSoulPartnerName(), MPSoulName(theirs), MPSoulName(r)))
			end
		elseif MPSoulApplyFaint(r.slot, mk) then
			MPSoul.pending[mk] = nil
			console:log("Soul Link: " .. MPSoulName(r) .. " fainted because " .. MPSoulName(theirs) .. " did")
			MPSoulSay(MPTF("%s's %s fainted,so your %s fainted too!", MPSoulPartnerName(), MPSoulName(theirs), MPSoulName(r)))
		elseif TotalFrame - p.since > 7200 then
			MPSoul.pending[mk] = nil                       --two minutes without a safe moment
		end
	end
end

-- ------------------------------------------------------------------ overlay
--a font of 3 x 5 pixels (rows of 3 bits, the left pixel is bit 2)
MPSoulFont = {
	A = {2, 5, 7, 5, 5}, B = {6, 5, 6, 5, 6}, C = {3, 4, 4, 4, 3}, D = {6, 5, 5, 5, 6}, E = {7, 4, 6, 4, 7}, F = {7, 4, 6, 4, 4},
	G = {3, 4, 5, 5, 3}, H = {5, 5, 7, 5, 5}, I = {7, 2, 2, 2, 7}, J = {1, 1, 1, 5, 2}, K = {5, 5, 6, 5, 5}, L = {4, 4, 4, 4, 7},
	M = {5, 7, 7, 5, 5}, N = {6, 5, 5, 5, 5}, O = {2, 5, 5, 5, 2}, P = {6, 5, 6, 4, 4}, Q = {2, 5, 5, 7, 3}, R = {6, 5, 6, 5, 5},
	S = {3, 4, 2, 1, 6}, T = {7, 2, 2, 2, 2}, U = {5, 5, 5, 5, 7}, V = {5, 5, 5, 5, 2}, W = {5, 5, 7, 7, 5}, X = {5, 5, 2, 5, 5},
	Y = {5, 5, 2, 2, 2}, Z = {7, 1, 2, 4, 7},
	["0"] = {7, 5, 5, 5, 7}, ["1"] = {2, 6, 2, 2, 7}, ["2"] = {6, 1, 2, 4, 7}, ["3"] = {6, 1, 2, 1, 6}, ["4"] = {5, 5, 7, 1, 1},
	["5"] = {7, 4, 6, 1, 6}, ["6"] = {3, 4, 6, 5, 2}, ["7"] = {7, 1, 2, 2, 2}, ["8"] = {2, 5, 2, 5, 2}, ["9"] = {2, 5, 3, 1, 6},
	["."] = {0, 0, 0, 0, 2}, [":"] = {0, 2, 0, 2, 0}, ["-"] = {0, 0, 7, 0, 0}, ["/"] = {1, 1, 2, 4, 4}, ["<"] = {1, 2, 4, 2, 1},
	[">"] = {4, 2, 1, 2, 4}, ["!"] = {2, 2, 2, 0, 2}, ["?"] = {6, 1, 2, 0, 2}, ["'"] = {2, 2, 0, 0, 0}, ["%"] = {5, 1, 2, 4, 5},
	["+"] = {0, 2, 7, 2, 0}, [","] = {0, 0, 0, 2, 4}, ["="] = {0, 7, 0, 7, 0}, ["#"] = {5, 7, 5, 7, 5},
}
MPSoulScale = 2
MPSoulColors = {text = 0xFFFFFFFF, ok = 0xFF70E890, down = 0xFFFF6060, dim = 0xFFB0B8C8, back = 0xD0101828}

function MPSoulHudInit()
	if MPSoul.hud or MPSoul.hudFailed then return MPSoul.hud end
	local cv = rawget(_G, "canvas")
	local im = rawget(_G, "image")
	if not cv or not im then MPSoul.hudFailed = true return nil end
	local ok, hud = pcall(function()
		local w, h = 240, 160
		local layer = cv:newLayer(w, h)
		local painter = im.newPainter(layer.image)
		painter:setBlend(false)
		painter:setFill(true)
		layer:setPosition(0, 0)
		return {layer = layer, painter = painter, w = w, h = h}
	end)
	if not ok then MPSoul.hudFailed = true return nil end
	MPSoul.hud = hud
	return hud
end

function MPSoulDrawText(hud, x, y, s, color)
	local sc = MPSoulScale
	hud.painter:setFillColor(color)
	for i = 1, #s do
		local gl = MPSoulFont[string.sub(s, i, i)]
		if gl then
			for row = 1, 5 do
				local bits = gl[row]
				for col = 0, 2 do
					if bits & (4 >> col) ~= 0 then hud.painter:drawRectangle(x + col * sc, y + (row - 1) * sc, sc, sc) end
				end
			end
		end
		x = x + 4 * sc
	end
end

function MPSoulHudClear(hud)
	hud.painter:setFillColor(0x00000000)
	hud.painter:drawRectangle(0, 0, hud.w, hud.h)
end

--what the panel says about one of my Pokemon: {title, status, color of the status}
function MPSoulInfo(mk)
	local mr = MPSoul.mine[mk]
	if not mr then return nil end
	local tk = MPSoul.links[mk]
	if not tk then
		if mr.foreign then return {"NOT LINKED", "TRADED POKEMON", MPSoulColors.dim} end
		if mr.base then return {"NOT LINKED", "CAUGHT BEFORE SOUL LINK", MPSoulColors.dim} end
		return {"NOT LINKED YET", "WAITING FOR " .. string.sub(MPSoulPartnerName(), 1, 8) .. "'S CATCH", MPSoulColors.dim}
	end
	local tr = MPSoul.theirs[tk]
	local title = "<> " .. string.sub(MPSoulPartnerName(), 1, 8) .. "'S " .. string.sub(MPSoulName(tr), 1, 10) .. " L" .. tostring(tr and tr.level or "?")
	if not tr then return {title, "NO DATA YET", MPSoulColors.dim} end
	if tr.hp == 0 then return {title, "FAINTED", MPSoulColors.down} end
	return {title, string.format("HP %d/%d", tr.hp, tr.maxhp), MPSoulColors.ok}
end

--which of my Pokemon is on the screen: a list of keys with a header, or nil
function MPSoulContext()
	local g, a = gAddress[GameID], MPSoulAddr[GameID]
	if not a then return nil end
	local cb = emu:read32(g.gMainCallback)
	if cb == a.sumcb then
		local sum = emu:read32(a.summary)
		if MPInEwram(sum) then
			--the Pokemon that is shown is copied into the data of the screen: struct Pokemon currentMon (Emerald: +0x0C, FireRed / LeafGreen: +0x3290)
			local off = ({BPR = 0x3290, BPG = 0x3290})[string.sub(tostring(GameID), 1, 3)] or 0x0C
			local pers, otid = emu:read32(sum + off), emu:read32(sum + off + 4)
			if pers ~= 0 or otid ~= 0 then return {kind = "mon", top = true, {MPSoulKey(pers, otid)}} end   --(top: the page below has text there)
		end
		return nil
	end
	if cb == a.pmcb then
		local slot = emu:read8(a.pdata + 9)
		if slot < 6 and MPSoul.bySlot[slot] then return {kind = "mon", {MPSoul.bySlot[slot]}} end
		return nil
	end
	if MPSoulInBattle() then
		local list = {}
		local count = emu:read8(a.count)
		for b = 0, math.min(count, 4) - 1 do
			if b % 2 == 0 then
				local key = MPSoul.bySlot[emu:read16(a.idx + b * 2)]
				if key then list[#list + 1] = key end
			end
		end
		if #list > 0 then return {kind = "battle", list} end
	end
	return nil
end

function MPSoulHudTick()
	local ctx = MPSoulActive() and MPSoulContext() or nil
	local sig = "-"
	local lines = {}
	if ctx then
		local keys = ctx[1]
		for _, mk in ipairs(keys) do
			local info = MPSoulInfo(mk)
			if info then lines[#lines + 1] = info end
		end
		local parts = {ctx.kind, ctx.top and "top" or "bottom"}
		for _, l in ipairs(lines) do parts[#parts + 1] = l[1] .. "|" .. l[2] end
		sig = table.concat(parts, ";")
	end
	if sig == MPSoul.hudSig then return end
	local hud = MPSoulHudInit()
	if not hud then MPSoul.hudSig = sig return end
	MPSoul.hudSig = sig
	MPSoulHudClear(hud)
	if ctx and #lines > 0 then
		if ctx.kind == "battle" then
			local sc, rowh = 1, 9
			for i, l in ipairs(lines) do
				local y = (i - 1) * rowh
				hud.painter:setFillColor(MPSoulColors.back)
				hud.painter:drawRectangle(0, y, hud.w, rowh)
				local save = MPSoulScale
				MPSoulScale = sc
				MPSoulDrawText(hud, 3, y + 2, l[1], MPSoulColors.text)
				MPSoulDrawText(hud, hud.w - #l[2] * 4 * sc - 3, y + 2, l[2], l[3])
				MPSoulScale = save
			end
		else
			local sc = MPSoulScale
			local l = lines[1]
			local h = 2 * (5 * sc + 4) + 6
			local y = ctx.top and 1 or (hud.h - h - 1)
			hud.painter:setFillColor(MPSoulColors.back)
			hud.painter:drawRectangle(0, y, hud.w, h)
			MPSoulDrawText(hud, 4, y + 4, l[1], MPSoulColors.text)
			MPSoulDrawText(hud, 4, y + 4 + 5 * sc + 4, l[2], l[3])
		end
	end
	pcall(function() hud.layer:update() end)
end

-- ------------------------------------------------------------------ main tick
function MPSoulReset()
	MPSoul.partner, MPSoul.partnerCode = nil, nil
	MPSoul.outbox, MPSoul.queued = {}, {}
	MPSoul.helloLeft = 3
	MPSoul.seen = -100000
end

function MPSoulTick()
	--a paired player (new on the server, or we are new): tell the state of the switch, also when it is off
	local paired = {}
	for _, pid in ipairs(MPPairedIDs()) do paired[#paired + 1] = pid end
	local sig = table.concat(paired, ",")
	if sig ~= MPSoul.pairedSig then
		MPSoul.pairedSig = sig
		if #paired > 0 and (MPIni.soulTime or MPSoulOn()) then MPSoulSendState() end
	end
	if not MPSoulOn() then
		if MPSoul.hudSig and MPSoul.hudSig ~= "-" then MPSoul.hudSig = nil MPSoulHudTick() end
		return
	end
	local g = gAddress[GameID]
	if not g or not g.gParty or not MPMon.Standard then return end
	-- the partner
	local id = MPSoulFindPartner()
	if id ~= MPSoul.partner then
		MPSoulReset()
		MPSoul.partner = id
		MPSoul.pairDirty = true
		if id then MPSoulQueueAll() end
	end
	MPSoul.partnerCode = MPIni.partner or (id and MPFriendCodes[id]) or nil
	if TotalFrame >= MPSoul.nextPoll then
		MPSoul.nextPoll = TotalFrame + 3
		MPSoulPoll()
	end
	if MPSoul.partner then
		if TotalFrame >= MPSoul.nextBeat then
			MPSoul.nextBeat = TotalFrame + 180
			local startup = MPSoul.helloLeft > 0
			if startup then MPSoul.helloLeft = MPSoul.helloLeft - 1 end
			MPSoulQueue("H", nil, "H" .. (startup and "1" or "0"))
			for slot = 0, 5 do
				local k = MPSoul.bySlot[slot]
				if k and MPSoul.mine[k] then MPSoulQueueMon(MPSoul.mine[k], false) end
			end
		end
		if MPSoul.pairDirty and MPSoul.baseline then
			MPSoul.pairDirty = false
			MPSoulPair()
		end
		MPSoulFlush()
		MPSoulTickPending()
	end
	--the panel needs the canvas of mGBA 0.11: say it once when Soul Link is working (the linking itself does not need it)
	if not MPSoul.noted and MPSoulActive() then
		MPSoul.noted = true
		if not (rawget(_G, "canvas") and rawget(_G, "image")) then
			console:log("Soul Link: the panel needs mGBA 0.11 or newer (this build has no canvas). Linking, fainting and reviving work as usual.")
			MPSoulSay(MPT("Soul Link panel needs\nmGBA 0.11 or newer."))
		end
	end
	if MPSoul.dirty and TotalFrame >= MPSoul.nextSave then
		MPSoul.nextSave = TotalFrame + 120
		MPSoulSave()
	end
	if TotalFrame >= MPSoul.nextHud then
		MPSoul.nextHud = TotalFrame + 6
		MPSoulHudTick()
	end
end

function MPSoulTickSafe()
	local ok, err = pcall(MPSoulTick)
	if not ok and not MPSoul.errorLogged then
		MPSoul.errorLogged = true
		console:log("Soul Link error: " .. tostring(err))
	end
end

-- ------------------------------------------------------------------ settings and console
function MPSoulToggle()
	MPIni.soul = not MPSoulOn()
	MPIni.soulTime = math.max(os.time(), (MPIni.soulTime or 0) + 1)       --always newer than anything seen
	MPIniWrite()
	MPSoulSendState()
	MPSoulReset()
	MPSoul.hudSig = nil
	if MPIni.soul then
		MPSoulSay(MPT("Soul Link ON: linked\nPokemon faint and revive\ftogether."))
	else
		MPSoulSay(MPT("Soul Link OFF."))
	end
end

function MPSoulLabel()
	local mark = MPSoulOn() and " ON" or " OFF"
	if MPSoulOn() and not MPMon.Standard then mark = " OFF" end
	return MPTF("Soul Link:%s", mark)
end

--the table in the console: own party and the partner's Pokemon with the link
function soul()
	if not MPSoulOn() then console:log("Soul Link is off (Settings in the MULTI menu).") return end
	console:log(string.format("Soul Link with %s: %s", MPSoulPartnerName(), MPSoulActive() and "active" or "waiting for the partner"))
	local function line(r, tag)
		local lk = (tag == "mine") and MPSoul.links[r.key] or MPSoul.rlinks[r.key]
		local other = lk and ((tag == "mine") and MPSoul.theirs[lk] or MPSoul.mine[lk])
		return string.format("  %s%s  L%d  %d/%d  %s%s", r.slot and r.slot < 6 and ("#" .. (r.slot + 1) .. " ") or "box ", MPSoulName(r),
			r.level or 0, r.hp or 0, r.maxhp or 0, lk and ("<-> " .. MPSoulName(other) .. (other and (" " .. other.hp .. "/" .. other.maxhp) or "")) or "not linked",
			(r.base and " (before)") or (r.foreign and " (traded)") or "")
	end
	local function listing(t, tag)
		local arr = {}
		for _, r in pairs(t) do arr[#arr + 1] = r end
		table.sort(arr, function(a, b)
			local sa, sb = (a.slot or 9) < 6 and a.slot or 100 + (a.seq or 0), (b.slot or 9) < 6 and b.slot or 100 + (b.seq or 0)
			return sa < sb
		end)
		for _, r in ipairs(arr) do console:log(line(r, tag)) end
	end
	console:log("Yours:")
	listing(MPSoul.mine, "mine")
	console:log(MPSoulPartnerName() .. ":")
	listing(MPSoul.theirs, "theirs")
end

--link by hand: the slot (1-6) of your party and the slot (1-6) of the partner's party
function soullink(mySlot, theirSlot)
	if not MPSoulActive() then console:log("Soul Link is not active.") return end
	local mk = MPSoul.bySlot[(tonumber(mySlot) or 0) - 1]
	local tk
	for _, r in pairs(MPSoul.theirs) do
		if r.slot == (tonumber(theirSlot) or 0) - 1 then tk = r.key end
	end
	if not mk or not tk then console:log("soullink(your slot 1-6, partner slot 1-6): that slot is empty.") return end
	MPSoulSetLink(mk, tk, "hand")
end

function soulunlink(mySlot)
	local mk = MPSoul.bySlot[(tonumber(mySlot) or 0) - 1]
	if mk and MPSoulUnlink(mk, false) then
		console:log("Unlinked " .. MPSoulName(MPSoul.mine[mk]) .. ".")
	else
		console:log("soulunlink(your slot 1-6): that slot is not linked.")
	end
end
-- END SOUL LINK

-- ===========================================================================================================================
-- 20. MAIN TICK
-- ===========================================================================================================================

--once per frame (called by Connection, which runs with and without a network)
function MPTick()
	if not MPMenuMode() or not EnableScript or not GameID or not gAddress[GameID] then return end
	if not Hosting and not Connected then MPRefreshVars() end
	MPCoopTickSafe()
	MPVsTickSafe()
	MPCDTickSafe()
	MPCoopShareTickSafe()
	pcall(MPCoopItemTick)
	pcall(MPProgressTick)
	pcall(MPObjTick)
	pcall(MPRegionTick)
	pcall(MPHoennTick)
	pcall(MPXpEvoTick)
	pcall(MPMansionTick)
	pcall(MPBaseTick)
	pcall(MPNameTick)
	MPSoulTickSafe()

	--The entry says MULTI for a moment when the START menu is drawn: after START was pressed, when the game comes back from a
	--screen of the menu and, while a part of the menu (the save question...) is active, because the menu is drawn again when it
	--ends. A menu that is just open and waiting says EXIT again after a few frames, so a script that is removed then leaves EXIT.
	if MPMenuReady then
		local inMenu = IsInMenu() ~= 0
		local busy = inMenu or emu:read8(gAddress[GameID].gLockControls) ~= 0
		if MPMenuOpen then
			if busy then
				MPOpenIdle = 0
			else
				MPOpenIdle = MPOpenIdle + 1
				if MPOpenIdle > MPLabelFrames then MPMenuOpen = false end   --closed
			end
		end
		if MPPrevInMenu and not inMenu then MPLabelHold = TotalFrame + MPLabelFrames end
		MPPrevInMenu = inMenu
		local on = TotalFrame < MPLabelHold
		local a = MPAddress[GameID]
		if MPLabelSubmenus and MPMenuOpen and a then
			local cb = emu:read32(a.callback)
			if cb ~= a.input and cb ~= a.func and cb ~= 0 then
				on = true
				MPLabelHold = math.max(MPLabelHold, TotalFrame + MPLabelFrames)
			end
		end
		MPSetLabel(on)
	end

	--a connection that is being made
	if MPConnectPending then
		if not Connected then
			MPConnectPending = false
		elseif PlayerID ~= 0 and FindPlayerByID(PlayerID) then
			MPConnectPending = false
			MPSay(MPT("Connected to the server!"))
			MPAnnounceCode()
		elseif MPRefusedCode then
			local code = MPRefusedCode
			MPRefusedCode = nil
			MPDropConnection()
			if code == 1 then
				MPSay(MPT("The server refused you:\nthe name is already used.\fChange the nickname and\ntry again."))
			else
				MPSay(MPT("The server refused you:\nit is full.\fTry again later."))
			end
		elseif TotalFrame - MPConnectSince > 600 then
			MPDropConnection()
			MPSay(MPT("The server did not answer.") .. "\n" .. string.gsub(MPFailText(MPLastIP, MPLastPort), "^[^\n]*\n", ""))
			MPAsk("retry", MPT("Try a different IP?"), {MPT("Yes"), MPT("No")})
		end
	end

	--a request of another player to pair with them: asked when the player is free
	if MPState == 0 and #MPPairRequests > 0 and MPPlayerFree() then
		local r = table.remove(MPPairRequests, 1)
		MPPairAsked[r.id] = nil          --asked now: the same player may ask again later
		local p = FindPlayerByID(r.id)
		if p then
			local who = tostring(p:GetNickname())
			MPConfirm(MPTF("%s wants to pair\nwith you. Accept?", who), function()
				MPIni.partner = r.code
				MPIniWrite()
				MPSentCode = {}
				MPAnnounceCode()
				MPSendPacket("FRRP", r.id, MPIni.code .. "Y")
				MPSay(MPTF("Paired with %s.", who))
				end, function()
					MPSendPacket("FRRP", r.id, MPIni.code .. "N")
			end)
		end
	end

	--EXIT chosen in the START menu: the game stores the function of the chosen entry in a variable. A new choice always wins:
	--whatever menu was open or waiting (and maybe stuck) is dropped
	local a = MPAddress[GameID]
	if a then
		local cb = emu:read32(a.callback)
		if cb == a.func and MPPrevCallback ~= a.func then
			if MPState ~= 0 or LockFromScript == 50 then MPAbort() end
			MPAsk("main", MPT("Multiplayer\nWhat would you like to do?"), nil)
		end
		MPPrevCallback = cb
	end

	--fail safes: LockFromScript 50 belongs to the menu. When no menu is on the screen it must not stay (it blocks the other
	--functions of the script), and the list of the game must not stay replaced
	if LockFromScript == 50 and MPState ~= 2 then LockFromScript = 0 end
	if MPState ~= 2 and LockFromScript ~= 2 and PrevExtraAdr == 0 and MPMultiOrig then
		local g = gAddress[GameID]
		local now = ROMCARD:read32(g.gMultiChoice)
		if now == g.gMultiChoiceData or now == MPKeypadList then MPRestoreMultichoice() end
	end

	if MPState == 1 then
		if MPPlayerFree() then
			MPWait = MPWait + 1
			if MPWait >= 10 then
				local r = MPRequest
				MPRequest = nil
				if not r then MPState = 0 return end
				LockFromScript = 50
				MPState = 2
				MPActiveKind = r.kind
				MPMenuStart = TotalFrame
				MPRequestAt = TotalFrame
				if r.kind == "key" then
					local title
					if MPKeyKind == "ip" then title = MPT("Server IP address:")
					elseif MPKeyKind == "port" then title = MPT("Server port:")
					else title = MPT("Code to pair with:") end
					if MPKeyNote then title = MPKeyNote end
					MPMenuTitle = title .. "\n" .. MPKeyText
					Loadscript(MPKeyKind == "code" and 41 or 40)
				else
					MPMenuTitle = r.title
					if r.kind == "main" then
						MPMenuOptions = {MPT(Hosting and "Stop Hosting" or "Host"), MPT(Connected and "Disconnect" or "Connect"), MPT("Settings"), MPT("Cancel")}
					elseif r.kind == "settings" then
						MPMenuOptions = MPSettingsLabels()
					else
						MPMenuOptions = r.options
					end
					Loadscript(39)
				end
			end
		else
			MPWait = 0
			if TotalFrame - MPRequestAt > 3600 then MPAbort("the game was busy for a minute") end   --a minute at 60 fps
		end
	elseif MPState == 2 then
		if LockFromScript ~= 50 then
			MPAbort()                                            --something else took over
		else
			local choice = emu:read16(gAddress[GameID].gSpecialVar_8000) --variable 0x8000: the chosen entry + 1, 0 while the menu is open
			if choice ~= 0 and TotalFrame - MPMenuStart > 5 then
				LockFromScript = 0
				MPState = 0
				MPRestoreMultichoice()
				MPNoLockFrames = 0
				MPMenuBusyFrames = 0
				MPOnChoice(MPActiveKind, choice)
			else
				--interrupted? A battle or a screen of the game is open, or the script of the menu is not running any more: while the
				--menu waits for a choice the script engine waits (status 1) inside our script. Status 2 (no script) or a script
				--of the game (a trainer, an event...) means that it is gone.
				if IsInMenu() ~= 0 then MPMenuBusyFrames = MPMenuBusyFrames + 1 else MPMenuBusyFrames = 0 end
				if TotalFrame - MPMenuStart > 30 and (MPScriptStatus() == 2 or not MPScriptIsOurs()) then
					MPNoLockFrames = MPNoLockFrames + 1
				else
					MPNoLockFrames = 0
				end
				if MPMenuBusyFrames > 5 then
					MPAbort("a battle or a screen opened")
				elseif MPNoLockFrames > 20 then
					MPAbort("the game took the controls back")
				elseif TotalFrame - MPMenuStart > 7200 then
					MPAbort("no answer for two minutes")
				end
			end
		end
	end
end

--MPTick may never break the rest of the script: a Lua error is caught here, the menu state is reset and the script goes on
function MPTickSafe()
	local ok, err = pcall(MPTick)
	if not ok then
		if not MPErrorLogged then
			MPErrorLogged = true
			console:log("Multiplayer menu error (the menu was reset): " .. tostring(err))
		end
		pcall(MPAbort)
	end
end

function MPKeyHookSafe()
	pcall(MPKeyHook)
end

--console commands
function host()
	if not MPMenuMode() or not EnableScript then console:log("host() needs ServerType = \"m\"") return end
	if Hosting then console:log("Already hosting.") return end
	MPChoose(1)
end

function connect()
	if not MPMenuMode() or not EnableScript then console:log("connect() needs ServerType = \"m\"") return end
	if Connected then console:log("Already connected.") return end
	MPChoose(2)
end

function disconnect()
	if not MPMenuMode() or not EnableScript then return end
	if Hosting then MPChoose(1) elseif Connected then MPChoose(2) end
end

function StartScript()
	if RestartScript then return end
	EnableScript = false
	ResetVariables()
	if #players > 0 then
		for i, player in ipairs(players) do
			player:Clear()
		end
	end

	if ConsoleForText == nil then
		if ServerType == "m" or ServerType == "M" then
			ConsoleForText = console:createBuffer("GBA-PK")
		elseif ServerType == "h" or ServerType == "s" or ServerType == "H" or ServerType == "S" then
			ConsoleForText = console:createBuffer("GBA-PK SERVER")
		else
			ConsoleForText = console:createBuffer("GBA-PK CLIENT")
		end

		ConsoleForText:clear()
		ConsoleForText:moveCursor(0,0)
		ConsoleForText:print("A new game has started")
		ConsoleForText:moveCursor(0,1)
	end
	FFTimer2 = os.time()
	GetGameVersion()
	MPCompatStart()
	MPAdjustFreeSpace()
	if EnableScript then
		ROMCARD = emu.memory.cart0



		if MPMenuMode() then
			MPOnStart()
		elseif #players < 1 then
			if ServerType == "h" or ServerType == "s" or ServerType == "H" or ServerType == "S" then
				CreateNetwork()
			elseif ServerType == "c" then
				ConnectNetwork()
			else
				--If set to anything other than h or c make it client
				ConnectNetwork()
			end
		end
	end
end

function StopScript()
	MPVsShutdown()
	MPRestoreMenu()
	RestartScript = false
	EnableScript = false
	ConsoleForText:clear()
	--console:log("The game was shutdown. Please restart the script when the game is open.")
	console:log("The game was shutdown. It is highly recommended to restart the script.")
	ResetVariables()
	players = {}
end

function ResetVariables()
	ServerNPCReset()
	DebugMenus = {}
	DebugMenusPrev = {}
	LockFromScript = 0
	TextSpeedWait = 0
	PositionData = {
		Bike = 0,
		Direction = 0,
		PlayerMapIDPrev = 0,
		PlayerMapID = 0,
		PlayerMapEntranceType = 0,
		PlayerMapChange = 0,
		CurrentX = 0,
		CurrentY = 0,
		PreviousX = 0,
		PreviousY = 0,
		Animation = 0,
		Gender = 0,
		SpriteType = 0,
		BorderX = 9999,
		BorderY = 9999,
		Connections = {},
		AnimationData = 0,
		Animate2 = 0,
		AnimType = 0,
		AnimLength = 0,
		Elevation = 0,
		PrevSurf = false,
		CurrentCameraX = 0,
		CurrentCameraY = 0,
		AnimationByte = 0,
		AnimationDirection = 0,
		isAnimating = 0,
		isCrossingBorder = 0,
		CameraXPos = 0,
		CameraYPos = 0,
		UseMapPos = false,
		ActualX = 0,
		ActualY = 0,
	}
	RefreshRenderPlayer()
end

-- ===========================================================================================================================
-- 21. NETWORK
-- ===========================================================================================================================

--the listening socket of the host is never read
function NetIsListener(sock)
	return Hosting and sock == SocketMain
end

--mGBA polls every socket once per frame (select) to call 'received' callbacks that this script does not use
function NetUnhook(sock)
	if sock and sock._onframecb then
		callbacks:remove(sock._onframecb)
		sock._onframecb = nil
	end
end

--forget everything about a socket (queues, unread bytes)
function NetForget(sock)
	NetOut[sock] = nil
	NetIn[sock] = nil
end

--a socket that is not used by any player anymore is flushed and closed (host only, the clients share one socket)
function NetRelease(sock)
	if not (Hosting and sock and sock ~= SocketMain) then return end
	for _, p in ipairs(players) do
		if p:GetSocket() == sock then return end
	end
	for _, p in ipairs(temp_players) do
		if p:GetSocket() == sock then return end
	end
	pcall(NetFlush, sock)
	NetForget(sock)
	pcall(sock.close, sock)
end

-- ------------------------------------------------------------------ sending
function NetSend(sock, data)
	if not sock or not data or #data == 0 then return end
	local q = NetOut[sock]
	if not q then
		q = {items = {}, first = 1, last = 0, bytes = 0, offset = 0, spos = {}}
		NetOut[sock] = q
	end
	local spos = nil
	if #data == NetFrameSize and string.sub(data, 17, 20) == "SPOS" then
		spos = string.sub(data, 21, 24) --the player the snapshot belongs to
		if q.bytes > NetQueueSoft then
			local at = q.spos[spos]
			--replace the waiting snapshot of this player, unless it is already partly written
			if at and at >= q.first and q.items[at] and #q.items[at] == NetFrameSize and not (at == q.first and q.offset > 0) then
				q.items[at] = data
				NetStats.collapsed = NetStats.collapsed + 1
				return
			end
		end
	end
	q.last = q.last + 1
	q.items[q.last] = data
	q.bytes = q.bytes + #data
	if spos then q.spos[spos] = q.last end
	if q.bytes > NetQueueHard then
		console:log("Network: connection is not accepting data, dropping " .. q.bytes .. " waiting bytes")
		NetOut[sock] = nil
		return
	end
	if not NetDefer then NetFlush(sock) end
end

--write what is waiting. Returns true when the queue is empty
function NetFlush(sock)
	local q = NetOut[sock]
	if not q or q.bytes == 0 then return true end
	for _ = 1, 64 do
		local parts, size, i = {}, 0, q.first
		while i <= q.last and size < NetWriteMax do
			local item = q.items[i]
			if i == q.first and q.offset > 0 then item = string.sub(item, q.offset + 1) end
			parts[#parts + 1] = item
			size = size + #item
			i = i + 1
		end
		local chunk = table.concat(parts)
		local n, err = sock:send(chunk)
		if n == nil and err == nil then n = #chunk end --a socket that does not report how much it wrote (SimuSocket)
		if not n or n <= 0 then
			NetStats.refused = NetStats.refused + 1
			return false --"temporary failure" or an error: everything stays queued
		end
		NetStats.writes = NetStats.writes + 1
		NetStats.bytesOut = NetStats.bytesOut + n
		local written = n
		q.bytes = q.bytes - n
		while n > 0 do
			local item = q.items[q.first]
			local left = #item - q.offset
			if n >= left then
				n = n - left
				q.items[q.first] = nil
				q.first = q.first + 1
				q.offset = 0
			else
				q.offset = q.offset + n
				n = 0
			end
		end
		if q.first > q.last then
			q.items, q.first, q.last, q.offset, q.bytes, q.spos = {}, 1, 0, 0, 0, {}
			return true
		end
		if written < #chunk then
			NetStats.partial = NetStats.partial + 1
			return false --the socket is full, the rest follows in the next frame
		end
	end
	return false
end

function NetFlushAll()
	for sock, q in pairs(NetOut) do
		if q.bytes > 0 then pcall(NetFlush, sock) end
	end
end

--first frame callback of every frame
function NetBeginFrame()
	if NetDefer then
		--the previous frame was never closed by NetEndFrame (callback missing): stop waiting for it, write at once from now on
		NetNoDefer = true
		NetFlushAll()
		console:log("Network: NetEndFrame did not run, packets are written immediately")
	end
	NetDefer = not NetNoDefer
end

--last frame callback of every frame: everything that was queued during the frame is written now
function NetEndFrame()
	NetDefer = false
	NetFlushAll()
end

-- ------------------------------------------------------------------ receiving
--is there a frame at buf[pos..pos+63]? header: game id (4 letters/digits), player id and target id (4 digits each), request type, 'U' at the end
function NetFrameAt(buf, pos)
	return string.byte(buf, pos + 63) == 85
	and string.find(buf, "^%w%w%w%w", pos) ~= nil
	and string.find(buf, "^%d%d%d%d%d%d%d%d", pos + 8) ~= nil
	and string.find(buf, "^[%u%d][%u%d][%u%d][%u%d]", pos + 16) ~= nil
end

--moves st.pos to the next complete frame (st.ready = true), skipping bytes that cannot start one
function NetScan(st)
	local buf, pos = st.buf, st.pos
	local last = #buf - NetFrameSize + 1
	local start = pos
	while pos <= last do
		if NetFrameAt(buf, pos) then
			if pos > start then
				NetStats.skipped = NetStats.skipped + (pos - start)
				console:log("Network: skipped " .. (pos - start) .. " bytes that were not a packet")
			end
			st.pos = pos
			st.ready = true
			return true
		end
		pos = pos + 1
	end
	st.pos = pos --what is left may be the start of a frame that is not complete yet
	st.ready = false
	return false
end

--true when a complete frame can be taken with NetNextFrame. Reads from the socket when needed
function NetHasFrame(sock)
	if NetIsListener(sock) then return false end
	local st = NetIn[sock]
	if not st then
		st = {buf = "", pos = 1, ready = false, polled = -1}
		NetIn[sock] = st
	end
	if st.ready then return true end
	if NetScan(st) then return true end
	--read what the socket has. Frames can arrive in pieces, so the rest of the last one stays in the buffer
	if st.polled == TotalFrame then return false end --already looked for new bytes in this frame
	st.polled = TotalFrame
	if st.pos > 1 then
		st.buf = string.sub(st.buf, st.pos)
		st.pos = 1
	end
	for _ = 1, 32 do
		local chunk, err = sock:receive(NetReadChunk)
		if not chunk or #chunk == 0 then
			if err == "disconnected" then st.dead = true end --the other side closed the connection
			break
		end
		st.dead = false
		NetStats.reads = NetStats.reads + 1
		NetStats.bytesIn = NetStats.bytesIn + #chunk
		st.buf = st.buf .. chunk
		if #chunk < NetReadChunk then break end
	end
	if #st.buf > 262144 then
		console:log("Network: too much unreadable data, clearing it")
		st.buf = ""
		st.pos = 1
		return false
	end
	return NetScan(st)
end

--the next frame (a string of NetFrameSize bytes) or nil
function NetNextFrame(sock)
	local st = NetIn[sock]
	if not st or not (st.ready or NetHasFrame(sock)) then return nil end
	NetStats.framesIn = NetStats.framesIn + 1
	local frame = string.sub(st.buf, st.pos, st.pos + NetFrameSize - 1)
	st.pos = st.pos + NetFrameSize
	st.ready = false
	if st.pos > #st.buf then
		st.buf = ""
		st.pos = 1
	end
	return frame
end

-- Battle data (BATT + 7 BAT2 frames, every network tick) is rebuilt by the receiver by counting the BAT2 frames after a BATT. The
-- battle script then looks at that count (Transfer_Stage > 6) at some moment of a frame. When the stream is cut inside a group
-- (the internet does that, a loopback connection does not) the count is below 7 at that moment and the check fails again and
-- again. So a BATT whose BAT2 frames have not all arrived yet is kept in the buffer until they have (at most NetGroupHold frames).
NetGroupHold = 20                      --frames a half arrived group may wait
NetGroupSince = setmetatable({}, {__mode = "k"})
function NetHoldGroup(sock)
	local st = NetIn[sock]
	if not st or not st.ready then return false end
	local buf, pos = st.buf, st.pos
	if string.sub(buf, pos + 16, pos + 19) ~= "BATT" then return false end
	local n, p, last = 0, pos + NetFrameSize, #buf - NetFrameSize + 1
	while n < 7 do
		if p > last then break end                      --the buffer ends inside the group: wait for the rest
		if not NetFrameAt(buf, p) then
			NetGroupSince[sock] = nil
			return false                                    --garbage after it: do not wait
		end
		local kind = string.sub(buf, p + 16, p + 19)
		if kind == "BATT" then NetGroupSince[sock] = nil return false end --a new group starts: this one is as complete as it gets
		if kind == "BAT2" then n = n + 1 end
		p = p + NetFrameSize
	end
	if n >= 7 then
		if NetGroupSince[sock] then BLogAdd("battle data group complete after waiting " .. (TotalFrame - NetGroupSince[sock]) .. " frames") end
		NetGroupSince[sock] = nil
		return false
	end
	local since = NetGroupSince[sock]
	if not since then
		NetGroupSince[sock] = TotalFrame
		BLogCount("held")
		return true
	end
	if TotalFrame - since > NetGroupHold then
		NetGroupSince[sock] = nil
		BLogAdd("battle data group still incomplete after " .. NetGroupHold .. " frames, using it as it is")
		return false
	end
	return true
end

-- Battle log: the last events of a battle (state changes of the script, what arrived per second, players that left). In the
-- console of mGBA: blog() prints it, blog(true) empties it.
BLog = {}
BLogMax = 300
BLogCounts = {}
BLogLastLock = 0
BLogLastSecond = 0
function BLogAdd(text)
	BLog[#BLog + 1] = string.format("%s frame %d (%s fps): %s", os.date("%H:%M:%S", os.time()), TotalFrame or 0, tostring(FPS or "?"), text)
	if #BLog > BLogMax then table.remove(BLog, 1) end
end
function BLogCount(kind)
	BLogCounts[kind] = (BLogCounts[kind] or 0) + 1
end
function BLogTick()
	if LockFromScript ~= BLogLastLock then
		BLogAdd("script state " .. BLogLastLock .. " -> " .. LockFromScript)
		BLogLastLock = LockFromScript
	end
	local now = os.time()
	if now ~= BLogLastSecond then
		BLogLastSecond = now
		if LockFromScript >= 14 and LockFromScript <= 22 or LockFromScript == 9 or LockFromScript == 21 then
			local parts = {}
			for k, v in pairs(BLogCounts) do parts[#parts + 1] = k .. "=" .. v end
			table.sort(parts)
			BLogAdd("received in the last second: " .. (#parts > 0 and table.concat(parts, " ") or "nothing"))
		end
		BLogCounts = {}
	end
end
function blog(clear)
	for _, line in ipairs(BLog) do console:log(line) end
	console:log(#BLog .. " lines")
	if clear then BLog = {} end
end

--the other side closed this connection (seen by the read that returned 'disconnected')
function NetIsDead(sock)
	local st = NetIn[sock]
	return st ~= nil and st.dead == true
end

--console: netstats() shows what the network layer did since the last call
function netstats()
	local now = os.time()
	local secs = math.max(1, now - NetStats.since)
	local s = NetStats
	console:log(string.format("Network last %ds: out %d B in %d writes (%d refused, %d partial, %d snapshots replaced) | in %d B, %d reads, %d packets, %d stray bytes skipped",
		secs, s.bytesOut, s.writes, s.refused, s.partial, s.collapsed, s.bytesIn, s.reads, s.framesIn, s.skipped))
	for k in pairs(s) do s[k] = 0 end
	s.since = now
end

-- ------------------------------------------------------------------ timing
--should the sockets be read in this frame? (FPS_Network_Receive keeps its old meaning when it is set)
function NetShouldReceive()
	if FPS_Network_Receive ~= 0 then return updateTimers("network_receive") end
	if FPS <= 0 then return true end
	local interval = math.floor(FPS / NetReceiveHz)
	if interval <= 1 then return true end
	return TotalFrame % interval == 0
end

--should the host look for new connections in this frame?
function NetShouldAccept()
	if FPS <= 0 then return true end
	local interval = math.floor(FPS / NetAcceptHz)
	if interval <= 1 then return true end
	return TotalFrame % interval == 0
end

--the position packet of this player. Built once per frame, whatever the number of players it is sent to
function NetOwnSPOS()
	if NetOwnFrame ~= TotalFrame or not NetOwnPacket then
		CreatePacket("SPOS", PlayerID, PlayerID)
		local me = FindPlayerByID(PlayerID)
		if me and MPMvSent then MPMvSent(me) end
		NetOwnPacket = Packet
		NetOwnFrame = TotalFrame
	end
	return NetOwnPacket
end
--Begin Networking

--Create Server

function CreateNetwork()
	if not Hosting then
		Hosting = true
		PlayerID = 1
		AddPlayer(PlayerID, SocketMain, Nickname, GameID, GetPosition())
		local success, errorMessage = SocketMain:bind(nil, Port)
		if not success then
			EnableScript = false
			ConsoleForText:print("Hosting could not be started. Please restart the script. Error: " .. errorMessage)
		else
			SocketMain:listen()
			ConsoleForText:moveCursor(0,3)
			ConsoleForText:print("Hosting game. Port forwarding may be required.")
		end
		ConsoleForText:moveCursor(0,3)
		ConsoleForText:print("Hosting game. Port forwarding may be required.")
		ConsoleForText:moveCursor(0,4)
		ConsoleForText:print("Searching for players...												")
	end
end

function ConnectNetwork()
	if not Connected then
		ConsoleForText:moveCursor(0,3)
		ConsoleForText:print("Searching for an open game on IP ".. IPAddress .. ". Please do not touch the emulator.")
		local success, errorMessage = SocketMain:connect(IPAddress, Port)
		if success then
			Connected = true
			NetUnhook(SocketMain)
			ConsoleForText:moveCursor(0,3)
			ConsoleForText:print("Game found. Sending request to join as a player...										")
			SendData(SocketMain, "Request")
		else
			RestartScript = true
			EnableScript = false
			ConsoleForText:clear()
			console:log("Error connecting. Error type: " .. errorMessage)
			console:log("Please restart the script")
		end
	end
end

function Disconnect()
	BLogAdd("Disconnect()")
	NetForget(SocketMain)
	ServerNPCReset()
	SocketMain:close()
	PlayerID = 0
	players = {}
	UpdatePlayerConsole()
	ConsoleForText:moveCursor(0,3)
	console:log("You have timed out")
	ConsoleForText:print("You have been disconnected due to timeout.										   ")
	ConsoleForText:moveCursor(0,4)
	ConsoleForText:print("Connected to a server: No		 ")
	Connected = false
	if MPMenuMode() then
		MPAfterDisconnect()
		return
	end
	ConnectNetwork()
end

function Connection()
	MPTickSafe()
	ServerMsgTick()
	if updateTimers("network_send") then
		if Hosting then
			if #players > 1 then
				for i, player in ipairs(players) do
					local ActualPlayer = FindPlayerByID(PlayerID)
					if player:GetID() ~= PlayerID then
						NetSend(player:GetSocket(), NetOwnSPOS())

						--Trade
						if LockFromScript == 9 and ActualPlayer:GetTalking() == player:GetID() then
							SendSpecialData(player:GetSocket(), "TRAD", player:GetID())
						end
						--Battle
						if LockFromScript == 21 and ActualPlayer:GetTalking() == player:GetID() then
							SendSpecialData(player:GetSocket(), "BATT", player:GetID())
							for i=1, 7 do --send bat2 4 times
								SendSpecialData(player:GetSocket(), "BAT2", player:GetID())
							end
						end
						if player:GetTimeout() <= 0 or NetIsDead(player:GetSocket()) then
							SendData(player:GetSocket(), "DISC", player:GetID())
							for i, player2 in ipairs(players) do
								local SocketToUse = player2:GetSocket()
								if player2:GetID() ~= PlayerID and player2:GetID() ~= player:GetID() then
									CreatePacket("RPLA", player:GetID(), player:GetID())
									NetSend(SocketToUse, Packet)
								end
							end
							RemovePlayer(player:GetID())
						end
					end
				end
			end
		elseif Connected then
			if #players > 1 then
				for i, player in ipairs(players) do
					if player:GetID() == 1 and (player:GetTimeout() <= 0 or NetIsDead(SocketMain)) then
						Disconnect()
					end
				end

				NetSend(SocketMain, NetOwnSPOS())
				--Trade
				if LockFromScript == 9 then
					local Player = FindPlayerByID(PlayerID)
					if Player then
						SendSpecialData(SocketMain, "TRAD", Player:GetTalking())
					end
				end
				--Battle
				if LockFromScript == 21 then
					local Player = FindPlayerByID(PlayerID)
					if Player then
						SendSpecialData(SocketMain, "BATT", Player:GetTalking())
						for i=1, 7 do --send bat2 7 times
							SendSpecialData(SocketMain, "BAT2", Player:GetTalking())
						end
					end
				end
			end
		end
	else
		MPMvExtraSend()
	end
	if NetShouldReceive() then
		if Hosting then
			local PlayerData = nil
			if NetShouldAccept() then PlayerData = SocketMain:accept() end
			if (PlayerData ~= nil) then
				NetUnhook(PlayerData)
				AddTempPlayer(PlayerData)
			end
			if #temp_players > 0 then
				for i, player in ipairs(temp_players) do
					ReceiveData(player:GetSocket())
					if player:GetTimeout() <= 0 then
						RemoveTempPlayer(player)
					end
				end
			end
			if #players > 1 then
				for i, player in ipairs(players) do
					ReceiveData(player:GetSocket())
					local ActualPlayer = FindPlayerByID(PlayerID)
					--Trade
					if LockFromScript == 9 and ActualPlayer:GetTalking() == player:GetID() then
						ReceiveData(player:GetSocket())
					end
					--Battle
					if LockFromScript == 21 and ActualPlayer:GetTalking() == player:GetID() then
						ReceiveData(player:GetSocket())
						for i=1, 7 do
							ReceiveData(player:GetSocket())
						end
					end
				end
			end
		elseif Connected then
			if SocketMain then
				ReceiveData(SocketMain)
				--Trade
				if LockFromScript == 9 then
					ReceiveData(SocketMain)
				end
				--Battle
				if LockFromScript == 21 then
					ReceiveData(SocketMain)
					for i=1, 7 do
						ReceiveData(SocketMain)
					end
				end
			end
		end
	end
end

-- ===========================================================================================================================
-- 22. PACKETS
-- ===========================================================================================================================

function ReceiveData(SocketMain)
	local function parseReceivedData(ReadData)
		local packet = {
			GameID = string.sub(ReadData, 1, 4),
			Nickname = "FFFF",
			PlayerID = tonumber(string.sub(ReadData, 9, 12)),
			SendToID = tonumber(string.sub(ReadData, 13, 16)),
			RequestType = string.sub(ReadData, 17, 20),
			ExtraData = string.sub(ReadData, 21, 63),
			Validate = string.sub(ReadData, 64, 64),
			IsSpecial = false,
		}
		if packet.Validate ~= "U" then
			console:log("got unverified packet: " .. ReadData)
		end
		if packet.Validate == "U" then
			if packet.RequestType == "POKE" then
				packet.PokeBytes = string.sub(ReadData,21,45)
				packet.IsSpecial = true
			elseif packet.RequestType == "POK2" then
				packet.slot = string.byte(string.sub(ReadData, 62, 62))
				packet.sect = string.byte(string.sub(ReadData, 63, 63))
				packet.pkmn = {}
				for i=1, 25 do
					packet.pkmn[i] = string.byte(string.sub(ReadData, 20+i, 20+i))
				end
			elseif packet.RequestType == "TRAD" then
				packet.TradeBytes = {
					Text_Stage = tonumber(string.sub(ReadData, 21, 24)) - 1000,
					Pokemon_Select = tonumber(string.sub(ReadData, 25, 28)) - 1000,
					Trade_Start = tonumber(string.sub(ReadData, 29, 32)) - 1000,
				}
				packet.IsSpecial = true
			elseif packet.RequestType == "BATT" then
				packet.BattleBytes = {
					Text_Stage = string.byte(string.sub(ReadData, 21, 21)),
					Waiting_Status = string.byte(string.sub(ReadData, 22, 22)),
					Battle_Start = string.byte(string.sub(ReadData, 23, 23)),
					Buffer_ID = string.byte(string.sub(ReadData, 24, 24)),
					Attacker = string.byte(string.sub(ReadData, 25, 25)),
					Target = string.byte(string.sub(ReadData, 26, 26)),
					Absent_Battler = string.byte(string.sub(ReadData, 27, 27)),
					Effect_Battler = string.byte(string.sub(ReadData, 28, 28)),
					Transfer_Stage = 0,
					Send_ID = string.byte(string.sub(ReadData, 63, 63)),
					Buffer_A = {},
					Buffer_B = {},
					Battleflags = {},
				}
				for i = 1, 30 do
					packet.BattleBytes.Buffer_A[i] = string.byte(string.sub(ReadData, i+28, i+28))
				end
				for i = 1, 4 do
					packet.BattleBytes.Battleflags[i] = string.byte(string.sub(ReadData, i+58, i+58))
				end
				packet.IsSpecial = true
			elseif packet.RequestType == "BAT2" then
				packet.Transfer_Stage = 1
				packet.Buffer_A = {}
				packet.Buffer_B = {}
				for i = 1, 20 do
					packet.Buffer_A[i] = string.byte(string.sub(ReadData, i+20, i+20))
				end
				for i = 1, 20 do
					packet.Buffer_B[i] = string.byte(string.sub(ReadData, i+40, i+40))
				end
			elseif packet.RequestType == "BAT3" then
				packet.BattleBytes = {
					Link_Battle_Header_versionLo = string.byte(string.sub(ReadData, 21, 21)),
					Link_Battle_Header_versionHi = string.byte(string.sub(ReadData, 22, 22)),
					Link_Battle_Header_vsLo = string.byte(string.sub(ReadData, 23, 23)),
					Link_Battle_Header_vsHi = string.byte(string.sub(ReadData, 24, 24)),
					Link_Battle_Header_Itemdata = {},
					Transfer_Stage = 1,
				}
				for i = 1, 27 do
					packet.BattleBytes.Link_Battle_Header_Itemdata[i] = string.byte(string.sub(ReadData, i+24, i+24))
				end
				packet.IsSpecial = true
			elseif packet.RequestType == "CARD" then
				packet.CardBytes = string.sub(ReadData,21,30) - 1000000000
				packet.CardBytes2 = string.sub(ReadData,31,40) - 1000000000
				packet.CardBytes3 = string.sub(ReadData,41,50) - 1000000000
				packet.CardBytes4 = string.sub(ReadData,51,60) - 1000000000
				packet.IsSpecial = true
			elseif packet.RequestType == "NICK" then
				packet.NicknameSpecial = string.sub(ReadData,21,63)
				packet.EngineTag, packet.FmtTag = string.match(packet.NicknameSpecial, "#(%x%x%x%x%x%x%x%x)%$(%w%w%w%w)$")
				packet.NicknameSpecial = packet.NicknameSpecial:gsub("~*#%x%x%x%x%x%x%x%x%$%w%w%w%w$", "")
				packet.NicknameSpecial = packet.NicknameSpecial:gsub("~*$", "")
				if DebugMessages.Nickname then console:log("NICK: " .. packet.NicknameSpecial) end
			elseif packet.RequestType == "NPCS" or packet.RequestType == "NMSG" or packet.RequestType == "NSCR" or packet.RequestType == "DEDI" or packet.RequestType == "FRCD" or packet.RequestType == "FRRQ" or packet.RequestType == "FRRP" or packet.RequestType == "TRNR" or packet.RequestType == "TRRQ" or packet.RequestType == "VSTM" or packet.RequestType == "CDLD"or packet.RequestType == "MODE"or packet.RequestType == "TRWN"or packet.RequestType == "TRST" or packet.RequestType == "TREN" or packet.RequestType == "PRGS" or packet.RequestType == "OBJE" or packet.RequestType == "SBAS" or packet.RequestType == "SOUL" then
				packet.IsSpecial = true --dedicated server packets, handled below
			else
				packet.RequestBytes = tonumber(string.sub(packet.ExtraData, 1, 4))
				packet.Battle = string.byte(string.sub(packet.ExtraData, 5, 5)) | (string.byte(string.sub(packet.ExtraData, 6, 6)) << 8) | (string.byte(string.sub(packet.ExtraData, 7, 7)) << 16) | (string.byte(string.sub(packet.ExtraData, 8, 8)) << 24)
				packet.Direction = string.byte(string.sub(packet.ExtraData, 9, 9))
				packet.MapID = string.byte(string.sub(packet.ExtraData, 10, 10)) | (string.byte(string.sub(packet.ExtraData, 11, 11)) << 8)
				packet.PreviousMapID = string.byte(string.sub(packet.ExtraData, 12, 12)) | (string.byte(string.sub(packet.ExtraData, 13, 13)) << 8)
				packet.CurrentX = string.byte(string.sub(packet.ExtraData, 14, 14)) | (string.byte(string.sub(packet.ExtraData, 15, 15)) << 8)
				packet.CurrentY = string.byte(string.sub(packet.ExtraData, 16, 16)) | (string.byte(string.sub(packet.ExtraData, 17, 17)) << 8)
				--15-18 is previous x and y, not used
				packet.BorderX = string.byte(string.sub(packet.ExtraData, 22, 22)) | (string.byte(string.sub(packet.ExtraData, 23, 23)) << 8)
				packet.BorderY = string.byte(string.sub(packet.ExtraData, 24, 24)) | (string.byte(string.sub(packet.ExtraData, 25, 25)) << 8)
				packet.MapConnectionType = string.byte(string.sub(packet.ExtraData, 27, 27))
				--24 is entrance, not used
				packet.Animation = string.byte(string.sub(packet.ExtraData, 28, 28))
				packet.Gender = string.byte(string.sub(packet.ExtraData, 29, 29))
				packet.SpriteType = string.byte(string.sub(packet.ExtraData, 30, 30))
				packet.AnimationData = string.byte(string.sub(packet.ExtraData, 31, 31))
				packet.MetaTile = string.byte(string.sub(packet.ExtraData, 32, 32))
				packet.Elevation = string.byte(string.sub(packet.ExtraData, 33, 33))
				packet.LevelCap = string.byte(string.sub(packet.ExtraData, 34, 34))
				packet.PokemonCap = string.byte(string.sub(packet.ExtraData, 35, 35))
				packet.Flags = string.byte(string.sub(packet.ExtraData, 36, 36)) or 0
				--37-43 is filler (movement build: marker, number of steps, the steps)
				packet.Trail, packet.Odo, packet.FxKind = MPMvTrailParse(packet.ExtraData)
				packet.RequestBytes = packet.RequestBytes - 1000
				packet.MapData = {
					["x"] = packet.CurrentX,
					["y"] = packet.CurrentY,
					["dir"] = packet.Direction,
					["id"] = packet.MapID,
					--	["mapdir"] = packet.MapDirection,
					["prev_id"] = packet.PreviousMapID,
					--	["entrance"] = packet.Entrance,
					--	["prev_x"] = packet.PreviousMapX,
					--	["prev_y"] = packet.PreviousMapY,
					["border_x"] = packet.BorderX,
					["border_y"] = packet.BorderY,
					["connection"] = packet.MapConnectionType,
					["elevation"] = packet.Elevation,
					["hidden"] = (packet.Flags & 1) ~= 0,
				}
				packet.PlayerData = {
					["anim"] = packet.Animation,
					["gender"] = packet.Gender,
					["sprite"] = packet.SpriteType,
					["id"] = packet.GameID,
					["anim_data"] = packet.AnimationData,
				}
			end

			packet.PlayerID = packet.PlayerID - 1000
			packet.SendToID = packet.SendToID - 1000
		end
		return packet
	end

	if EnableScript == true then
		local Network_Count = 0
		while NetHasFrame(SocketMain) do
			if NetHoldGroup(SocketMain) then break end
			local ReadData = NetNextFrame(SocketMain)
			if ReadData == nil then
				break
			else
				Network_Count = Network_Count + 1
				local packet = parseReceivedData(ReadData)
				BLogCount(packet.RequestType)
				--Host
				if Hosting then
					if packet.RequestType == "JOIN" then
						if DebugMessages.Unable_To_Connect then console:log("OBTAINED PACKET FROM NEW PLAYER: " .. ReadData) end
						if packet.Validate == "U" then
							if MaxPlayers < 0 or #players < MaxPlayers then
								if DebugMessages.Unable_To_Connect then console:log("ADDING TEMP PLAYER. SENDING DETAILS BACK.") end
								local id = FindFirstFreeID()
								AddPlayer(id, SocketMain, packet.Nickname, packet.GameID, packet.CurrentX, packet.CurrentY, packet.Direction, packet.MapID, packet.Animation, packet.Gender, packet.SpriteType, packet.MapConnectionType, packet.BorderX, packet.BorderY, nil, packet.AnimationData)
								SendData(SocketMain, "NewPlayer", id, PlayerID)
							else
								console:log("A player was unable to join due to capacity limit.")
								SendData(SocketMain, "Refuse", 2)
							end
						else
							if DebugMessages.Unable_To_Connect then console:log("DOES NOT HAVE U AT END. CLOSING CONNECTION...") end
						end
					elseif packet.RequestType == "NICK" then
						if packet.Validate == "U" then
							if DebugMessages.Unable_To_Connect then console:log("RECEIVED NICK FROM CLIENT") end
							local player = FindPlayerByID(packet.PlayerID)
							if player then
								if packet.SendToID ~= PlayerID then
									local target = FindPlayerByID(packet.SendToID)
									if target then
										if DebugMessages.Nickname then console:log("SENDING NICK OF " .. packet.PlayerID .. " TO " .. packet.SendToID) end
										CreateSpecialPacket(target:GetSocket(), "NICK", packet.SendToID, packet.PlayerID)
									end
								else
									player:UpdateNickname(packet.NicknameSpecial)
									if packet.EngineTag then MPEngines[packet.PlayerID] = packet.EngineTag end
									if packet.FmtTag then MPFmts[packet.PlayerID] = packet.FmtTag end
									--Update players to the nickname
									for i, player in ipairs(players) do
										if player:GetID() ~= PlayerID and player:GetSocket() ~= SocketMain then
											CreateSpecialPacket(player:GetSocket(), "NICK", player:GetID(), packet.PlayerID)
											if DebugMessages.Nickname then console:log("SENDING NICK OF " .. packet.PlayerID .. " TO " .. player:GetID()) end
										end
									end
								end
							end
						end
					end
					--Client
				elseif Connected then
					if packet.RequestType == "STRT" then
						if DebugMessages.Unable_To_Connect then console:log("RECEIVED STRT") end
						--Add host
						AddPlayer(1, SocketMain, packet.Nickname, packet.GameID, packet.CurrentX, packet.CurrentY, packet.Direction, packet.MapID, packet.Animation, packet.Gender, packet.SpriteType, packet.MapConnectionType, packet.BorderX, packet.BorderY, nil, packet.AnimationData, packet.MetaTile)
						--Add yourself
						PlayerID = packet.RequestBytes
						AddPlayer(PlayerID, SocketMain, Nickname, GameID, GetPosition())
						ConsoleForText:moveCursor(0,3)
						ConsoleForText:print("You have successfully connected.																																														")
						ConsoleForText:moveCursor(0,4)
						ConsoleForText:print("Connected to a server: Yes				 ")
					end

					if packet.RequestType == "GNIC" then
						if DebugMessages.Unable_To_Connect then console:log("RECEIVED GNIC. SENDING NICK BACK") end
						SendSpecialData(SocketMain, "NICK", packet.PlayerID)
					end

					if packet.RequestType == "NICK" then
						if DebugMessages.Unable_To_Connect then console:log("RECEIVED NICK FROM HOST") end
						local player = FindPlayerByID(packet.PlayerID)
						if player then
							if DebugMessages.Nickname then console:log("UPDATE NAME OF " .. packet.PlayerID) end
							player:UpdateNickname(packet.NicknameSpecial)
							if packet.EngineTag then MPEngines[packet.PlayerID] = packet.EngineTag end
							if packet.FmtTag then MPFmts[packet.PlayerID] = packet.FmtTag end
						end
					end

					if packet.RequestType == "RFSE" then
						MPRefused(packet.RequestBytes)
						if packet.RequestBytes == 1 then
							ConsoleForText:moveCursor(0,3)
							ConsoleForText:print("You could not join this game due to someone else using your nickname.					")
							ConsoleForText:moveCursor(0,4)
							ConsoleForText:print("Connected to a server: No				 ")
						elseif packet.RequestBytes == 2 then
							ConsoleForText:moveCursor(0,3)
							ConsoleForText:print("You could not join this game due to the server player limit.							")
							ConsoleForText:moveCursor(0,4)
							ConsoleForText:print("Connected to a server: No				 ")
						end
					end
					--Both
				end

				if packet.RequestType == "DISC" then
					for i, player in ipairs(players) do
						if player:GetID() ~= PlayerID then
							RemovePlayer(packet.RequestBytes)
						end
					end

					--Add player
				elseif packet.RequestType == "APLA" then
					AddPlayer(packet.RequestBytes, SocketMain, packet.Nickname, packet.GameID, packet.CurrentX, packet.CurrentY, packet.Direction, packet.MapID, packet.Animation, packet.Gender, packet.SpriteType, packet.MapConnectionType, packet.BorderX, packet.BorderY, nil, packet.AnimationData, packet.MetaTile)
					MPOnPlayerAdded(packet.RequestBytes)

					--Remove player
				elseif packet.RequestType == "RPLA" then
					RemovePlayer(packet.RequestBytes)

				elseif packet.RequestType == "SPOS" then
					--Set player position
					local player = FindPlayerByID(packet.RequestBytes)
					if player then
						player:SetMapData(packet.MapData)
						player:SetPlayerData(packet.PlayerData)
						player:SetMetaTile(packet.MetaTile)
						if packet.Trail then player:MvSetTrail(packet.Trail, packet.Odo) end
						player.FxKind = packet.FxKind or 0
						if MPMoveSmoothing then player:MvPush() end
						player:SetBattle(packet.Battle)
						player:SetLevelCap(packet.LevelCap)
						player:SetPokemonCap(packet.PokemonCap)
						player:RefreshTimeout()
						--Send Position to all clients
						if Hosting then
							for i, player in ipairs(players) do
								if player:GetID() ~= PlayerID and player:GetID() ~= packet.RequestBytes then
									if NetForwardRaw then
										NetSend(player:GetSocket(), ReadData)
									else
										SendData(player:GetSocket(), "SPOS", packet.RequestBytes, packet.RequestBytes)
									end
								end
							end
						end
					end
				elseif packet.RequestType == "NPCS" then
					ServerNPCReceive(ReadData)
				elseif packet.RequestType == "NMSG" then
					ServerMsgReceive(ReadData)
				elseif packet.RequestType == "NSCR" then
					ServerScriptReceive(ReadData)
				elseif packet.RequestType == "DEDI" then
					ServerDedicated(packet)
				elseif packet.RequestType == "FRCD" and packet.SendToID == PlayerID then
					MPFriendCodeReceive(packet.PlayerID, ReadData)
				elseif (packet.RequestType == "TRNR" or packet.RequestType == "TRRQ") and packet.SendToID == PlayerID then
					MPCoopReceive(packet.RequestType, packet.PlayerID, ReadData)
				elseif packet.RequestType == "MODE" and packet.SendToID == PlayerID then
					MPModeReceive(packet.PlayerID, ReadData)
				elseif packet.RequestType == "TRWN" and packet.SendToID == PlayerID then
					MPCoopShareReceive(packet.PlayerID, ReadData)
				elseif (packet.RequestType == "TRST" or packet.RequestType == "TREN") and packet.SendToID == PlayerID then
					MPCoopEngageReceive(packet.RequestType, packet.PlayerID, ReadData)
				elseif packet.RequestType == "PRGS" and packet.SendToID == PlayerID then
					MPProgressReceive(packet.PlayerID, ReadData)
				elseif packet.RequestType == "OBJE" and packet.SendToID == PlayerID then
					MPObjReceive(packet.PlayerID, ReadData)
				elseif packet.RequestType == "SBAS" and packet.SendToID == PlayerID then
					MPBaseReceive(packet.PlayerID, ReadData)
				elseif packet.RequestType == "VSTM" and packet.SendToID == PlayerID then
					MPVsTeamReceive(packet.PlayerID, ReadData)
				elseif packet.RequestType == "CDLD" and packet.SendToID == PlayerID then
					MPCDLeadReceive(packet.PlayerID, ReadData)
				elseif packet.RequestType == "SOUL" and packet.SendToID == PlayerID then
					MPSoulReceive(packet.PlayerID, ReadData)
				elseif (packet.RequestType == "FRRQ" or packet.RequestType == "FRRP") and packet.SendToID == PlayerID then
					MPPairPacket(packet.RequestType, packet.PlayerID, ReadData)
				else
					if packet.SendToID ~= PlayerID and Hosting then
						if packet.SendToID and packet.PlayerID and packet.RequestType then
							if DebugMessages.Network then console:log("HOST RECEIVED " .. packet.RequestType .. " FROM " .. packet.PlayerID .. " TO " .. packet.SendToID) end
							local player = FindPlayerByID(packet.PlayerID)
							local player2 = FindPlayerByID(packet.SendToID)
							if player then
								if player2 then
									if DebugMessages.Network then console:log("FORWARD TO PLAYER " .. packet.SendToID) end
									local sockettosend = player2:GetSocket()
									NetSend(sockettosend, ReadData)
								else
									if DebugMessages.Network then console:log("COULD NOT FIND PLAYER. SEND TOO BUSY BACK") end
									SendData(player:GetSocket(), "TBUS", packet.PlayerID)
								end
							end
						end
					elseif packet.SendToID ~= PlayerID then
						if DebugMessages.Network then console:log("CLIENT RECEIVED WRONG REQUEST. SENDING TBUS BACK.") end
						SendData(SocketMain, "TBUS", packet.PlayerID)

					else
						local player = FindPlayerByID(PlayerID)
						local playertalking = FindPlayerByID(player:GetTalking())
						local IsCorrectPlayer = true
						if playertalking then
							if player:GetTalking() ~= packet.PlayerID then
								IsCorrectPlayer = false
							end
						end

						if IsCorrectPlayer then
							if packet.RequestType == "ROFF" then
								if DebugMessages.Network or DebugMessages.Battle or DebugMessages.Trade then console:log("Other player has refused the offer.") end
								if LockFromScript == 5 or LockFromScript == 9 or LockFromScript == 14 or LockFromScript == 20 or LockFromScript == 21 or LockFromScript == 22 then
									OtherPlayerHasCancelled = 3
								end
							end

							if packet.RequestType == "RTRA" then
								if DebugMessages.Network or DebugMessages.Trade then console:log("YOU RECEIVED RTRA FROM " .. packet.PlayerID .. " TO YOU") end
								local TooBusyByte = emu:read8(gAddress[GameID].gLockControls)
								local PartyCount = emu:read8(gAddress[GameID].gPartyCount)
								if (TooBusyByte ~= 0 or LockFromScript ~= 0) then
									if DebugMessages.Network or DebugMessages.Trade then console:log("SEND TOO BUSY") end
									SendData(SocketMain, "TBUS", packet.PlayerID)
								elseif PartyCount < 1 then
									SendData(SocketMain, "NTRA", packet.PlayerID)
								else
									local player = FindPlayerByID(PlayerID)
									player:SetTalking(packet.PlayerID)
									local target = FindPlayerByID(packet.PlayerID)
									--since you are client, set battlemain to other player
									BattleMain = target:GetBattle()
									BattleLevelCap = target:GetLevelCap()
									BattlePokemonCap = target:GetPokemonCap()
									OtherPlayerHasCancelled = 0
									LockFromScript = 14
									Loadscript(6)
								end
							end

							--If the other player cancels trade
							if packet.RequestType == "CTRA" then
								if DebugMessages.Network or DebugMessages.Trade then console:log("Other player has canceled trade.") end
								if LockFromScript == 5 or LockFromScript == 9 or LockFromScript == 14 then
									OtherPlayerHasCancelled = 2
								end
							end

							--If the other player denies trade
							if packet.RequestType == "DTRA" then
								if DebugMessages.Trade then console:log("DENIED TRADE") end
								if LockFromScript == 5 or LockFromScript == 9 or LockFromScript == 14 then
									if Var8000[2] ~= 0 then
										LockFromScript = 0
										Loadscript(7)
									else
										TextSpeedWait = 4
									end
								end
							end

							--If the other player cannot trade due to 0 pokemon
							if packet.RequestType == "NTRA" then
								if LockFromScript == 5 or LockFromScript == 9 or LockFromScript == 14 then
									if Var8000[2] ~= 0 then
										LockFromScript = 0
										Loadscript(31)
									else
										TextSpeedWait = 5
									end
								end
							end

							--If the other player accepts your trade request
							if packet.RequestType == "STRA" and LockFromScript == 5 then
								if DebugMessages.Network or DebugMessages.Trade then console:log("TRADE START NETWORK. SENDING POKEMON") end
								local Target = FindPlayerByID(packet.PlayerID)
								if Target then
									local player = FindPlayerByID(packet.PlayerID)
									GetPokemonTeam(player, 0)
									ClearTrade()
									if Var8000[2] ~= 0 then
										LockFromScript = 9
									else
										TextSpeedWait = 2
									end
								end
							end

							if packet.RequestType == "RBAT" then
								if DebugMessages.Network or DebugMessages.Battle then console:log("YOU RECEIVED RBAT FROM " .. packet.PlayerID .. " TO YOU") end
								local TooBusyByte = emu:read8(gAddress[GameID].gLockControls)
								local PartyCount = emu:read8(gAddress[GameID].gPartyCount)
								if not MPSameEngine(packet.PlayerID) then
									--another battle engine: declined (the asking game does not send it, a game of an older version might)
									local fromP = FindPlayerByID(packet.PlayerID)
									SendData((Hosting and fromP) and fromP:GetSocket() or SocketMain, "DBAT", packet.PlayerID)
								elseif MPVs.req and LockFromScript == 20 and packet.Battle and (packet.Battle & MPVersusFlag) ~= 0 then
									--both walked into a trainer at the same moment and asked each other: "busy" would make both wait for ever.
									--This player declines; the partner does the same with the request it gets: both trainers fight as in the game.
									console:log("Versus: the partner asked at the same time, this request is declined")
									local fromP = FindPlayerByID(packet.PlayerID)
									SendData((Hosting and fromP) and fromP:GetSocket() or SocketMain, "DBAT", packet.PlayerID)
								elseif (TooBusyByte ~= 0 or LockFromScript ~= 0) or (MPVs.watch ~= nil or MPVs.after ~= nil or MPVs.post ~= nil or MPVs.def ~= nil or MPVs.swapped ~= nil or (MPCS and MPCS.cur ~= nil)) then
									--(also busy while the own trainer battle of the game is starting / running: the party must not be swapped in the middle of it)
									if DebugMessages.Network or DebugMessages.Trade then console:log("SEND TOO BUSY") end
									SendData(SocketMain, "TBUS", packet.PlayerID)
								elseif PartyCount < 1 then
									SendData(SocketMain, "NBAT", packet.PlayerID)
								else
									local player = FindPlayerByID(PlayerID)
									player:SetTalking(packet.PlayerID)
									local target = FindPlayerByID(packet.PlayerID)
									--since you are client, set battlemain to other player
									if packet.Battle then target:SetBattle(packet.Battle) end
									BattleMain = target:GetBattle()
									BattleLevelCap = target:GetLevelCap()
									BattlePokemonCap = target:GetPokemonCap()
									OtherPlayerHasCancelled = 0
									--if forced battle, make this player battle, otherwise request
									if (BattleMain & MPVersusFlag) ~= 0 and not MPVsDefend(packet.PlayerID) then
										--Versus: not in Versus mode, not paired or no team of the trainer: no
										LockFromScript = 0
										player:SetTalking(0)
										BattleMain = 0
										SendData(Hosting and target:GetSocket() or SocketMain, "DBAT", target:GetID())
									elseif (BattleMain & BATTLE_FLAGS.FORCE_BATTLE) ~= 0 then
										if OtherPlayerHasCancelled == 0 then
											target:SetBattleID(1) --they are client,
											player:SetBattleID(0) --you are host
											if Hosting then
												if DebugMessages.Battle then console:log("SEND DATA FROM HOST") end
												SendData(target:GetSocket(), "SBAT", target:GetID())
											else
												if DebugMessages.Battle then console:log("SEND DATA FROM CLIENT") end
												--Special Data is structured differently
												SendData(SocketMain, "SBAT", target:GetID())
											end
											ClearBattle()
											LockFromScript = 21
										else
											if DebugMessages.Battle then console:log("Other player cancelled") end
											LockFromScript = 0
											OtherPlayerHasCancelled = 0
											LockFromScript = 0
											Loadscript(18)
										end
									else
										LockFromScript = 22
										Loadscript(10)
									end
								end
							end

							if packet.RequestType == "CBAT" then
								if DebugMessages.Network or DebugMessages.Battle then console:log("Other player has canceled battle.") end
								if LockFromScript == 22 and MPVs.def ~= nil and MPVs.def.opponent == packet.PlayerID and not MPVs.swapped and Var8000[2] == 0 then
									--Versus: the challenger gave up while the question is open: the question is closed with the usual "cancelled" message
									console:log("Versus: the challenger cancelled, the question is closed")
									LockFromScript = 0
									OtherPlayerHasCancelled = 0
									MPVs.def = nil
									BattleMain = 0
									Keypressholding = 1
									Loadscript(18)
								elseif LockFromScript == 20 or LockFromScript == 21 or LockFromScript == 22 then
									OtherPlayerHasCancelled = 1
								end
							end

							--If the other player denies your battle request
							if packet.RequestType == "DBAT" and MPVsDeclined() then
								--Versus: handled, the battle of the game goes on
							elseif packet.RequestType == "DBAT" then
								if DebugMessages.Battle then console:log("DENIED HATTLE") end
								if LockFromScript == 20 or LockFromScript == 21 or LockFromScript == 22 then
									if Var8000[2] ~= 0 then
										LockFromScript = 0
										Loadscript(11)
									else
										TextSpeedWait = 4
									end
								end
							end

							--If the other player cannot battle due to 0 pokemon
							if packet.RequestType == "NBAT" then
								if LockFromScript == 20 or LockFromScript == 21 or LockFromScript == 22 then
									if Var8000[2] ~= 0 then
										LockFromScript = 0
										Loadscript(31)
									else
										TextSpeedWait = 5
									end
								end
							end

							--If the other player accepts your battle request
							if packet.RequestType == "SBAT" and LockFromScript == 20 then
								if DebugMessages.Network or DebugMessages.Battle then console:log("BATTLE START NETWORK. SENDING POKEMON") end
								local Target = FindPlayerByID(packet.PlayerID)
								local player = FindPlayerByID(PlayerID)
								if Target then
									player:SetBattleID(0) --you are host
									Target:SetBattleID(1) --they are client
									if (Battle & BATTLE_FLAGS.FORCE_BATTLE) ~= 0 then
										player:SetBattleID(1) --you are client
										Target:SetBattleID(0) --they are host
									end
									ClearBattle()
									if Var8000[2] ~= 0 then
										LockFromScript = 21
									else
										TextSpeedWait = 2
									end
								end
							end

							if packet.RequestType == "POKE" then
								local Target = FindPlayerByID(packet.PlayerID)
								SetPokemonData(Target, packet.PokeBytes)
							end
							if packet.RequestType == "POK2" then
								local player = FindPlayerByID(PlayerID)
								for i=1, 25 do
									local off = packet.sect * 25 + (i - 1)
									if off < MPMon.Size then
										emu:write8(gAddress[GameID].gEnemyParty + packet.slot * MPMon.Size + off, packet.pkmn[i])
									end
								end
								if packet.slot == 5 and packet.sect == MPMon.BSects - 1 then
									player.BattleVars.Waiting_Status = player.BattleVars.Waiting_Status | 1
									--		console:log("SENT!!! STATUS: " .. player.BattleVars.Waiting_Status)
								end
							end

							if packet.RequestType == "TRAD" then
								local player = FindPlayerByID(packet.PlayerID)
								player:SetTradeVar2(packet.TradeBytes.Text_Stage, packet.TradeBytes.Pokemon_Select, packet.TradeBytes.Trade_Start)
							end

							if packet.RequestType == "BATT" then
								local player = FindPlayerByID(packet.PlayerID)
								player:SetBattleVar(packet.BattleBytes)
							end

							if packet.RequestType == "BAT2" then
								local player = FindPlayerByID(packet.PlayerID)
								player:SetBattleVarBuffer(packet.Transfer_Stage, packet.Buffer_A, packet.Buffer_B)
							end

							if packet.RequestType == "BAT3" then
								local player = FindPlayerByID(packet.PlayerID)
								player:SetBattleVar2(packet.BattleBytes)
							end

							if packet.RequestType == "RCRD" then
								local player = FindPlayerByID(PlayerID)
								if DebugMessages.Network or DebugMessages.Card then console:log("Other player has requested card.") end
								local TooBusyByte = emu:read8(gAddress[GameID].gLockControls)
								if TooBusyByte ~= 0 and (LockFromScript ~= 10 or (LockFromScript == 10 and Var8000[2] == 0)) then
									if DebugMessages.Network or DebugMessages.Card then console:log("SEND TOO BUSY. TBB: " .. TooBusyByte .. " PLAYER: " .. packet.PlayerID) end
									SendData(SocketMain, "TBUS", packet.PlayerID)
								else
									if DebugMessages.Network or DebugMessages.Card then console:log("WORKING ON IT") end
									local gSendBuffer = gAddress[GameID].gSendBuffer
									for i=0, 35 do --clear buffer first.
										emu:write32(gSendBuffer + (4*i), 0)
									end
									--Set 1st pokemon to 62355. When loaded, will be erased with the correct one
									emu:write16(gSendBuffer + 84, 62355)
									if gAddress[GameID].sGameType == "RSE" then
										emu:write16(gSendBuffer, 62355)
									end
									if DebugMessages.Network or DebugMessages.Card then console:log("SETTING PLAYER TARGET") end
									player:SetLoadingCard(true, packet.PlayerID) --Card needs to load first
									if DebugMessages.Network or DebugMessages.Card then console:log("LOADING CARD STUFF INTO MEMORY") end
									Loadscript(24)
								end
							end

							--You are receiving the card data now
							if packet.RequestType == "CARD" then
								if DebugMessages.Network or DebugMessages.Card then console:log("CARD DATA COMING IN.") end
								Target = FindPlayerByID(packet.PlayerID)
								Target:SetCardData(packet.CardBytes)
								Target:SetCardData(packet.CardBytes2)
								Target:SetCardData(packet.CardBytes3)
								Target:SetCardData(packet.CardBytes4)
							end

							--You are done receiving the card
							if packet.RequestType == "DCRD" then
								if DebugMessages.Network or DebugMessages.Card then console:log("Card data is done being received.") end
								if LockFromScript == 10 or LockFromScript == 11 then LockFromScript = 12 end
							end

							--You are done receiving the card, but the other player needs the card as well
							if packet.RequestType == "DCD2" then
								local player = FindPlayerByID(PlayerID)
								if DebugMessages.Network or DebugMessages.Card then console:log("SENDING CARD DATA BACK") end
								local gSendBuffer = gAddress[GameID].gSendBuffer
								for i=0, 35 do --clear buffer first.
									emu:write32(gSendBuffer + (4*i), 0)
								end
								--Set 1st pokemon to 62355. When loaded, will be erased with the correct one
								emu:write16(gSendBuffer + 84, 62355)
								if gAddress[GameID].sGameType == "RSE" then
									emu:write16(gSendBuffer, 62355)
								end
								if DebugMessages.Network or DebugMessages.Card then console:log("SETTING PLAYER TARGET") end
								player:SetLoadingCard(true, packet.PlayerID) --Card needs to load first
								if DebugMessages.Network or DebugMessages.Card then console:log("LOADING CARD STUFF INTO MEMORY") end
								Loadscript(24)
								LockFromScript = 11
							end

							if packet.RequestType == "TBUS" then
								if DebugMessages.Network or DebugMessages.Card then console:log("YOU RECEIVED TBUS FROM " .. packet.PlayerID .. " TO YOU") end
								if LockFromScript == 4 then
									--Cancel Battle
									if Var8000[2] ~= 0 then
										LockFromScript = 0
										Loadscript(20)
									else
										TextSpeedWait = 5
									end
								elseif LockFromScript == 5 then
									--Cancel Trade
									if Var8000[2] ~= 0 then
										LockFromScript = 0
										Loadscript(21)
									else
										TextSpeedWait = 6
									end
								elseif LockFromScript == 10 then
									local Target = FindPlayerByID(packet.PlayerID)
									--If got too busy message while in trainer card, resend request again
									if Hosting then
										SendData(Target:GetSocket(), "RCRD", Target:GetID())
									else
										SendData(SocketMain, "RCRD", Target:GetID())
									end
								elseif LockFromScript == 20 and MPVsBusy() then
									--Versus: asked again later
								elseif LockFromScript == 20 then
									--Cancel Trade
									if Var8000[2] ~= 0 then
										LockFromScript = 0
										Loadscript(20)
									else
										TextSpeedWait = 6
									end
								end
							end
						else
							if DebugMessages.Network then console:log("ANOTHER PLAYER IS TRYING TO ASK STUFF WHILE YOU ARE BUSY") end
							SendData(SocketMain, "TBUS", packet.PlayerID)
						end
					end
				end
			end
		end

		if DebugMessages.Network_Count then console:log("Network interactions this frame: " .. Network_Count) end
	end
end

--Send Data to clients
function CreatePacket(RequestTemp, PacketTemp, DataToUse, SendToID)
	local FillerStuff = "FFFFFFF"
	if RequestTemp == "SPOS" and DataToUse == PlayerID and MPMvTrailBytes then FillerStuff = MPMvTrailBytes() end
	local PacketMap = {}
	local PacketPlayer = {}
	local PacketPlayerID, PacketGameID = 0, 0
	player = FindPlayerByID(DataToUse)
	PacketSendToID = SendToID or PacketTemp
	if #players > 0 and player then
		local temp1, temp2, temp3, temp4, temp5
		PacketMap = player:GetMapData() or {}
		PacketPlayer = player:GetPlayerData() or {}
		PacketPlayerID = player:GetID()
		PacketGameID = player:GetGameID()
	else
		local CurrentX, CurrentY, Direction, MapID, Animation, Gender, SpriteType, EntranceType, BorderX, BorderY, Connections, AnimationData, Metatile = GetPosition()
		PacketMap = {
			["x"] = CurrentX,
			["y"] = CurrentY,
			["dir"] = Direction,
			["id"] = MapID,
			["mapdir"] = Direction,
			["prev_id"] = MapID,
			["entrance"] = EntranceType,
			["prev_x"] = CurrentX,
			["prev_y"] = CurrentY,
			["border_x"] = BorderX,
			["border_y"] = BorderY,
			["connection"] = Connections,
			["metatile"] = Metatile,
			["elevation"] = PositionData.Elevation,
			["hidden"] = PositionData.Hidden,
		}
		PacketPlayer = {
			["anim"] = Animation,
			["gender"] = Gender,
			["sprite"] = SpriteType,
			["id"] = GameID,
			["anim_data"] = AnimationData,
		}
		PacketPlayerID = PlayerID
		PacketGameID = GameID
	end
	local function Cap(value, length)
		return string.sub(tostring(value), 1, math.max(1, length))
	end

	local Packets = {}
	--4 bytes
	Packets["battle"] = safeStringChar(Battle & 0xFF) .. safeStringChar((Battle >> 8) & 0xFF) .. safeStringChar((Battle >> 16) & 0xFF) .. safeStringChar((Battle >> 24) & 0xFF)
	--1 byte
	Packets["direction"] = safeStringChar(PacketMap.dir)
	--2 bytes
	Packets["mapid"] = safeStringChar(PacketMap.id & 0xFF) .. safeStringChar((PacketMap.id >> 8) & 0xFF)
	--2 bytes
	Packets["prev_mapid"] = safeStringChar(PacketMap.prev_id & 0xFF) .. safeStringChar((PacketMap.prev_id >> 8) & 0xFF)
	--4 bytes
	Packets["pos"] = safeStringChar(PacketMap.x & 0xFF) .. safeStringChar((PacketMap.x >> 8) & 0xFF) .. safeStringChar(PacketMap.y & 0xFF) .. safeStringChar((PacketMap.y >> 8) & 0xFF)
	--4 bytes
	Packets["prev_pos"] = safeStringChar(PacketMap.prev_x & 0xFF) .. safeStringChar((PacketMap.prev_x >> 8) & 0xFF) .. safeStringChar(PacketMap.prev_y & 0xFF) .. safeStringChar((PacketMap.prev_y >> 8) & 0xFF)
	--4 bytes
	Packets["border_pos"] = safeStringChar(PacketMap.border_x & 0xFF) .. safeStringChar((PacketMap.border_x >> 8) & 0xFF) .. safeStringChar(PacketMap.border_y & 0xFF) .. safeStringChar((PacketMap.border_y >> 8) & 0xFF)
	--1 byte
	Packets["connection"] = safeStringChar(PacketMap.connection)
	--1 byte
	Packets["entrance"] = safeStringChar(PacketMap.entrance)
	--1 byte
	Packets["animation"] = safeStringChar(PacketPlayer.anim)
	--1 byte
	Packets["gender"] = safeStringChar(PacketPlayer.gender)
	--1 byte
	Packets["sprite"] = safeStringChar(PacketPlayer.sprite)
	--1 byte
	Packets["animation_data"] = safeStringChar(PacketPlayer.anim_data)
	--1 byte
	Packets["metatile"] = safeStringChar(PacketMap.metatile)
	--1 byte
	Packets["elevation"] = safeStringChar(PacketMap.elevation)
	--1 byte
	Packets["level_cap"] = safeStringChar(Level_Cap)
	--1 byte
	Packets["pokemon_cap"] = safeStringChar(Pokemon_Cap)
	--1 byte
	Packets["flags"] = safeStringChar(PacketMap.hidden and 1 or 0)
	PacketNickname = "FFFF"
	PacketPlayerID = Cap(PacketPlayerID + 1000, 4)
	PacketSendToID = Cap(PacketSendToID + 1000, 4)
	PacketTemp = Cap(PacketTemp + 1000, 4)
	Packet = PacketGameID .. PacketNickname .. PacketPlayerID .. PacketSendToID .. RequestTemp .. PacketTemp
	Packet = Packet .. Packets["battle"] .. Packets["direction"] .. Packets["mapid"] .. Packets["prev_mapid"] .. Packets["pos"] .. Packets["prev_pos"] .. Packets["border_pos"] .. Packets["connection"] .. Packets["entrance"] .. Packets["animation"] .. Packets["gender"] .. Packets["sprite"] .. Packets["animation_data"] .. Packets["metatile"] .. Packets["elevation"] .. Packets["level_cap"] .. Packets["pokemon_cap"] .. Packets["flags"]
	Packet = Packet .. FillerStuff .. "U"
	if #Packet ~= 64 then
		console:log("PACKET NOT CORRECT SIZE! SIZE: " .. #Packet .. ". SETTING FILLER PACKET")
		Packet = "FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFU"
	end
	if DebugMessages.Network then console:log("SEND PACKET " .. Packet) end
end

function CreateSpecialPacket(Socket, RequestTemp, PacketTemp, DataToUse, Optional)
	local Target, player, PacketPlayerID, PacketNickname, PacketGameID, PacketSendToID
	local NicknameSpecial
	Target = FindPlayerByID(PacketTemp)
	player = FindPlayerByID(DataToUse)
	PacketSendToID = PacketTemp
	if player then
		PacketPlayerID = player:GetID()
		PacketGameID = player:GetGameID()
		NicknameSpecial = player:GetNickname()
	else
		PacketPlayerID = PlayerID
		PacketGameID = GameID
	end
	PacketNickname = "FFFF"
	PacketPlayerID = PacketPlayerID + 1000
	PacketSendToID = PacketSendToID + 1000
	PacketTemp = PacketTemp + 1000
	if RequestTemp == "POKE" then
		local PokeTemp
		local StartNum = 0
		local StartNum2 = 0
		local Filler = "FFFFFFFFFFFFFFFFFF"
		local Filler2 = "1000000000000000000000000"
		for j = 1, 6 do
			for i = 1, MPMon.Sects do
				StartNum = ((i - 1) * 25) + 1
				StartNum2 = StartNum + 24
				PokeTemp = string.sub(player:GetPokemonRaw(j),StartNum,StartNum2)
				if #PokeTemp < 25 and type(player:GetPokemonRaw(j)) == "string" and #player:GetPokemonRaw(j) >= MPMon.Chars then
					PokeTemp = PokeTemp .. string.rep("0", 25 - #PokeTemp)       --the last part of a layout of 108 bytes
				end
				Packet = PacketGameID .. PacketNickname .. PacketPlayerID .. PacketSendToID .. RequestTemp .. PokeTemp .. Filler .. "U"
				if #Packet == 64 then
					NetSend(Socket, Packet)
				else
					console:log("PACKET NOT CORRECT SIZE!!! SIZE: " .. #Packet .. ". SENDING FILLER PACKET. MAY CORRUPT POKEMON.")
					Packet = PacketGameID .. PacketNickname .. PacketPlayerID .. PacketSendToID .. RequestTemp .. Filler2 .. Filler .. "U"
					NetSend(Socket, Packet)
				end
			end
		end
	elseif RequestTemp == "POK2" then
		local StartAdr = gAddress[GameID].gParty
		local Filler = "FFFFFFFFFFFFFFFF"
		local Filler2 = "FFFFFFFFFFFFFFFFFFFFFFFFFFF"
		local PacketPKMN = 0 --which pokemon. can be 0-5
		local PacketPKMNLOC = 0 --which section. can be 0-3
		for j = 1, 6 do
			for l = 1, MPMon.BSects do
				Packet = PacketGameID .. PacketNickname .. PacketPlayerID .. PacketSendToID .. RequestTemp
				for i = 1, 25 do
					local off = (l - 1) * 25 + (i - 1)
					local pkmn = safeStringChar(off < MPMon.Size and emu:read8(StartAdr + (j - 1) * MPMon.Size + off) or 0)
					Packet = Packet .. pkmn
				end
				PacketPKMN = safeStringChar(j - 1)
				PacketPKMNLOC = safeStringChar(l - 1)
				Packet = Packet .. Filler .. PacketPKMN .. PacketPKMNLOC .. "U"
				if #Packet == 64 then
					--	console:log("POK2 SENT!")
					NetSend(Socket, Packet)
				else
					--	console:log("PACKET NOT CORRECT SIZE!!! SIZE: " .. #Packet .. ". SENDING FILLER PACKET. MAY CORRUPT POKEMON.")
					Packet = PacketGameID .. PacketNickname .. PacketPlayerID .. PacketSendToID .. RequestTemp .. Filler2 .. Filler .. "U"
					NetSend(Socket, Packet)
				end
			end
		end

	elseif RequestTemp == "TRAD" then
		local playerTrade = player:GetTradeVar()
		local PacketTextStage = playerTrade.Text_Stage + 1000
		local PacketPokemonSelect = playerTrade.Pokemon_Select + 1000
		local PacketTradeStart = playerTrade.Trade_Start + 1000
		local Filler = "FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF"
		Packet = PacketGameID .. PacketNickname .. PacketPlayerID .. PacketSendToID .. RequestTemp .. PacketTextStage .. PacketPokemonSelect .. PacketTradeStart .. Filler .. "U"
		--4 + 4 + 4 + 4 + 4 + 4 + 4 + 4 + 31 + 1
		NetSend(Socket, Packet)

	elseif RequestTemp == "NICK" then
		--the nickname field is exactly 43 bytes: 10 characters at most, filled up with ~
		local PacketSpecialNickname
		local NickToSend = NicknameSpecial or ""
		if utf8_length(NickToSend) > 10 then NickToSend = utf8_cut(NickToSend, 10) end
		if string.len(NickToSend) > 43 then NickToSend = string.sub(NickToSend, 1, 43) end
		local eng = ((player and player:GetID() ~= PlayerID) and MPEngines[player:GetID()]) or ((not player or player:GetID() == PlayerID) and MPEngine) or "00000000"
		local fmt = ((player and player:GetID() ~= PlayerID) and MPFmts[player:GetID()]) or ((not player or player:GetID() == PlayerID) and MPFmt) or "S100"
		if string.len(NickToSend) > 29 then NickToSend = string.sub(NickToSend, 1, 29) end
		PacketSpecialNickname = NickToSend .. string.rep("~", 29 - string.len(NickToSend)) .. "#" .. eng .. "$" .. fmt
		Packet = PacketGameID .. PacketNickname .. PacketPlayerID .. PacketSendToID .. RequestTemp .. PacketSpecialNickname .. "U"
		if DebugMessages.Nickname then console:log("NICKNAME: " .. Packet) end
		NetSend(Socket, Packet)

	elseif RequestTemp == "CARD" then
		local gSendBuffer = gAddress[GameID].gSendBuffer
		local Filler = "FFF"
		if DebugMessages.Network or DebugMessages.Card then console:log("SEND SPECIAL DATA CARD START") end
		for i = 0, 8 do
			local CardData = emu:read32(gSendBuffer + (i*16))
			CardData = CardData + 1000000000
			for j = 1, 3 do
				local CardDataTemp = emu:read32(gSendBuffer + (i*16) + (j*4))
				CardDataTemp = CardDataTemp + 1000000000
				CardData = CardData .. CardDataTemp
			end
			Packet = PacketGameID .. PacketNickname .. PacketPlayerID .. PacketSendToID .. RequestTemp .. CardData .. Filler .. "U"
			--4 + 4 + 4 + 4 + 4 + 40 + 3 + 1
			NetSend(Socket, Packet)
			if DebugMessages.Network or DebugMessages.Card then console:log("SEND PACKET " .. Packet) end
		end
		if DebugMessages.Network or DebugMessages.Card then console:log("SENT SPECIAL DATA CARD DONE") end

	elseif RequestTemp == "BATT" then
		player:ReadBattleVar()
		local playerBattle = player:GetBattleVar()
		local PacketTextStage = safeStringChar(playerBattle.Text_Stage)
		local PacketWaitingStatus = safeStringChar(playerBattle.Waiting_Status)
		local PacketBattle_Start = safeStringChar(playerBattle.Battle_Start)
		local PacketBuffer_ID = safeStringChar(playerBattle.Buffer_ID)
		local PacketAttacker = safeStringChar(playerBattle.Attacker)
		local PacketTarget = safeStringChar(playerBattle.Target)
		local PacketAbsent_Battler = safeStringChar(playerBattle.Absent_Battler)
		local PacketEffect_Battler = safeStringChar(playerBattle.Effect_Battler)
		local PacketSend_ID = safeStringChar(playerBattle.Send_ID)
		local PacketBufferA = {}
		local PacketBattleFlags = {}
		player.BattleVars.Transfer_Stage = 0
		for i=1, 30 do
			PacketBufferA[i] = safeStringChar(playerBattle.Buffer_A[i])
		end
		for i=1, 4 do
			PacketBattleFlags[i] = safeStringChar(playerBattle.Battleflags[i])
		end
		local Filler = "FFFF"
		Packet = PacketGameID .. PacketNickname .. PacketPlayerID .. PacketSendToID .. RequestTemp
		Packet = Packet .. PacketTextStage .. PacketWaitingStatus .. PacketBattle_Start .. PacketBuffer_ID .. PacketAttacker .. PacketTarget .. PacketAbsent_Battler .. PacketEffect_Battler
		for i=1, 30 do
			Packet = Packet .. PacketBufferA[i]
		end
		for i=1, 4 do
			Packet = Packet .. PacketBattleFlags[i]
		end
		Packet = Packet .. PacketSend_ID .. "U"
		NetSend(Socket, Packet)

	elseif RequestTemp == "BAT2" then
		local playerBattle = player:GetBattleVar()
		local PacketBufferA = {}
		local PacketBufferB = {}
		player.BattleVars.Transfer_Stage = player.BattleVars.Transfer_Stage + 1
		local bufferaloc = 30 + 20*(player.BattleVars.Transfer_Stage - 1)
		local bufferbloc = 20*(player.BattleVars.Transfer_Stage - 1)
		for i=1, 20 do
			PacketBufferA[i] = safeStringChar(playerBattle.Buffer_A[i+bufferaloc])
		end
		for i=1, 20 do
			PacketBufferB[i] = safeStringChar(playerBattle.Buffer_B[i+bufferbloc])
		end
		local Filler = "FFF"
		--	console:log("PACKET BAT2: " .. Packet)
		Packet = PacketGameID .. PacketNickname .. PacketPlayerID .. PacketSendToID .. RequestTemp
		for i = 1, 20 do
			Packet = Packet .. PacketBufferA[i]
		end
		for i = 1, 20 do
			Packet = Packet .. PacketBufferB[i]
		end
		Packet = Packet .. Filler .. "U"
		NetSend(Socket, Packet)


		--Initial battle parameters
	elseif RequestTemp == "BAT3" then
		local playerBattle = player:GetBattleVar2()
		local packettable = {}
		packettable[1] = safeStringChar(playerBattle.Link_Battle_Header_versionLo)
		packettable[2] = safeStringChar(playerBattle.Link_Battle_Header_versionHi)
		packettable[3] = safeStringChar(playerBattle.Link_Battle_Header_vsLo)
		packettable[4] = safeStringChar(playerBattle.Link_Battle_Header_vsHi)
		packettable[5] = {}
		for i = 1, 27 do
			packettable[5][i] = safeStringChar(playerBattle.Link_Battle_Header_Itemdata[i])
		end
		local Filler = "FFFFFFFFFFFF"
		Packet = PacketGameID .. PacketNickname .. PacketPlayerID .. PacketSendToID .. RequestTemp .. packettable[1] .. packettable[2] .. packettable[3] .. packettable[4]
		for i = 1, 27 do
			Packet = Packet .. packettable[5][i]
		end
		Packet = Packet .. Filler .. "U"
		NetSend(Socket, Packet)


	elseif RequestTemp == "NRES" then
		--the answer of a script of the dedicated server: request id u8, status u8 (0 done, 1 refused, 2 not answered), then VAR_ANSWER,
		--VAR_CHOICE and VAR_RESULT as u16
		local r = Optional or {}
		local function u16(v) v = v or 0 return string.char(v & 0xFF, (v >> 8) & 0xFF) end
		local body = string.char((r.id or 0) & 0xFF, (r.status or 0) & 0xFF) .. u16(r.answer) .. u16(r.choice) .. u16(r.result)
		Packet = PacketGameID .. PacketNickname .. PacketPlayerID .. PacketSendToID .. RequestTemp .. body .. string.rep("F", 43 - #body) .. "U"
		NetSend(Socket, Packet)

	elseif RequestTemp == "NTLK" then
		--the player talks to an NPC of the dedicated server: NPC id (2 bytes) and filler
		local NpcId = Optional or 0
		Packet = PacketGameID .. PacketNickname .. PacketPlayerID .. PacketSendToID .. RequestTemp .. string.char(NpcId & 0xFF, (NpcId >> 8) & 0xFF) .. string.rep("F", 41) .. "U"
		NetSend(Socket, Packet)

	elseif RequestTemp == "SLNK" then
		PlayerReceiveID = PlayerTalkingID2
		OptionalData = OptionalData or 0
		local Filler = "100000000000000000000000000000000"
		local SizeAct = OptionalData + 1000000000
		Packet = GameID .. Nickname .. PlayerID2 .. PlayerReceiveID .. RequestTemp .. SizeAct .. Filler .. "U"
	end
end

function SendData(Socket, DataType, ExtraData, DataToUse)
	local ExtraData = ExtraData or 0
	local DataToUse = DataToUse or PlayerID
	--If you have made a server
	if (DataType == "NewPlayer") then
		CreatePacket("STRT", ExtraData, DataToUse)
		NetSend(Socket, Packet)
		CreateSpecialPacket(Socket, "NICK", ExtraData, DataToUse)
		NetSend(Socket, Packet)
		CreatePacket("GNIC", ExtraData, DataToUse)
		NetSend(Socket, Packet)
		if DebugMessages.Unable_To_Connect then console:log("SENT TO PLAYER STRT, NICK, AND GNIC") end
		--Update new player on current players
		for i, player in ipairs(players) do
			if player:GetID() ~= PlayerID and player:GetSocket() ~= Socket then
				CreatePacket("APLA", player:GetID(), player:GetID())
				--	console:log("SENDING APLA OF " .. player:GetID() .. " TO " .. ExtraData)
				NetSend(Socket, Packet)
				CreateSpecialPacket(Socket, "GNIC", ExtraData, player:GetID())
				CreateSpecialPacket(Socket, "NICK", ExtraData, player:GetID())
			end
		end
		--Update current players on new player
		for i, player in ipairs(players) do
			local PlayerSocket = player:GetSocket()
			if player:GetID() ~= PlayerID and player:GetSocket() ~= Socket then
				CreatePacket("APLA", ExtraData, ExtraData)
				--	console:log("SENDING APLA OF " .. ExtraData .. " TO " .. player:GetID())
				NetSend(PlayerSocket, Packet)
			end
		end
	elseif (DataType == "Request") then
		--console:log("REQUEST!!")
		CreatePacket("JOIN", ExtraData, DataToUse)
		if DebugMessages.Unable_To_Connect then console:log("SENDING TO HOST PACKET: " .. Packet) end
		NetSend(Socket, Packet)
	elseif (DataType == "Refuse") then
		CreatePacket("RFSE", ExtraData, DataToUse)
		NetSend(Socket, Packet)
	elseif (DataType == "GPOS") then
		CreatePacket("GPOS", ExtraData, DataToUse)
		NetSend(Socket, Packet)
	else
		CreatePacket(DataType, ExtraData, DataToUse)
		NetSend(Socket, Packet)
	end
end

function SendSpecialData(Socket, DataType, ExtraData, DataToUse, Optional)
	local ExtraData = ExtraData or 0
	local DataToUse = DataToUse or PlayerID
	if DebugMessages.Network then console:log("SENDING SPECIAL DATA. SEND ID: " .. ExtraData .. " SENT FROM: " .. DataToUse) end
	CreateSpecialPacket(Socket, DataType, ExtraData, DataToUse, Optional)
end

function RandomizeNickname()
	local res = ""
	for i = 1, 4 do
		res = res .. string.char(math.random(97, 122))
	end
	return res
end

function GetInGameName()
	local save_loc = 0
	local name = ""
	local letter = 0
	local length = 0
	for i=0, 7 do
		if gAddress[GameID].sGameVersion ~= "RS" then
			save_loc = emu:read32(gAddress[GameID].gSaveBlock2Ptr)
		else
			save_loc = gAddress[GameID].gSaveBlock2Ptr --save pointer, RS is already pointed
		end
		letter = findKeyByValue(LanguageTable[LanguageTableType], emu:read8(save_loc+i))
		if letter then
			name = name .. letter
			length = length + 1
		end
	end
	if length == 0 then
		name = RandomizeNickname()
		console:log("No name found. Generating one...")
	end
	return name
end

