					end

					--Fix previous multi choice
					if PrevExtraAdr ~= 0 then
						ROMCARD:write32(gAddress[GameID].gMultiChoice, PrevExtraAdr)
						ROMCARD:write8(gAddress[GameID].gMultiChoiceAmount, PrevExtraAdrNum)
