function GetNicknameBuffer(id, opt_nick)
	-- Convert 4-byte buffer to readable bytes
	local player
	if id ~= 9999 then player = FindPlayerByID(id) end
	local Buffer = {0, 0, 0, 0, 255}
	local LanguageTableTemp = 0
	local LanguageOffsets = {}
	local offset = 1
	local maxnickname = 10
	local Nickname
	if player then
		Nickname = player:GetNickname()
	else
		Nickname = opt_nick
	end

	if not Nickname then return Buffer end

	local i = 1
	for _, char in utf8.codes(Nickname) do
		table.insert(LanguageOffsets, i)
		i = i + 1
	end
	for i = 1, #LanguageOffsets do
		local NickNameNum = utf8sub(Nickname, LanguageOffsets[i], LanguageOffsets[i])
		if NickNameNum then
			--	console:log("NICK: " .. NickNameNum .. " TABLE: " .. LanguageTableType)
			if LanguageTableType == "Western" and is_japanese_char(NickNameNum) then
				LanguageTableTemp = LanguageTable["JapaneseWestern"][NickNameNum]
				if LanguageTableTemp then
					for j=1, string.len(LanguageTableTemp) do
						local LanguageTableTemp2 = LanguageTable["Western"][string.sub(LanguageTableTemp,j,j)]
						if not LanguageTableTemp2 then LanguageTableTemp2 = 0 end
						Buffer[offset] = LanguageTableTemp2
						offset = offset + 1
						if offset > maxnickname then Buffer[offset] = 255 return Buffer end
					end
				end
			else
				LanguageTableTemp = LanguageTable[LanguageTableType][NickNameNum]
				if not LanguageTableTemp then LanguageTableTemp = LanguageTable["Western"][NickNameNum] end
				if not LanguageTableTemp then LanguageTableTemp = 0 end
				Buffer[offset] = LanguageTableTemp
				offset = offset + 1
				if offset > maxnickname then Buffer[offset] = 255 return Buffer end
			end
		end
		Buffer[offset] = 255
	end
	return Buffer
end

function writeToMemory(addr, buffer)
	for i = 1, #buffer do
		emu:write8(addr, buffer[i])
		addr = addr + 1
	end
end

function WriteToRom(addr, data)
	for i = 1, #data do
		ROMCARD:write8(addr, data[i])
		addr = addr + 1
	end
end

--Escape sequence for string text
function EscapeSequences(str)
	str = str:gsub("\\l", "\a")
	str = str:gsub("\\p", "\b")
	str = str:gsub("\\c", "\f")
	str = str:gsub("\\v", "\r")
	str = str:gsub("\\n", "\n")
	str = str:gsub("\\h", "\t")
	return str
end


-- ===========================================================================================================================
-- SCRIPT COMPILER
-- Scripts of the mod are written in the game's own script language (the command names of pokeemerald / pokefirered) and
-- compiled to the number words the game runs when the mod loads them. The numbering of the commands is the same in
-- FireRed / LeafGreen and in Ruby / Sapphire / Emerald, so one source serves every game.
--
-- One command per line, operands separated by commas. Everything after "--" or ";" is a comment. "name:" starts a label.
-- Operands are numbers (0x.. or decimal), the names of MPScriptNames, labels, or addresses of the game from gAddress
-- (`callnative InitLocalLinkPlayer + 1`). TEXT is the place where the text of the script's message box is written,
-- SPECIAL_LINK_START the special that starts a link battle / trade (it is another one in Emerald).
-- A new command is added by one line in MPScriptCommands: name = {opcode, size of operand 1, size of operand 2, ...}.
-- ===========================================================================================================================
MPScriptCommands = {
	nop = {0x00}, ["end"] = {0x02},
	goto_if = {0x06, 1, 4},                 --goto_if CONDITION, label
	callstd = {0x09, 1},                    --callstd MSGBOX_YESNO
	loadword = {0x0F, 1, 4},                --loadword 0, TEXT   (the text of msgbox / callstd)
	setvar = {0x16, 2, 2}, addvar = {0x17, 2, 2}, copyvar = {0x19, 2, 2},
	compare = {0x21, 2, 2},                 --compare VAR_RESULT, 1  (compare_var_to_value)
	callnative = {0x23, 4},                 --run machine code at an address (+1 = thumb)
	special = {0x25, 2}, specialvar = {0x26, 2, 2}, waitstate = {0x27},
	delay = {0x28, 2},
	dotrainerbattle = {0x5D},
	waitmessage = {0x66}, message = {0x67, 4}, closemessage = {0x68},
	lockall = {0x69}, lock = {0x6A}, releaseall = {0x6B}, release = {0x6C},
	multichoice = {0x6F, 1, 1, 1, 1},      --multichoice left, top, list, cancelable
	multichoicegrid = {0x71, 1, 1, 1, 1, 1},  --multichoicegrid left, top, list, per row, cancelable
	bufferspeciesname = {0x7D, 1, 2},
	messageautoscroll = {0x9B, 4},
	--pseudo commands: `pad [command]`  the first byte of a script is skipped by the loader, so it is a dummy (default: lock)
	--                 `byte N, N...`   raw bytes (filler that keeps a label or the length where it was)
}

MPScriptNames = {
	LT = 0, EQ = 1, GT = 2, LE = 3, GE = 4, NE = 5,                                 --conditions of goto_if
	MSGBOX_NPC = 2, MSGBOX_SIGN = 3, MSGBOX_DEFAULT = 4, MSGBOX_YESNO = 5, MSGBOX_AUTOCLOSE = 6,   --callstd
	VAR_RESULT = 0x800D, VAR_FACING = 0x800C, VAR_ITEM_ID = 0x800E, VAR_LAST_TALKED = 0x800F,
	VAR_CHOICE = 0x8000, VAR_ANSWER = 0x8001, VAR_SELECTED = 0x8004, VAR_SPECIES = 0x8003,     --used by the scripts of the mod
}
for i = 0, 11 do MPScriptNames[string.format("VAR_0x%04X", 0x8000 + i)] = 0x8000 + i end

--translates the source of a script to bytes. env = {base = address of the script area, text = TEXT, A = addresses of the game}
function MPScriptAssemble(code, env)
	local items, labels, pos = {}, {}, 0
	for rawLine in string.gmatch(code .. "\n", "([^\n]*)\n") do
		local line = rawLine
		line = string.gsub(string.gsub(line, "%-%-.*$", ""), ";.*$", "")
		line = string.match(line, "^%s*(.-)%s*$")
		if line ~= "" then
			local label = string.match(line, "^([%w_]+):$")
			if label then
				labels[label] = pos
			else
				local name, rest = string.match(line, "^([%w_]+)%s*(.*)$")
				local ops = {}
				for tok in string.gmatch(rest, "[^,]+") do ops[#ops + 1] = string.match(tok, "^%s*(.-)%s*$") end
				local size
				if name == "pad" then
					size = 1
				elseif name == "byte" then
					size = #ops
				else
					local def = MPScriptCommands[name]
					if not def then error("script: unknown command '" .. name .. "' in: " .. line) end
					size = 1
					for i = 2, #def do size = size + def[i] end
					if #ops ~= #def - 1 then error("script: '" .. name .. "' needs " .. (#def - 1) .. " operand(s): " .. line) end
					size = size + (MPScriptExtra[name] or 0)          --a hack whose command takes more operand bytes (profile: cmdextra)
				end
				items[#items + 1] = {name = name, ops = ops, size = size}
				pos = pos + size
			end
		end
	end
	local function value(tok)
		local n = tonumber(tok)
		if n then return n end
		local sym, sign, num = string.match(tok, "^([%w_]+)%s*([%+%-]?)%s*(%w*)$")
		if not sym then error("script: bad operand '" .. tok .. "'") end
		local v
		if sym == "TEXT" then v = env.text
		elseif labels[sym] then v = env.base + labels[sym]
		elseif env.names and env.names[sym] then v = env.names[sym]
		elseif MPScriptNames[sym] then v = MPScriptNames[sym]
		elseif env.A and env.A[sym] then v = env.A[sym]
		else error("script: unknown name '" .. sym .. "'") end
		if sign ~= "" then
			local d = tonumber(num)
			v = (sign == "-") and (v - d) or (v + d)
		end
		return v
	end
	local bytes = {}
	for _, it in ipairs(items) do
		if it.name == "pad" then
			local def = it.ops[1] and MPScriptCommands[it.ops[1]]
			bytes[#bytes + 1] = def and def[1] or 0x6A
		elseif it.name == "byte" then
			for _, op in ipairs(it.ops) do bytes[#bytes + 1] = value(op) & 0xFF end
		else
			local def = MPScriptCommands[it.name]
			bytes[#bytes + 1] = def[1]
			for i = 2, #def do
				local v = value(it.ops[i - 1])
				--a hack that added or removed specials has the functions of the game at other numbers (profile: specials)
				if ((it.name == "special" and i == 2) or (it.name == "specialvar" and i == 3)) and MPSpecialMap and MPSpecialMap[v] then
					v = MPSpecialMap[v]
				end
				for b = 0, def[i] - 1 do bytes[#bytes + 1] = (v >> (8 * b)) & 0xFF end
			end
			for _ = 1, (MPScriptExtra[it.name] or 0) do bytes[#bytes + 1] = 0 end
		end
	end
	return bytes
end

--bytes -> number words (little endian, the last word is filled with 0xFF)
function MPScriptWords(bytes)
	local words = {}
	for i = 1, #bytes, 4 do
		words[#words + 1] = (bytes[i] or 0xFF) | ((bytes[i + 1] or 0xFF) << 8) | ((bytes[i + 2] or 0xFF) << 16) | ((bytes[i + 3] or 0xFF) << 24)
	end
	return words
end

-- ===========================================================================================================================
-- A script in the source is   MPScript(id, "name", {fields})   with these fields
--   code      the commands (see above). The first byte of a script is skipped by the loader: start with `pad`
--   native    the script starts with machine code (list of words, or a function(A) returning it); `code` has no `pad` then
--   text      text of the message box: one string, or {en = "...", de = "...", jp = "..."} ("en" is the fallback)
--   set       variables set before the script runs: {[0x8001] = 0, [0x8005] = 3}. 0 clears, 0x8001..0x8013 copies that variable
--   buffer1 / buffer2 / buffer3   "nickname": the name of the player that is talked to is put into \v\h01 / \h02 / \h03
--   choices   the list of the interaction menu {en = {"Battle", "Trade", ...}, de = {...}}, 15 bytes of text each
-- ===========================================================================================================================
MPScriptSource = {}
function MPScript(id, name, def)
	def.Name = name
	MPScriptSource[id] = def
end

--the same table the loader has always used ({Name, flags, scriptData, textData, ...}) for one script
function MPScriptBuild(id, A, nickname)
	local def = MPScriptSource[id]
	if not def then return nil end
	local base = A.gScriptData
	local startLink = 0x8E            --the special that starts the link battle / trade (Emerald, but not the Japanese one: 0x91)
	if A.sGameVersion == "E" and GameID ~= "BPEJ" then startLink = 0x91 end
	local env = {base = base, text = base + 0x90, A = A, names = {SPECIAL_LINK_START = startLink}}
	local s = {Name = def.Name, flags = {}}
	for var, setValue in pairs(def.set or {}) do
		local v = setValue
		if type(v) == "table" then v = 8000 + (v.var - 0x8000 + 1) end      --{var = 0x8004}: the value that variable has now
		s.flags[var - 0x8000 + 1] = v
	end
	if def.code then s.scriptData = MPScriptWords(MPScriptAssemble(def.code, env)) end
	if def.text then
		local t = def.text
		if type(t) == "function" then t = t() end
		if type(t) == "string" then t = {en = t} end
		s.textData = {}
		for lang, str in pairs(t) do s.textData[lang] = {[env.text - MPMem.ROM] = str} end
	end
	if def.native then
		local n = def.native
		if type(n) == "function" then n = n(A) end
		s.scriptASM = {ALL = n}
	end
	if def.buffer1 then s.buffer1Data = nickname end
	if def.buffer2 then s.buffer2Data = nickname end
	if def.buffer3 then s.buffer3Data = nickname end
	if def.choices then
		local opts, text = {}, {}
		local first = def.choices.en
		for i = 1, #first do
			opts[#opts + 1] = A.gTextData + 15 * (i - 1)
			opts[#opts + 1] = 0
		end
		for lang, list in pairs(def.choices) do
			text[lang] = {}
			for i, label in ipairs(list) do text[lang][A.gTextData + 15 * (i - 1)] = label end
		end
		s.multichoiceData = {oldmultichoiceaddr = A.gMultiChoice, newmultichoiceaddr = A.gMultiChoiceData,
			multichoiceoptions = opts, textData = text}
	end
	return s
end

