--variables that scripts and the mod share (Var8000[n] of the mod: 0x8000 + n - 1)
local VAR_CHOICE = MPScriptNames.VAR_CHOICE         --the entry of a menu that was chosen (1 = first)
local VAR_ANSWER = MPScriptNames.VAR_ANSWER         --how the script ended: the mod reads it (Var8000[2])
local VAR_RESULT = MPScriptNames.VAR_RESULT         --answer of the game's own boxes
local VAR_SELECTED = MPScriptNames.VAR_SELECTED     --slot of the Pokemon that was chosen in the party screen (6 = none)
local VAR_SPECIES = MPScriptNames.VAR_SPECIES       --its species

--pieces of code that several scripts share
--a message with a YES / NO question. The answer for the mod is VAR_ANSWER: 2 = YES, 1 = NO (the game itself answers 1 = YES, 0 = NO)
local ASK_YESNO = [[
		pad                             -- (skipped by the loader)
		nop
		loadword 0, TEXT
		callstd MSGBOX_YESNO
		compare VAR_RESULT, 1           -- the game answers 1 = YES, 0 = NO: YES gives 2, NO gives 1
		goto_if LT, accepted
		setvar VAR_ANSWER, 2
		release
		end
	accepted:
		setvar VAR_ANSWER, 1
		release
		end
]]
--"the battle / trade starts now": text with automatic scrolling, then the game's own link start, a pause of 60 frames.
--The mod goes on when VAR_ANSWER is 2
local BATTLE_STARTS = [[
		pad
		nop
		nop
		messageautoscroll TEXT
		waitmessage
		special SPECIAL_LINK_START
		delay 0x3C
		setvar VAR_ANSWER, 2
		release
]]
--(not used by anything: the first byte is not skipped here, a loader would start behind it)
local LINK_BATTLE_PLAYER = [[
		special 0x20
		waitstate
		end
]]
--a message that closes by itself after A / B; VAR_ANSWER = 5 tells the mod that it is over
local SHOW_MESSAGE = [[
		pad
		nop
		loadword 0, TEXT
		callstd MSGBOX_AUTOCLOSE
		setvar VAR_ANSWER, 5
		release
		end
]]

MPScript(1, "Host Script (Unused)", {
	set = {[VAR_ANSWER] = 0, [0x8004] = 0},
	text = {
		en = "Would you like to enable\\nHide 'n Seek?",
		jp = "ウッド ユー ライク ター\\nエネーブル ハイド アンド シーク？",
		fr = "Souhaitez-vous activer\\nCache-cache?",
		de = "Möchtest du Hide 'n Seek\\naktivieren?",
		es = "¿Te gustaría habilitar\\nHide 'n Seek?",
		it = "Vuoi abilitare Nascondino?",
	},
	code = ASK_YESNO,
})

MPScript(2, "Interaction Menu Script", {
	set = {[VAR_CHOICE] = 0, [VAR_ANSWER] = 0, [VAR_RESULT] = 0},
	buffer2 = true,         --the name of the player that is talked to goes into \v\h03
	text = {
		en = "What would you like to do\\nwith \\v\\h03?",
		jp = "\\v\\h03 と なに を\\nしたい です か？",
		fr = "Que souhaitez-vous faire\\navec \\v\\h03?",
		de = "Was möchtest du mit \\v\\h03 machen?",
		es = "¿Qué te gustaría hacer con \\v\\h03?",
		it = "Cosa vorresti fare con \\v\\h03?",
	},
	choices = {                                      --15 bytes of text for each entry
		en = {"Battle", "Trade", "Card", "Exit"},
		jp = {"バトル", "トレード", "カード", "でぐち"},
		fr = {"Bataille", "Échange", "Carte", "Sortie"},
		de = {"Kampf", "Tauschen", "Karte", "Beenden"},
		es = {"Batalla", "Intercambio", "Tarjeta", "Salir"},
		it = {"Battaglia", "Scambiare", "Carta", "Uscita"},
	},
	code = [[
			pad lockall
			nop
			nop
			message TEXT
			waitmessage
			multichoice 0x15, 4, 2, 0
			copyvar VAR_CHOICE, VAR_RESULT
			addvar VAR_CHOICE, 1
			releaseall
			end
	]],
})

