--Machine code (thumb). The script only calls it (callnative); the routine is written to gNativeData first.
MPScript(24, "Generate Trainer Card to gSendBuffer", {
	--calls GenerateTrainerCard(gSendBuffer): the trainer card goes to the buffer that is normally used by the game's own
	--multiplayer send and receive
	code = [[
		callnative gNativeData + 1
		end
	]],
	native = function(A) return {
		0x4802B510,     --push {r4, lr}        ldr r0, =gSendBuffer
		0xF0004B02,     --ldr r3, =GenerateTrainerCard        bl (to the bx r3 below)
		0xBD10F805,     --pop {r4, pc}
		A.gSendBuffer,
		A.GenerateTrainerCard,
		0x46C04718,     --bx r3                nop
		0x46C04770,     --bx lr                nop
		0xFFFFFFFF,
	} end,
})

