	code = LINK_BATTLE_PLAYER,
})

MPScript(36, "Link Battle Player 4", {
	set = {[0x8005] = 3},
	code = LINK_BATTLE_PLAYER,
})

MPScript(37, "Initiate Link Player", {
	--sets gSpecialVar 0x8004 and 0x8005 to 1 and starts the task that the game starts for a wired cable club battle (CreateTask)
	--(the nops keep the two callnative pointers on word borders as they were)
	code = [[
		nop
		nop
		nop
		callnative InitLocalLinkPlayer + 1
		nop
		nop
		nop
		callnative gNativeData + 1
		end
	]],
	native = function(A) return {
		0x2101B500,     --push {lr}            movs r1, #1
		0x80014806,     --ldr r0, =var 0x8004  strh r1, [r0]
		0x80194B06,     --ldr r3, =var 0x8005  strh r1, [r3]
		0x21804A02,     --ldr r2, =CreateTask  movs r1, #0x80
		0x47104802,     --ldr r0, =Task_StartWiredCableClubBattle    bx r2
		0x4600BD00,     --pop {pc}            nop
		A.CreateTask + 1,
		A.Task_StartWiredCableClubBattle + 1,
		A.gSpecialVar_8000 + 4 * 2,
		A.gSpecialVar_8000 + 5 * 2,
	} end,
})

