function Help(page)
	local page = page or 1
	page = string.byte(safeStringChar(page))
	if page == 1 or page == 0 or page > 1 then
		console:log("Page 1/1. Type help(x) where x is page number to get more commands")
		console:log("->batflags(n) --Sets flags for battle. *n is number. If set, removes, otherwise adds. 0 sets it to empty")
		console:log("->heal(p, s) --Heal pokemon in position *p. If 0, heal all. *s is which team, 0 is player and 1 is enemy")
		console:log("->help(x) --Print help commands, with each page being *x. Defaults to page 1")
		console:log("->interact(x) --Interact with player *x")
		console:log("->levelcap(*x) --Set the level cap for flag LEVEL_CAP to *x level. if 0, default to 50")
		console:log("->pokemoncap(*x) --Set the pokemon cap for flag POKEMON_CAP to *x amount. if 0, default to 3")
	end
end

--Debug helper: prints the GBA display registers that decide blending / windows (call regs() in the scripting console)
function regs()
	local names = {{"DISPCNT", MPHw.IO + 0x00}, {"WIN0H", MPHw.IO + 0x40}, {"WIN1H", MPHw.IO + 0x42}, {"WIN0V", MPHw.IO + 0x44}, {"WIN1V", MPHw.IO + 0x46}, {"WININ", MPHw.IO + 0x48}, {"WINOUT", MPHw.IO + 0x4A}, {"MOSAIC", MPHw.IO + 0x4C}, {"BLDCNT", MPHw.IO + 0x50}, {"BLDALPHA", MPHw.IO + 0x52}, {"BLDY", MPHw.IO + 0x54}}
	for _, r in ipairs(names) do
		console:log(string.format("%-9s 0x%04X", r[1], emu:read16(r[2])))
	end
end

--Debug helper: prints decoded OAM entries (call oam(first, last) in the scripting console, e.g. oam(0, 25) for the game and oam(112, 127) for multiplayer players)
function oam(first, last)
	local first = first or 0
	local last = last or first
	local shapes = {[0] = "square", [1] = "wide", [2] = "tall"}
	local modes = {[0] = "normal", [1] = "TRANS", [2] = "OBJWIN", [3] = "?"}
	for i = first, last do
		local base = MPHw.OAM + i * 8
		local a0, a1, a2 = emu:read16(base), emu:read16(base + 2), emu:read16(base + 4)
		console:log(string.format("OAM %3d: %04X %04X %04X  y=%3d x=%3d shape=%s size=%d mode=%s affine=%d tile=%d prio=%d pal=%d", i, a0, a1, a2,
			a0 & 0xFF, a1 & 0x1FF, shapes[(a0 >> 14) & 3] or "?", (a1 >> 14) & 3, modes[(a0 >> 10) & 3], (a0 >> 8) & 3, a2 & 0x3FF, (a2 >> 10) & 3, (a2 >> 12) & 15))
	end
end

